INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10T-0159', 'HDSAT-RW-M10T-0159', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'The students drew the apparatus from three angles. ______, they labeled every part and compared their drawings with the original plans.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "As a result"}, {"id": "B", "text": "Then"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "Nevertheless"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10T-0159', 'B', ARRAY['B']::TEXT[], '''Then'' marks the second sentence marks the next step in time; the other options signal a different relationship.', '{"D": "''Nevertheless'' signals a relationship the two sentences do not have.", "A": "''As a result'' signals a relationship the two sentences do not have.", "C": "''For instance'' signals a relationship the two sentences do not have."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0000', 'HDSAT-RW-M10P-0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Along the California coast, purple sea urchins have multiplied in recent decades, grazing kelp holdfasts until once-dense forests become bare rock. Biologists note that the urchin boom followed the loss of sea otters, which eat urchins, to disease and historic hunting. Where otters remain, kelp persists; where they are absent, urchin barrens spread. Restoration trials that transplant otters have seen kelp return within a few years, but only where urchin densities were already low.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The presence of sea otters helps keep kelp forests from being overgrazed by urchins."}, {"id": "B", "text": "Transplanting sea otters restores kelp forests wherever they are attempted."}, {"id": "C", "text": "Sea urchins improve kelp growth by clearing competing algae from holdfasts."}, {"id": "D", "text": "Kelp forests are declining mainly because ocean temperatures have risen."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0000', 'A', ARRAY['A']::TEXT[], 'The passage links the loss of otters to an urchin boom and then to kelp loss, and it says otter transplants work only under limited conditions.', '{"C": "The text presents urchins as grazers that strip kelp, not as helpers.", "D": "Temperature is never offered as the cause; the otter loss is.", "B": "The text limits success to sites where urchin numbers were already low."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0001', 'HDSAT-RW-M10P-0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Roman harbour concrete has survived two millennia of wave action that erodes modern port cement in decades. Analysis of cores shows the material contains lumps of lime that were never fully mixed. When cracks form, water dissolves calcium from these lumps and precipitates new minerals that seal the crack. Engineers had long treated the lumps as evidence of sloppy mixing; they now regard them as a self-healing reservoir.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Modern port cement fails because it contains too much calcium."}, {"id": "B", "text": "Lime lumps once dismissed as a mixing flaw are what allow Roman harbour concrete to heal itself."}, {"id": "C", "text": "Roman concrete was weaker than modern cement but lasted longer by accident."}, {"id": "D", "text": "Roman builders deliberately added cracks to their concrete to test it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0001', 'B', ARRAY['B']::TEXT[], 'The core claim is a reversal: the lime lumps were read as a defect and are now understood to supply the mineral that seals cracks.', '{"C": "The text does not compare initial strength, only durability.", "A": "Calcium in the Roman lumps is described as helpful, not as a fault in modern cement.", "D": "Cracks are described as something the material repairs, not something builders created."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0002', 'HDSAT-RW-M10P-0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A returning honeybee that has found a rich patch of flowers performs a looping dance on the comb. The angle of the dance''s straight run relative to vertical encodes the direction of the flowers relative to the sun, and the duration encodes distance. Researchers who rotated a hive so that gravity no longer matched the sky found that recruits flew in the wrong direction, confirming that the bees read gravity, not the sun, while dancing in the dark.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Honeybees find flowers by following the scent of nectar through the hive."}, {"id": "B", "text": "The waggle dance conveys direction by using gravity as a stand-in for the position of the sun."}, {"id": "C", "text": "Bees can dance accurately only when they can see the sun directly."}, {"id": "D", "text": "The length of the dance tells other bees how many flowers are available."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0002', 'B', ARRAY['B']::TEXT[], 'The rotated-hive experiment is the decisive evidence: when gravity and sky disagree, the bees follow gravity, so direction is encoded against vertical.', '{"A": "Scent is not mentioned; the dance is the mechanism described.", "D": "Duration is said to encode distance, not abundance.", "C": "The experiment shows the dance works in darkness by using gravity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0003', 'HDSAT-RW-M10P-0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Measurements in several underground rail systems found particulate concentrations many times higher than at street level, largely from iron and brake dust ground from wheels and rails. The particles are coarse enough that most are trapped in the nose, but the smallest fraction penetrates deep into the lungs. Platform-edge screens and improved ventilation lowered concentrations substantially in stations where they were installed.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Most subway particles are fine enough to reach the deepest part of the lungs."}, {"id": "B", "text": "Subway particulate pollution comes mainly from train wear and can be reduced through station engineering."}, {"id": "C", "text": "Platform screens increase pollution by trapping air beside the track."}, {"id": "D", "text": "Subway air is cleaner than street air because trains produce no exhaust."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0003', 'B', ARRAY['B']::TEXT[], 'The passage names wheel and brake wear as the main source and then describes screens and ventilation as effective countermeasures.', '{"D": "The measurements show the opposite: concentrations many times higher than at street level.", "A": "The text says most particles are coarse and trapped in the nose.", "C": "Screens are listed as a measure that lowered concentrations."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0004', 'HDSAT-RW-M10P-0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Within fifty years of the movable-type press, European printers had issued millions of volumes, far more than scribes could have copied. The presses did not create a new reading public overnight. Instead, they made cheap ephemera such as pamphlets, indulgences and almanacs profitable, and those sales funded larger projects. Printers thus expanded literacy by selling what ordinary people already wanted to buy.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Scribes copied more books after the press was invented than before."}, {"id": "B", "text": "Early printers widened literacy by profiting first from inexpensive everyday material."}, {"id": "C", "text": "The printing press immediately produced a large new reading public."}, {"id": "D", "text": "Printers stayed in business by publishing only scholarly volumes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0004', 'B', ARRAY['B']::TEXT[], 'The argument is sequential: cheap ephemera sold well, those profits paid for bigger books, and literacy grew as a result.', '{"C": "The text explicitly denies that a reading public appeared overnight.", "A": "The text says presses produced far more than scribes could have copied.", "D": "Scholarly projects are described as funded by cheap sales, not as the main business."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0005', 'HDSAT-RW-M10P-0005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Antarctic ice preserves air bubbles from the atmosphere of past millennia. By measuring the ratio of oxygen isotopes in the ice itself and the trapped carbon dioxide in the bubbles, researchers reconstruct temperature and greenhouse gas levels for the same moment. The two records move together across eight glacial cycles, a correlation that has become central to climate models.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Climate models rely on ice cores because direct temperature measurements are unavailable today."}, {"id": "B", "text": "Ice cores provide a paired record of ancient temperature and carbon dioxide that supports climate modeling."}, {"id": "C", "text": "Air bubbles in ice contain only oxygen, not carbon dioxide."}, {"id": "D", "text": "Ice cores show that temperature and carbon dioxide levels are unrelated over long periods."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0005', 'B', ARRAY['B']::TEXT[], 'One core yields both signals for the same moment, and the correlation across glacial cycles is what makes the record useful for models.', '{"D": "The text says the two records move together.", "C": "Carbon dioxide in the bubbles is the second measurement described.", "A": "The cores reconstruct the past; the text does not claim present measurements are missing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0006', 'HDSAT-RW-M10P-0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Coffee leaf rust, a fungus, destroys the leaves that feed the bean. For decades, plantations planted a single high-yielding variety, and when the fungus arrived it swept through them. Farms that kept a mix of varieties lost less of their harvest, because the varieties differed in susceptibility. Breeders now cross wild coffee species with commercial plants to widen resistance.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Wild coffee species are too susceptible to be useful to breeders."}, {"id": "B", "text": "Genetic uniformity made coffee plantations vulnerable to rust, and mixing varieties reduces the loss."}, {"id": "C", "text": "Coffee rust spreads only between farms that grow several varieties."}, {"id": "D", "text": "High-yielding coffee varieties are naturally resistant to leaf rust."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0006', 'B', ARRAY['B']::TEXT[], 'The passage traces the damage to a single variety and then points to variety mixing and wild crosses as the response.', '{"D": "The single high-yielding variety is the one that was swept through.", "A": "Breeders use wild species precisely to widen resistance.", "C": "The text contrasts single-variety farms with mixed farms, not the other way round."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0007', 'HDSAT-RW-M10P-0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Brake and tire wear, not exhaust, now accounts for most of the particulate matter emitted by road traffic in cities that have tightened engine standards. These particles are heavier and tend to settle near roads, where they wash into drains with the first rain. Filters fitted to drainage outlets capture a large share before the water reaches rivers.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Drain filters remove pollution only after it has reached rivers."}, {"id": "B", "text": "Tire particles rise into the air and travel far from the roads where they form."}, {"id": "C", "text": "As exhaust emissions fell, non-exhaust particles became the main road-pollution problem, and drain filters can intercept them."}, {"id": "D", "text": "Exhaust emissions remain the largest source of traffic particles in regulated cities."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0007', 'C', ARRAY['C']::TEXT[], 'The first sentence shifts the source from exhaust to wear; the rest explains where those heavier particles go and how filters catch them.', '{"D": "The text says wear, not exhaust, now accounts for most of the particles.", "B": "The particles are described as heavier and settling near roads.", "A": "The filters are placed at outlets and act before the water reaches rivers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0008', 'HDSAT-RW-M10P-0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'For thousands of years, people in many fire-prone regions set small fires in cool seasons. These burns cleared litter and opened grassland, reducing the fuel that feeds large late-summer fires. When such burning was suppressed, forests thickened and catastrophic fires became more common. Land managers now reintroduce controlled burns, though the practice requires trained crews and favorable weather.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Large fires became less common after traditional burning stopped."}, {"id": "B", "text": "Controlled burns are easy to carry out in any weather once crews are trained."}, {"id": "C", "text": "Cool-season burning increased the amount of fuel available to late-summer fires."}, {"id": "D", "text": "Suppressing small traditional burns allowed fuel to build up and made large fires more likely."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0008', 'D', ARRAY['D']::TEXT[], 'The causal chain runs from small burns that removed fuel to suppression, thickening and larger fires, with reintroduction offered as a corrective.', '{"C": "The burns cleared litter, which reduced fuel.", "B": "The text stresses that the practice depends on trained crews and favorable weather.", "A": "The text says catastrophic fires became more common after suppression."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0009', 'HDSAT-RW-M10P-0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Lithium is extracted from brines pumped from beneath salt flats. The process evaporates water in shallow ponds over many months, leaving lithium salts behind. Because the same aquifers feed wetlands at the surface, pumping can lower water tables and alter the habitat. Direct-extraction technologies that return most of the water to the aquifer are being tested to reduce that impact.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Lithium is extracted from brine by heating it until the salts crystallise."}, {"id": "B", "text": "Salt-flat wetlands are unaffected by pumping because the aquifers are separate."}, {"id": "C", "text": "Direct extraction increases the amount of water lost to evaporation."}, {"id": "D", "text": "Brine extraction can harm wetlands by removing water, and new methods aim to return it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0009', 'D', ARRAY['D']::TEXT[], 'The key relationship is hydrological: the aquifer feeds both the brine and the wetland, so removal has a habitat cost that new methods try to reduce.', '{"A": "The text describes evaporation in shallow ponds, not heating.", "B": "The text says the same aquifers feed the wetlands.", "C": "Direct extraction is presented as returning water, not losing more."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0010', 'HDSAT-RW-M10P-0010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Iron gall ink, used for centuries on parchment, corrodes the paper from within as it ages: the iron and acid it contains attack cellulose. Conservators once treated affected pages with alkaline solutions, which slowed the decay but sometimes darkened the ink. Newer treatments use gels that deliver the same neutralising agent only to the ink lines, leaving the surrounding parchment untouched.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Gel treatments remove the ink from the page to protect the parchment."}, {"id": "B", "text": "Alkaline solutions were abandoned because they failed to slow decay at all."}, {"id": "C", "text": "A targeted gel treatment neutralises corrosive ink without damaging the rest of the page."}, {"id": "D", "text": "Iron gall ink is harmless once it has dried on parchment."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0010', 'C', ARRAY['C']::TEXT[], 'The passage contrasts a broad treatment that had a side effect with a precise one that confines the chemical to where it is needed.', '{"B": "The text says the solutions did slow decay, but sometimes darkened the ink.", "D": "The text describes the ink attacking cellulose as it ages.", "A": "The gel delivers a neutralising agent to the ink lines; it does not remove them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0011', 'HDSAT-RW-M10P-0011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Elephants produce rumbles below the range of human hearing. The low frequencies travel far and bend around obstacles, allowing herds kilometres apart to stay in contact. Recordings show that elephants respond to distant rumbles by orienting toward the source and answering, and that the calls carry differently in the morning than at midday, when the air is more turbulent.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Elephants use high-pitched calls that humans can hear easily."}, {"id": "B", "text": "Low-frequency rumbles let elephants communicate across long distances, and the air affects how well the sound travels."}, {"id": "C", "text": "Rumbles travel further at midday, when the air is warmer."}, {"id": "D", "text": "Elephants answer rumbles only after they see the caller."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0011', 'B', ARRAY['B']::TEXT[], 'The passage combines a physical advantage of low frequencies with observed responses and a note that atmospheric conditions change transmission.', '{"A": "The rumbles are described as below human hearing.", "C": "The text notes the calls carry differently at midday, when the air is turbulent.", "D": "Elephants orient toward the source and answer, without seeing the caller."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0012', 'HDSAT-RW-M10P-0012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Satellite measurements of surface temperature show that blocks with mature tree canopy can be several degrees cooler than treeless blocks nearby. The shade matters, but so does water: trees release vapour that cools the air. Because canopy takes decades to develop, cities that plant only saplings see little cooling for years, while a single large tree can shade a whole terrace.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Shade alone explains the temperature difference between treed and treeless blocks."}, {"id": "B", "text": "Mature tree canopy cools streets through shade and evaporation, and that effect takes decades to develop."}, {"id": "C", "text": "Planting saplings produces immediate cooling comparable to mature trees."}, {"id": "D", "text": "Trees warm the air by releasing vapour into it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0012', 'B', ARRAY['B']::TEXT[], 'The passage names two cooling mechanisms and then emphasises time: the benefit is tied to canopy size, which is why saplings do little at first.', '{"A": "The text says water, as well as shade, matters.", "C": "The text says saplings produce little cooling for years.", "D": "Vapour is described as cooling the air, not warming it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0013', 'HDSAT-RW-M10P-0013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Norse sagas describe sailors finding the sun on cloudy days with a crystal. Some translucent minerals split light into two beams whose relative brightness changes with the angle to polarised skylight; a navigator could rotate such a stone until the beams matched to locate the sun''s position. Experiments with calcite have reproduced the effect, though no such stone has been recovered from a Norse ship.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A polarising crystal could locate the sun in cloudy weather, though the evidence that Norse sailors used one is indirect."}, {"id": "B", "text": "Sagas are unreliable because they describe crystals that cannot exist."}, {"id": "C", "text": "Polarised skylight is visible only when the sky is completely clear."}, {"id": "D", "text": "Calcite has been found aboard several Norse ships, confirming how sailors navigated."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0013', 'A', ARRAY['A']::TEXT[], 'The passage sets a saga claim beside a demonstrable optical effect, then notes the missing physical evidence, which keeps the conclusion provisional.', '{"D": "The text says no such stone has been recovered from a Norse ship.", "B": "The effect has been reproduced with calcite, so such crystals do exist.", "C": "The whole point is that the technique works under cloud, when direct sunlight is hidden."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0014', 'HDSAT-RW-M10P-0014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Most antibiotics in use today were first found in soil microorganisms that produce them to compete with neighbors. That same soil is now a reservoir of resistance genes, many of them ancient and unrelated to clinical drug use. When resistance genes from soil bacteria spread into pathogens, treatments fail. Understanding how genes move between environments is therefore central to preserving the drugs.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Soil microorganisms no longer produce any of the antibiotics used today."}, {"id": "B", "text": "Pathogens cannot acquire resistance genes from soil bacteria."}, {"id": "C", "text": "Soil holds ancient resistance genes that can move into pathogens, so tracking that movement matters for medicine."}, {"id": "D", "text": "Resistance genes exist only because humans have used antibiotics in medicine."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0014', 'C', ARRAY['C']::TEXT[], 'The link is between the origin of antibiotics and the origin of resistance, with gene transfer as the route that turns a soil reservoir into a clinical problem.', '{"D": "The text says many soil resistance genes are ancient and unrelated to clinical use.", "A": "The text says most current antibiotics were first found in soil microorganisms.", "B": "The text describes exactly that spread as the reason treatments fail."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0015', 'HDSAT-RW-M10P-0015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Cement production releases carbon dioxide in two ways: fuel burned to heat kilns and the chemical reaction that converts limestone to clinker. Geopolymer binders avoid the limestone step, using aluminosilicate waste such as fly ash instead. They can cut emissions substantially, but their strength depends on the ash''s composition, which varies between power plants, so each batch must be tested.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Cement emissions come only from the fuel used to heat kilns."}, {"id": "B", "text": "Geopolymer binders produce more carbon dioxide than ordinary cement."}, {"id": "C", "text": "Geopolymer binders can cut cement emissions, but variable ash composition means each batch needs testing."}, {"id": "D", "text": "Fly ash has a consistent composition wherever it is produced."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0015', 'C', ARRAY['C']::TEXT[], 'The passage gives an environmental benefit and a practical constraint, and the constraint is the variability of the waste material.', '{"B": "The text says they can cut emissions substantially.", "D": "The text says composition varies between power plants.", "A": "The text names two sources: fuel and the limestone reaction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0016', 'HDSAT-RW-M10P-0016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Migrating birds often fly at night and orient partly by stars. Artificial light attracts and disorients them, drawing them toward cities where collisions with glass are common. Turning off upper-floor lights during peak migration nights reduces deaths measurably; one city''s program cut recorded collisions at a large tower by more than half during the weeks it operated.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Collisions with glass occur mainly during the day, when birds are active."}, {"id": "B", "text": "Birds migrate only on nights when the stars are hidden by city light."}, {"id": "C", "text": "Reducing night lighting during migration saves birds that are drawn off course by artificial light."}, {"id": "D", "text": "Turning off lights increases the number of birds drawn into cities."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0016', 'C', ARRAY['C']::TEXT[], 'The causal sequence runs from artificial light to disorientation to collisions, and the city program is the evidence that removing light reduces harm.', '{"B": "The text says birds orient partly by stars, not that they migrate only when stars are hidden.", "A": "The text links collisions to disorientation at night.", "D": "The program is reported as cutting collisions, not raising them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0017', 'HDSAT-RW-M10P-0017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Maya cities in the seasonal tropics depended on reservoirs that stored rainwater through the dry season. Sediment cores from one reservoir show layers of sand and clay laid down quickly, indicating that the floor was dredged repeatedly. The same cores show later layers of algae and eroded soil, suggesting the system was neglected as droughts intensified.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Reservoir sediments record a history of careful maintenance followed by neglect during worsening drought."}, {"id": "B", "text": "Maya cities relied on rivers rather than stored rainwater."}, {"id": "C", "text": "Algae layers show that the water became cleaner over time."}, {"id": "D", "text": "The reservoir was dredged only once, at the end of its use."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0017', 'A', ARRAY['A']::TEXT[], 'The core evidence is a change in sediment type, and the interpretation is a change from maintenance to neglect under drought.', '{"B": "The text says cities depended on reservoirs that stored rainwater.", "D": "Repeated dredging is inferred from repeated layers.", "C": "Algae and eroded soil are offered as signs of neglect and declining water quality."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0018', 'HDSAT-RW-M10P-0018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'During deep sleep, the brain replays sequences of activity recorded during learning, but faster. This replay occurs alongside slow waves that coordinate the hippocampus and cortex. When researchers disrupted those waves in sleeping volunteers, the volunteers remembered fewer of the word pairs they had studied, even though their total sleep time was unchanged.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Replay during sleep erases the sequences recorded during learning."}, {"id": "B", "text": "Memory depends mainly on how many hours a person sleeps."}, {"id": "C", "text": "Slow-wave activity during sleep helps consolidate what was learned, independent of total sleep time."}, {"id": "D", "text": "The hippocampus is inactive during deep sleep."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0018', 'C', ARRAY['C']::TEXT[], 'The experiment holds sleep time constant and changes only the waves, which isolates slow-wave activity as the factor that matters.', '{"B": "The disrupted-wave group remembered less with the same total sleep, so hours alone are not the factor.", "A": "Replay is described as strengthening, not erasing, learned sequences.", "D": "The text says the waves coordinate the hippocampus with the cortex."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0019', 'HDSAT-RW-M10P-0019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'At deep-sea vents, seawater heated by magma carries dissolved metals and hydrogen sulphide. Where the fluid meets cold seawater, minerals precipitate and build chimneys. Microbes there use chemical energy instead of sunlight, supporting tube worms and crabs. Because similar conditions may exist beneath the ice of other worlds, vents are a target in the search for life beyond Earth.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Tube worms at vents feed directly on sunlight filtered through the water."}, {"id": "B", "text": "Deep-sea vents are formed by cold seawater dissolving minerals."}, {"id": "C", "text": "Vents are studied mainly because they contain no living organisms."}, {"id": "D", "text": "Vent ecosystems run on chemical energy rather than sunlight, which makes them a model for life elsewhere."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0019', 'D', ARRAY['D']::TEXT[], 'The passage describes a food web founded on chemistry, then draws the astrobiological implication from the possibility of similar conditions elsewhere.', '{"B": "The fluid is heated by magma, and minerals precipitate when it meets cold water.", "A": "The text says the microbes use chemical energy instead of sunlight.", "C": "The text describes a community of microbes, worms and crabs."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0020', 'HDSAT-RW-M10P-0020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Sea ice forms by rejecting salt, which concentrates impurities in narrow brine channels. Microplastics carried north by currents become trapped in those channels, so ice can hold far more particles per liter than the water beneath it. When the ice melts in spring, the particles are released into surface water precisely where plankton bloom.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sea ice concentrates microplastics and releases them in spring where plankton are blooming."}, {"id": "B", "text": "Sea ice filters microplastics out of the ocean and stores them permanently."}, {"id": "C", "text": "Plankton blooms occur in winter, after the ice has formed."}, {"id": "D", "text": "Microplastics are less concentrated in sea ice than in the water below it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0020', 'A', ARRAY['A']::TEXT[], 'Two mechanisms combine: brine channels trap particles, and spring melt releases them at the moment and place where plankton are most active.', '{"B": "The ice releases the particles when it melts rather than storing them permanently.", "D": "The text says ice can hold far more particles per liter.", "C": "The release is described as happening in spring, when plankton bloom."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0021', 'HDSAT-RW-M10P-0021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Wind turbine blades are built from glass fibres set in resin, a composite that is strong and light but hard to separate. Most retired blades are buried or burned. New methods dissolve the resin so the fibres can be reused, or replace it with a thermoplastic that can be melted and remoulded. Each approach must still compete with the low cost of making a new blade.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Thermoplastic resins make blades impossible to remould."}, {"id": "B", "text": "Burying blades is now more expensive than recycling them."}, {"id": "C", "text": "Recycling retired blades is technically possible, but the economics must improve for it to replace disposal."}, {"id": "D", "text": "Turbine blades are made of a single material that is easy to recycle."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0021', 'C', ARRAY['C']::TEXT[], 'The passage presents two recycling routes and then names cost as the barrier, so the conclusion is technical feasibility with an economic caveat.', '{"D": "The blades are a composite of glass fibre and resin, which is why separation is difficult.", "B": "The text says recycling must compete with low-cost new blades and does not claim burial is pricier.", "A": "A thermoplastic is described as meltable and remouldable."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0022', 'HDSAT-RW-M10P-0022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Romans sweetened wine by boiling it in lead vessels. The resulting syrup was concentrated and sweet, and the lead it picked up was consumed in quantity. Skeletal remains from some Roman sites show elevated lead, though the contribution of any single source is debated. Archaeologists therefore treat sapa as one exposure among several, including water pipes and cosmetics.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Lead-sweetened syrup was a real source of exposure but one of several that archaeologists must weigh together."}, {"id": "B", "text": "Roman wine contained no lead because the vessels were lined with tin."}, {"id": "C", "text": "Skeletal remains show that lead exposure was limited to a single source."}, {"id": "D", "text": "Archaeologists agree that water pipes were the only source of Roman lead exposure."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0022', 'A', ARRAY['A']::TEXT[], 'The passage accepts the exposure but frames it as one contributor among several whose relative weight remains uncertain.', '{"B": "The text says the syrup picked up lead from the vessels.", "C": "The text says the contribution of any single source is debated.", "D": "Pipes are listed as one of several sources, not the only one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0023', 'HDSAT-RW-M10P-0023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Some orchids produce no nectar but resemble the females of a particular bee species in shape, color and scent. Males attempt to mate with the flower and carry pollen away. The mimicry works only if the orchid is rarer than the bee; when orchids become common, males learn to avoid them and pollination falls. This frequency dependence helps explain why such orchids remain sparse.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The orchids attract bees by offering a large supply of nectar."}, {"id": "B", "text": "Male bees learn to prefer orchids once the flowers become common."}, {"id": "C", "text": "Orchids are abundant because mimicry becomes more effective as they multiply."}, {"id": "D", "text": "Orchid mimicry succeeds only while the flowers stay rarer than the bees they imitate."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0023', 'D', ARRAY['D']::TEXT[], 'The dependence on relative frequency is the central claim, and it explains the observed scarcity rather than contradicting it.', '{"A": "The orchids produce no nectar.", "B": "Males learn to avoid the flowers when they become common.", "C": "The text says pollination falls as orchids multiply, which keeps them sparse."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0024', 'HDSAT-RW-M10P-0024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'People learning a new motor skill improve quickly at first, then plateau, then improve again after a night''s sleep. Brain imaging shows that the sleeping brain replays the movement, strengthening the connections that support it. Practising a slightly different version of the movement before sleep can improve the original more than repeating the same movement, a phenomenon called variability training.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Motor learning stops once a person reaches a plateau."}, {"id": "B", "text": "Sleep consolidates motor learning, and varied practice before sleep can strengthen the original skill."}, {"id": "C", "text": "Brain imaging shows no activity related to movement during sleep."}, {"id": "D", "text": "Repeating exactly the same movement is the most effective way to improve it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0024', 'B', ARRAY['B']::TEXT[], 'The passage joins a sleep effect to a practice effect: replay during sleep supports consolidation, and variation before sleep appears to enhance it.', '{"A": "The text says improvement resumes after sleep following a plateau.", "D": "The text reports that a slightly different movement can help more than exact repetition.", "C": "The text says the sleeping brain replays the movement."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0025', 'HDSAT-RW-M10P-0025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Mangrove roots slow water and trap sediment, raising the seabed over time. During storms, the dense stems and roots absorb wave energy before it reaches the shore. Studies after cyclones find less damage behind wide mangrove belts than behind cleared shoreline, though a narrow fringe offers little protection against the largest surges.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A narrow fringe of mangroves prevents damage from even the largest surges."}, {"id": "B", "text": "Mangroves increase wave energy by funnelling water toward the shore."}, {"id": "C", "text": "Wide mangrove belts reduce storm damage, though a thin fringe provides little protection."}, {"id": "D", "text": "Mangrove roots prevent sediment from accumulating on the seabed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0025', 'C', ARRAY['C']::TEXT[], 'The passage links protection to the width of the belt and explicitly limits what a narrow fringe can do against extreme surges.', '{"B": "The text says the roots absorb wave energy.", "A": "The text says a narrow fringe offers little protection against the largest surges.", "D": "The text says the roots trap sediment and raise the seabed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0026', 'HDSAT-RW-M10P-0026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Tablets from a Mesopotamian archive record grain deliveries, receipts and loans. Because scribes dated many tablets by the regnal year of a king, the archive lets historians reconstruct prices and wages across decades. Some tablets were later reused as filler in walls, and their order in the rubble has to be reconstructed before the records can be read as a series.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Once their order is reconstructed, the tablets yield a long-run economic record."}, {"id": "B", "text": "The archive contains only religious texts with no economic information."}, {"id": "C", "text": "The tablets are useless because they were reused as building material."}, {"id": "D", "text": "Scribes dated tablets by the harvest rather than by a king''s reign."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0026', 'A', ARRAY['A']::TEXT[], 'The value depends on sequence: dating by regnal year plus physical reconstruction turns individual receipts into a series covering decades.', '{"C": "The reuse is a problem to solve, not a reason the tablets are useless.", "B": "The tablets record deliveries, receipts and loans.", "D": "The text says scribes used the regnal year of a king."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0027', 'HDSAT-RW-M10P-0027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Legumes such as clover host bacteria that convert atmospheric nitrogen into forms plants can use. Sowing them between cash crops adds nitrogen to the soil, reducing fertiliser need. But the cover must be killed before it competes with the next crop, and in dry regions it can consume water that the cash crop needs. Farmers therefore choose species and timing by climate.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Water availability has no effect on which cover crop a farmer chooses."}, {"id": "B", "text": "Cover crops remove nitrogen from the soil and increase fertiliser needs."}, {"id": "C", "text": "Cover crops can be left growing through the cash crop without any cost."}, {"id": "D", "text": "Legume cover crops add nitrogen but must be managed for water and competition, so the choice depends on climate."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0027', 'D', ARRAY['D']::TEXT[], 'The passage sets a benefit against two costs, water use and competition, and concludes that local climate governs the decision.', '{"B": "The legumes add nitrogen, reducing fertiliser need.", "C": "The text says the cover must be killed before it competes with the next crop.", "A": "The text says farmers choose species and timing by climate, including dryness."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0028', 'HDSAT-RW-M10P-0028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A moving bicycle stays upright without a rider. For years the explanation was gyroscopic effect: spinning wheels resist tipping. Experiments with counter-rotating wheels that cancel the gyroscopic effect showed the bicycle still stabilised itself, but only at sufficient speed. Steering geometry that lets the front wheel turn toward a lean turns out to be the key.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A bicycle stabilises itself at any speed, including when stationary."}, {"id": "B", "text": "Counter-rotating wheels make a bicycle more stable than ordinary wheels."}, {"id": "C", "text": "Steering geometry, rather than wheel spin alone, is what keeps a moving bicycle upright."}, {"id": "D", "text": "Gyroscopic effect is the only reason a bicycle stays upright."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0028', 'C', ARRAY['C']::TEXT[], 'The experiment is designed to eliminate one explanation, and the surviving explanation is the steering geometry that turns the wheel into a lean.', '{"D": "The counter-rotating experiment removed the gyroscopic effect and the bicycle still stabilised.", "A": "The text says stabilisation requires sufficient speed.", "B": "The counter-rotating wheels canceled the effect, which was done to test, not to improve, stability."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0029', 'HDSAT-RW-M10P-0029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Coral fragments grown on underwater frames can be replanted onto damaged reefs. Survival is highest when fragments come from the same reef and are planted in dense clusters, because nearby corals share water flow and can fuse. Restoration is expensive per hectare, however, and cannot offset warming unless the underlying stress is reduced.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Coral restoration can work locally but is costly and cannot substitute for reducing the stress that kills reefs."}, {"id": "B", "text": "Fragments from distant reefs survive better than local fragments."}, {"id": "C", "text": "Planting corals far apart improves their survival."}, {"id": "D", "text": "Restoration alone is enough to offset rising ocean temperatures."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0029', 'A', ARRAY['A']::TEXT[], 'The passage gives practical conditions for success and then a limit: local replanting does not address the warming that drives loss.', '{"B": "The text says survival is highest when fragments come from the same reef.", "C": "The text says dense clusters survive best.", "D": "The text says restoration cannot offset warming without reducing the stress."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0030', 'HDSAT-RW-M10P-0030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Many vaccines lose potency if they freeze or overheat. In rural clinics without reliable power, keeping them between two and eight degrees is difficult. Solar direct-drive refrigerators use panels and ice banks instead of batteries, so they keep working through cloudy days. Their main constraint is that the panels must be sized for the worst week of the year, not the average.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Solar refrigerators can protect vaccines without reliable power, but they must be sized for the worst conditions."}, {"id": "B", "text": "Panels sized for average conditions are sufficient for a clinic."}, {"id": "C", "text": "Solar refrigerators depend on batteries that fail during cloudy weather."}, {"id": "D", "text": "Vaccines remain effective at any temperature as long as they stay dry."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0030', 'A', ARRAY['A']::TEXT[], 'The passage explains the design that avoids batteries and then names the sizing rule that makes it reliable in bad weather.', '{"D": "The text says many vaccines lose potency if they freeze or overheat.", "C": "The text says the units use ice banks instead of batteries.", "B": "The text says panels must be sized for the worst week, not the average."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0031', 'HDSAT-RW-M10P-0031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'To slow desertification at the edge of dunes, crews set fences of woven reeds perpendicular to the prevailing wind. Sand piles up behind each fence, forming a ridge that stabilises the surface. Once the ridge holds, grasses can be planted, and their roots bind the sand further. The fences themselves decay within a few years, but by then the vegetation has taken over.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Grasses are planted before any sand has accumulated behind the fence."}, {"id": "B", "text": "Fences are built parallel to the wind to spread sand evenly."}, {"id": "C", "text": "Temporary fences create the conditions for vegetation that then stabilises the dune permanently."}, {"id": "D", "text": "Reed fences must be replaced every year to keep a dune stable."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0031', 'C', ARRAY['C']::TEXT[], 'The sequence is fence, ridge, grass, roots, and the conclusion is that the temporary structure is replaced by a living one.', '{"D": "The text says the fences decay within a few years and vegetation takes over.", "A": "The text says grasses are planted once the ridge holds.", "B": "The text says the fences are set perpendicular to the prevailing wind."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0032', 'HDSAT-RW-M10P-0032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The Bay of Fundy has some of the world''s largest tides. Tidal turbines convert the moving water into electricity, but the resource is intermittent in a different way from wind: the tide follows the moon and is predictable decades ahead. Designers can therefore plan output, though the strongest currents last only a few hours around each slack.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The strongest currents at the Bay of Fundy last for most of the day."}, {"id": "B", "text": "Tidal turbines generate electricity only when the tide is slack."}, {"id": "C", "text": "Tidal power is highly predictable but available only in short windows around each tide."}, {"id": "D", "text": "Tidal power is less predictable than wind because the moon''s orbit varies."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0032', 'C', ARRAY['C']::TEXT[], 'The passage contrasts predictability with availability: the timing is known far in advance, but the usable current is brief.', '{"D": "The text says the tide is predictable decades ahead, unlike wind.", "A": "The text says strong currents last only a few hours around each slack.", "B": "The turbines use moving water; slack water is when the current is weakest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0033', 'HDSAT-RW-M10P-0033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Insects colonise a body in a predictable order, and the development of each species depends on temperature. An investigator who knows the temperature history of the site can estimate how long a body has been exposed. The method is most reliable in warm weather and least reliable indoors or in winter, when development slows and the sequence is harder to read.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Cold weather speeds insect development and improves estimates."}, {"id": "B", "text": "The order in which insects arrive is random and cannot be used."}, {"id": "C", "text": "Insect development can estimate time since death, but its accuracy depends on temperature and setting."}, {"id": "D", "text": "Insect evidence is equally reliable indoors and outdoors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0033', 'C', ARRAY['C']::TEXT[], 'The passage explains the method through temperature-dependent development and then names the conditions that undermine it.', '{"D": "The text says the method is least reliable indoors or in winter.", "A": "The text says development slows in winter.", "B": "The text says insects colonise in a predictable order."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0034', 'HDSAT-RW-M10P-0034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'A concert hall''s acoustics depend less on its size than on how quickly sound decays and how it reflects. Surfaces that diffuse sound scatter reflections in many directions, giving the audience a sense of envelopment. A hall designed with too much absorption sounds clear but dry; one with too little sounds muddy. Designers therefore balance reflective and absorptive surfaces carefully.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Good hall acoustics come from balancing reflected and absorbed sound rather than from size alone."}, {"id": "B", "text": "Diffusing surfaces concentrate reflections in a single direction."}, {"id": "C", "text": "Adding as much absorption as possible produces the clearest sound."}, {"id": "D", "text": "Larger halls always sound better than smaller ones."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0034', 'A', ARRAY['A']::TEXT[], 'The passage rejects size as the main factor and frames design as a balance between two extremes, each with a distinct flaw.', '{"D": "The text says acoustics depend less on size than on decay and reflection.", "C": "The text says too much absorption leaves a hall dry.", "B": "Diffusing surfaces scatter sound in many directions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0035', 'HDSAT-RW-M10P-0035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'A vault in the Arctic permafrost stores seeds at minus eighteen degrees, cold enough to slow ageing for decades. But the vault is a backup, not a working collection: seeds must periodically be grown out to produce fresh, viable samples. The greatest threat to stored seeds is not the cold failing but the samples being too few, so that repeated regeneration narrows their genetic diversity.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The main danger to stored seeds is a failure of the refrigeration."}, {"id": "B", "text": "Repeated regeneration increases the genetic diversity of a sample."}, {"id": "C", "text": "A seed vault preserves samples only if they are periodically regenerated, and small samples lose diversity over time."}, {"id": "D", "text": "The vault keeps seeds alive indefinitely without any need for regeneration."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0035', 'C', ARRAY['C']::TEXT[], 'The passage corrects a common assumption: the risk is not the freezer but the genetics of a small sample renewed too often.', '{"D": "The text says seeds must periodically be grown out for fresh samples.", "A": "The text says the greatest threat is too few samples, not the cold failing.", "B": "The text says repeated regeneration narrows diversity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0036', 'HDSAT-RW-M10P-0036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Roman aqueducts ran for tens of kilometres with gradients of only a fraction of a percent. Keeping that slope exact required surveying with levels and cords over difficult ground, and the channels were built with a slight covering to keep out sun and debris. Modern surveys show sections that descend too steeply to have flowed, suggesting some were never completed.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Modern surveys show that every aqueduct section once carried water."}, {"id": "B", "text": "The channels were left open to the sky to keep the water cool."}, {"id": "C", "text": "Roman aqueducts were built with steep gradients to increase water speed."}, {"id": "D", "text": "Aqueducts demanded precise surveying, and some surviving sections suggest unfinished rather than working channels."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0036', 'D', ARRAY['D']::TEXT[], 'The passage pairs an engineering requirement with physical evidence that not every surviving stretch met it, which changes how those stretches are read.', '{"C": "The text says gradients were only a fraction of a percent.", "B": "The text says the channels had a covering to keep out sun and debris.", "A": "The text says some sections descend too steeply to have flowed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0037', 'HDSAT-RW-M10P-0037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Streetlights attract insects, and bats that hunt insects gather under them. But some species avoid light, and the ones that tolerate it may arrive late and feed on already-depleted swarms. Surveys along lit and unlit paths find different species compositions, with light-averse bats retreating to dark corridors. Lighting redesign that shields the bulb can reduce the shift.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Insects are repelled by streetlights, leaving bats with less food."}, {"id": "B", "text": "All bat species benefit equally from street lighting."}, {"id": "C", "text": "Shielding a bulb increases the area lit by a streetlight."}, {"id": "D", "text": "Street lighting helps some bats and displaces others, and shielded fixtures can limit the disruption."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0037', 'D', ARRAY['D']::TEXT[], 'The passage sets a benefit for tolerant bats against a cost for light-averse ones and then names a design change that lessens the divide.', '{"B": "The text distinguishes tolerant species from light-averse ones.", "A": "The text says lights attract insects.", "C": "Shielding is offered as a way to reduce the ecological shift."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0038', 'HDSAT-RW-M10P-0038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Recycled glass melts at a lower temperature than raw materials, so using it saves energy. Contamination by ceramics or heat-resistant glass, however, raises the melting point and can ruin a whole batch. Sorting technology that identifies materials by their optical properties has improved recovery, but collection systems that mix colors still limit what can be remade into new containers.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Glass recycling saves energy, but contamination and mixed colors limit how much can be remade."}, {"id": "B", "text": "Sorting by optical properties has made color mixing unnecessary."}, {"id": "C", "text": "Ceramics lower the melting point and improve the recycling process."}, {"id": "D", "text": "Recycled glass requires more energy to melt than raw materials."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0038', 'A', ARRAY['A']::TEXT[], 'The passage gives the energy benefit and then two practical limits, one at the material level and one in collection.', '{"D": "The text says recycled glass melts at a lower temperature.", "C": "The text says ceramics raise the melting point and can ruin a batch.", "B": "The text says mixed colors still limit what can be remade."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0039', 'HDSAT-RW-M10P-0039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Seismic waves travel more slowly than the electronic signals that carry a warning. Sensors near an epicentre can detect the first, faster waves and send an alert ahead of the slower, damaging waves. The warning lasts only seconds near the source, but it is enough to stop trains and open fire doors. The system''s value depends on dense sensors and fast processing.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The system is valuable mainly because it predicts when an earthquake will occur."}, {"id": "B", "text": "Early warning works by detecting fast waves and outrunning the slower damaging ones, and it depends on sensor density."}, {"id": "C", "text": "The slower waves arrive first and give the system time to react."}, {"id": "D", "text": "Earthquake warnings reach distant cities before they reach nearby towns."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0039', 'B', ARRAY['B']::TEXT[], 'The mechanism is a race between wave speeds, and the practical value depends on detecting the first waves quickly and processing them fast.', '{"D": "The text says warnings last only seconds near the source.", "C": "The faster waves arrive first and trigger the alert before the damaging waves.", "A": "The text does not claim prediction of earthquakes, only warning after they begin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0040', 'HDSAT-RW-M10P-0040', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Lichen absorbs water and nutrients directly through its surface, so it accumulates airborne elements rather than filtering them. Surveys find that lichen communities near smelters are dominated by a few tolerant species, while sensitive species disappear. Researchers sampling lichen tissue at various distances from a smelter found metal concentrations declining with distance. This pattern suggests that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the composition of a lichen community can serve as a measure of airborne metal pollution"}, {"id": "B", "text": "lichen grows faster near smelters because metals are nutrients"}, {"id": "C", "text": "sensitive lichen species are more tolerant of pollution than dominant ones"}, {"id": "D", "text": "airborne metals are deposited evenly at every distance from a smelter"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0040', 'A', ARRAY['A']::TEXT[], 'Tissue concentrations and species composition both change with distance from the source, so the community itself records the exposure.', '{"B": "The sensitive species disappear near smelters, which does not suggest faster growth.", "C": "The text calls the sensitive species sensitive and the survivors tolerant.", "D": "The measurements show a decline with distance, not even deposition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0041', 'HDSAT-RW-M10P-0041', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Prairie voles form lasting pairs, and their brains release oxytocin when they are together. Blocking oxytocin receptors prevents pair formation, while boosting them speeds it. In a related species that does not form pairs, the same receptors are distributed differently in the brain. These findings indicate that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "where oxytocin receptors sit in the brain may matter as much as whether they are present"}, {"id": "B", "text": "oxytocin prevents pair formation in all rodent species"}, {"id": "C", "text": "pair bonding depends on a receptor that prairie voles lack"}, {"id": "D", "text": "the related species forms pairs but does so more slowly"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0041', 'A', ARRAY['A']::TEXT[], 'The comparison isolates receptor location as the difference between a pair-forming and a non-pair-forming species.', '{"B": "Boosting oxytocin speeds pair formation rather than preventing it.", "D": "The related species is described as not forming pairs.", "C": "Prairie voles have the receptor; the difference is its distribution."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0042', 'HDSAT-RW-M10P-0042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Concrete gains strength as cement reacts with water. Below about five degrees Celsius the reaction slows sharply, and if fresh concrete freezes, ice expands and cracks it permanently. Builders therefore add accelerators or insulate the forms in cold weather. These precautions suggest that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "concrete gains strength faster when it freezes"}, {"id": "B", "text": "concrete placed in freezing weather needs protection until it has gained enough strength to resist damage"}, {"id": "C", "text": "accelerators remove the need to insulate concrete in cold weather"}, {"id": "D", "text": "concrete placed in cold weather never reaches full strength"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0042', 'B', ARRAY['B']::TEXT[], 'The harm occurs while the concrete is fresh and weak, so protection is needed until it can survive a freeze.', '{"A": "Freezing cracks fresh concrete, which is damage rather than strength gain.", "C": "Accelerators and insulation are listed as alternatives, so accelerators do not replace insulation.", "D": "The text describes slowed reaction and damage, not a permanent ceiling."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0043', 'HDSAT-RW-M10P-0043', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Wood buried in seabed sediment without oxygen is attacked only slowly by microbes. When erosion exposes the timbers, oxygen returns and decay accelerates. Conservators therefore rebury exposed wreck sites or cover them with sand. This practice implies that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "microbes cannot survive in seabed sediment at all"}, {"id": "B", "text": "excavation is the only way to preserve a wreck permanently"}, {"id": "C", "text": "leaving a wreck buried can protect it better than exposing it for study"}, {"id": "D", "text": "oxygen slows the decay of waterlogged wood"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0043', 'C', ARRAY['C']::TEXT[], 'The reasoning follows the decay mechanism: if oxygen drives decay, then keeping oxygen out by reburial preserves the wood.', '{"D": "Oxygen returns with exposure and decay accelerates.", "B": "The text describes reburial, not excavation, as a preservation measure.", "A": "The text says microbes attack slowly without oxygen, not that they are absent."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0044', 'HDSAT-RW-M10P-0044', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Bats deposit guano in caves, and insects and fungi break it down. Isotope analysis of guano layers shows shifts that match changes in the surrounding vegetation, and a core from a cave floor preserves a sequence of such layers thousands of years deep. Investigators therefore use guano cores to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "show that bats prefer guano from a single plant species"}, {"id": "B", "text": "reconstruct how the vegetation around a cave changed over time"}, {"id": "C", "text": "measure the current population of bats in the cave"}, {"id": "D", "text": "date the formation of the cave itself"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0044', 'B', ARRAY['B']::TEXT[], 'Because guano isotopes track vegetation and the core preserves layers in order, the core is a dated environmental archive.', '{"C": "A layer sequence records the past, not a present count.", "D": "The layers date accumulation, not the origin of the cave.", "A": "The text describes shifts in vegetation generally, not a single preferred species."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0045', 'HDSAT-RW-M10P-0045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Green tea is heated soon after picking, which stops the oxidation that darkens leaves. Black tea is rolled and left to oxidise. The same cultivar can produce either tea depending on how it is handled after harvest. This comparison indicates that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "green tea comes from a different species than black tea"}, {"id": "B", "text": "black tea is heated sooner after picking than green tea"}, {"id": "C", "text": "oxidation is required to make green tea"}, {"id": "D", "text": "the difference between green and black tea lies mainly in processing rather than in the plant"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0045', 'D', ARRAY['D']::TEXT[], 'The shared cultivar is the controlling fact: identical plants diverge because one is heated and the other oxidised.', '{"A": "The text says the same cultivar can produce either tea.", "C": "Heating stops oxidation, which is what makes green tea.", "B": "Black tea is left to oxidise; green tea is heated soon after picking."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0046', 'HDSAT-RW-M10P-0046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Pack rats collect plant material and urinate on it, creating hard middens that preserve fragments for thousands of years. Middens in dry caves contain twigs from species that no longer grow nearby, and the layers can be dated. Researchers studying such middens can therefore infer ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "that the species found in the midden still grow nearby today"}, {"id": "B", "text": "which plant species grew near the cave under earlier climate conditions"}, {"id": "C", "text": "how many pack rats currently live in the cave"}, {"id": "D", "text": "that the cave climate has remained unchanged for thousands of years"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0046', 'B', ARRAY['B']::TEXT[], 'Datable layers of preserved plants that are locally absent together support a picture of past vegetation and therefore past climate.', '{"C": "The middens record the past; they do not count present animals.", "D": "Species that no longer grow nearby imply a changed climate, not an unchanged one.", "A": "The text says those species no longer grow nearby."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0047', 'HDSAT-RW-M10P-0047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Navigators in the Pacific learned to read swells reflected by islands and the flight paths of seabirds returning to land at dusk. A bird flying in a straight line at dusk is likely heading toward its roost, while birds that circle are likely still searching. A navigator who sees a steady line of birds can therefore ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "follow circling birds to reach an island faster"}, {"id": "B", "text": "assume the birds have found no land and turn back"}, {"id": "C", "text": "ignore the birds because they fly only during the day"}, {"id": "D", "text": "use their direction of flight as a clue to where land lies"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0047', 'D', ARRAY['D']::TEXT[], 'A straight line at dusk signals a roost, so the flight direction points toward land that the navigator cannot yet see.', '{"B": "A steady line implies a destination, not a failure to find one.", "A": "Circling birds are described as still searching.", "C": "The observation is made at dusk, when the birds are flying."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0048', 'HDSAT-RW-M10P-0048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Capacitance sensors estimate soil moisture from the dielectric properties of soil. Salinity changes those properties too, so a sensor reading in a saline soil reflects both water and dissolved salt. Readings from such soils must therefore be ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "discarded entirely, since no soil measurement is possible"}, {"id": "B", "text": "interpreted as showing less water than is actually present in every case"}, {"id": "C", "text": "used without adjustment because salinity has no effect on capacitance"}, {"id": "D", "text": "corrected for salinity before they are treated as a measure of water content"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0048', 'D', ARRAY['D']::TEXT[], 'The confound is named explicitly, so the inference is a calibration step rather than a claim about which way the error runs.', '{"C": "The text says salinity changes the same properties the sensor reads.", "A": "The text calls for correction, not for abandoning measurement.", "B": "The direction of the error is not stated, so a universal over- or under-estimate cannot be inferred."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0049', 'HDSAT-RW-M10P-0049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'In a nineteenth-century maternity ward, the death rate from fever was higher among patients attended by physicians than among those attended by midwives. The physicians also performed autopsies before their ward rounds, while the midwives did not. An observer who noticed this pattern might reasonably conclude that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "midwives were better trained than physicians in every respect"}, {"id": "B", "text": "something carried from the autopsy room may have contributed to the fever"}, {"id": "C", "text": "autopsies were performed in order to treat the fever"}, {"id": "D", "text": "the fever was caused by the patients'' living conditions alone"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0049', 'B', ARRAY['B']::TEXT[], 'The one difference that tracks the death rate is the physicians'' contact with autopsies, which points to transmission from that contact.', '{"A": "The comparison concerns fever deaths, not overall training.", "D": "Living conditions are not mentioned and cannot explain the difference between the two wards.", "C": "Autopsies are presented as preceding ward rounds, not as treatment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0050', 'HDSAT-RW-M10P-0050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Owls fly almost silently. Their flight feathers have a comb-like leading edge and a soft trailing fringe that break up the turbulent air flowing over the wing. In wind-tunnel tests, wings with these features produced less noise than smooth wings at the same speed. The feather structure therefore appears to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "reduce the noise created by airflow over the wing"}, {"id": "B", "text": "increase the speed at which the owl can fly"}, {"id": "C", "text": "make the wing heavier and more rigid"}, {"id": "D", "text": "produce a louder call for communication"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0050', 'A', ARRAY['A']::TEXT[], 'Because the test varies only the feather features at a fixed speed, the reduced noise can be attributed to the structure.', '{"B": "Speed is held constant in the comparison; noise is the measured difference.", "C": "The features are described as structural and soft, not as adding rigidity.", "D": "The passage concerns flight noise, not vocal calls."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0051', 'HDSAT-RW-M10P-0051', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Paper made from wood pulp contains lignin, which yellows and embrittles as it oxidises. Papers made from cotton rags lack lignin and remain flexible for centuries. Conservators who want to slow the deterioration of a wood-pulp document therefore usually ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "add lignin to the paper to strengthen it"}, {"id": "B", "text": "replace the document with a cotton-rag copy and discard the original"}, {"id": "C", "text": "store the document in bright light to stop oxidation"}, {"id": "D", "text": "treat the paper to remove or neutralise the lignin and the acids it produces"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0051', 'D', ARRAY['D']::TEXT[], 'The contrast with lignin-free cotton paper identifies lignin as the agent of decay, which is what treatment would target.', '{"A": "Lignin is the cause of the yellowing and embrittlement.", "C": "Light accelerates oxidation rather than stopping it.", "B": "The question asks how to slow deterioration of the document, not how to replace it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0052', 'HDSAT-RW-M10P-0052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Salmon that return to spawn carry marine nitrogen into rivers. Trees along streams where salmon spawn contain measurably more of that nitrogen than trees along streams without salmon. This pattern suggests that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the nitrogen in the trees comes from rainwater rather than the ocean"}, {"id": "B", "text": "salmon avoid streams where trees grow densely"}, {"id": "C", "text": "spawning salmon transfer nutrients from the ocean to the surrounding forest"}, {"id": "D", "text": "trees along salmon streams absorb nitrogen only from the soil"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0052', 'C', ARRAY['C']::TEXT[], 'The marine signature appears only where salmon spawn, which supports a transfer from fish to forest.', '{"D": "The comparison turns on salmon presence, so the trees are receiving marine nitrogen.", "B": "No such avoidance is described, and the presence of salmon is what predicts the nitrogen.", "A": "The isotope signature is specifically marine."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0053', 'HDSAT-RW-M10P-0053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Birds flying in a wind tunnel were filmed with tracer particles. As air speed increased, the birds shifted the angle of their wings, and the wake behind them changed from a single vortex to a pair of vortices. These observations indicate that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the pattern of airflow behind a bird changes as its flight speed changes"}, {"id": "B", "text": "tracer particles alter the way birds flap in a tunnel"}, {"id": "C", "text": "birds produce the same wake at every speed"}, {"id": "D", "text": "wing angle has no effect on the air moving over the wing"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0053', 'A', ARRAY['A']::TEXT[], 'Both the wing angle and the wake change together with speed, so the wake structure is speed-dependent.', '{"C": "The wake is described as changing from one vortex to a pair.", "D": "The birds shift wing angle as speed rises, alongside the wake change.", "B": "The particles are a visualisation method; the text does not suggest they change flight."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0054', 'HDSAT-RW-M10P-0054', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Salt marshes accumulate sediment and can rise as sea level rises, but only if the sediment supply keeps pace. Marshes behind dikes that block sediment often drown, while nearby marshes with open tidal channels keep their elevation. Managers seeking to keep a marsh above water therefore sometimes ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "remove all vegetation so that sediment can settle"}, {"id": "B", "text": "restore tidal flow so sediment can reach the marsh surface"}, {"id": "C", "text": "pump water out of the marsh to lower its surface"}, {"id": "D", "text": "build higher dikes to hold back the sea"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0054', 'B', ARRAY['B']::TEXT[], 'The contrast between diked and open marshes points to sediment supply through tidal channels as the factor that lets a marsh keep up.', '{"D": "Dikes are the condition associated with drowning because they block sediment.", "A": "Vegetation is not described as blocking sediment.", "C": "Lowering the surface would worsen the problem the manager is trying to solve."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0055', 'HDSAT-RW-M10P-0055', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Roman fish sauce was made by salting fish and leaving the mixture in the sun for weeks. Enzymes and bacteria break the proteins into amino acids, including glutamate, which the human tongue detects as savoury. The sauce''s distinctive taste therefore came from ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "whole fish that were never broken down"}, {"id": "B", "text": "salt added at the end of the process"}, {"id": "C", "text": "compounds produced as proteins broke down during fermentation"}, {"id": "D", "text": "the absence of bacteria during curing"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0055', 'C', ARRAY['C']::TEXT[], 'The taste is attributed to glutamate released by protein breakdown, which is the fermentation step the text describes.', '{"B": "Salt is part of the curing mixture, not a flavour added at the end.", "A": "The proteins are broken into amino acids.", "D": "Bacteria are named as agents of the breakdown."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0056', 'HDSAT-RW-M10P-0056', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'As coffee beans roast, acids are destroyed and new aromatic compounds form. A light roast retains more of the acids, while a dark roast contains more of the bitter compounds produced by heat. Two roasts of the same green beans therefore ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "taste identical because they began as the same beans"}, {"id": "B", "text": "differ in flavour because the roasting process changes which compounds dominate"}, {"id": "C", "text": "contain more acids as the roast gets darker"}, {"id": "D", "text": "differ because dark beans come from a different plant species"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0056', 'B', ARRAY['B']::TEXT[], 'The same starting material plus different roasting produces different compounds, so the difference is processing rather than origin.', '{"A": "The passage explains that roasting creates and destroys different compounds.", "D": "The text contrasts light and dark roasts directly.", "C": "The text says acids are destroyed and a dark roast retains fewer."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0057', 'HDSAT-RW-M10P-0057', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Lightning in volcanic plumes occurs when ash particles collide and separate charge, much as ice crystals do in thunderstorms. Plumes with a larger ash load produce more lightning. Observers monitoring an eruption from a safe distance can therefore use lightning activity to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "measure the temperature of the magma below"}, {"id": "B", "text": "determine the chemical composition of the ash"}, {"id": "C", "text": "predict exactly when the eruption will end"}, {"id": "D", "text": "estimate how much ash the plume is carrying"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0057', 'D', ARRAY['D']::TEXT[], 'Because the charging mechanism scales with ash load, lightning gives an indirect measure of how much ash is present.', '{"C": "The text draws no connection between lightning and eruption duration.", "A": "The mechanism concerns ash collisions, not magma temperature.", "B": "The text relates lightning to the quantity of ash, not its chemistry."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0058', 'HDSAT-RW-M10P-0058', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Paper wasps chew wood fibres and build combs of hexagonal cells. The cells are open downward, and larvae hang inside them. Species that build in sheltered cavities have cells that open in various directions, while species that build in the open all have downward-facing cells. This contrast suggests that the downward orientation ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "helps the wasps find their way back to the nest"}, {"id": "B", "text": "makes the comb easier to attach to a branch"}, {"id": "C", "text": "is required for the larvae to breathe inside the cell"}, {"id": "D", "text": "protects the brood from rain where the nest is exposed"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0058', 'D', ARRAY['D']::TEXT[], 'The difference tracks exposure: only open-air builders always point cells down, which is consistent with shedding rain.', '{"B": "Attachment is not discussed in the comparison.", "C": "No connection between orientation and respiration is given.", "A": "Navigation is not mentioned."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0059', 'HDSAT-RW-M10P-0059', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Trees form wide rings in wet years and narrow rings in dry years. A series of measured rings from a living tree can be matched to the pattern in an old roof beam, allowing the beam to be placed in the same sequence. Dendrochronologists can therefore use ring patterns to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "date timbers by matching them to a known sequence of years"}, {"id": "B", "text": "determine the species of a beam without examining its wood"}, {"id": "C", "text": "show that every tree in a region has an identical ring sequence"}, {"id": "D", "text": "measure the current rainfall in a forest"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0059', 'A', ARRAY['A']::TEXT[], 'The matched pattern places an undated beam against a dated sequence, which is the definition of cross-dating.', '{"D": "Ring widths record past conditions, not present rainfall.", "B": "Matching sequences dates wood; it does not identify species.", "C": "The method relies on matching patterns, not on identical sequences everywhere."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0060', 'HDSAT-RW-M10P-0060', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Dust settles on the solar panels of Mars rovers and reduces the power they collect. Gusts occasionally clear panels, and operators have learned to park a rover on a slope so that gravity helps loose dust slide off. This strategy suggests that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "rovers generate more power on flat ground than on slopes"}, {"id": "B", "text": "dust on Mars is permanently fixed to panel surfaces"}, {"id": "C", "text": "tilting a panel can help remove dust when wind alone is not enough"}, {"id": "D", "text": "wind on Mars never clears dust from panels"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0060', 'C', ARRAY['C']::TEXT[], 'Combining occasional wind with a tilt that lets gravity move dust supports the idea that angle helps when wind is insufficient.', '{"B": "The text describes gusts clearing panels and a slope supplementing them.", "A": "The slope is chosen to shed dust, which implies a power benefit.", "D": "The text says gusts occasionally clear panels."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0061', 'HDSAT-RW-M10P-0061', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Some frogs secrete peptides on their skin that kill bacteria. Bacteria living on frog skin are often resistant to those same peptides, while bacteria from nearby ponds are not. This difference suggests that ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "frogs absorb resistant bacteria from the pond to protect themselves"}, {"id": "B", "text": "skin bacteria have evolved tolerance to the defenses of the frog they live on"}, {"id": "C", "text": "pond bacteria are exposed to more frog peptides than skin bacteria"}, {"id": "D", "text": "the frog''s peptides are ineffective against all bacteria"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0061', 'B', ARRAY['B']::TEXT[], 'Resistance appears only in the community that lives with the peptides, which points to selection in that habitat.', '{"D": "The peptides are effective against pond bacteria.", "C": "Skin bacteria live in direct contact with the peptides.", "A": "The comparison shows resistance arising on the skin, not being acquired from the pond."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0062', 'HDSAT-RW-M10P-0062', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Ice accumulating on the leading edge of a wing disrupts smooth airflow and reduces lift. De-icing systems use heat or inflatable boots to break the ice away. After a de-icing cycle, lift returns to near its clean-wing value. These results indicate that the loss of lift was caused by ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "smooth airflow over the leading edge"}, {"id": "B", "text": "permanent deformation of the wing structure"}, {"id": "C", "text": "the weight of the de-icing equipment"}, {"id": "D", "text": "the disruption of airflow by the ice, not by permanent damage to the wing"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0062', 'D', ARRAY['D']::TEXT[], 'Reversibility is the key signal: if removing the ice restores lift, the ice''s interference with airflow caused the loss.', '{"B": "Lift returns after the ice is removed, so the wing itself is not permanently damaged.", "C": "Equipment weight is not measured or discussed.", "A": "Smooth airflow is the condition that restores lift."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0063', 'HDSAT-RW-M10P-0063', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Bamboo poles are strong for their weight and flex under wind loads. In some cities, scaffolding is still built from bamboo lashed with plastic strips rather than steel tube. Engineers note that bamboo scaffolds have survived typhoons that damaged rigid structures nearby. Bamboo''s flexibility therefore appears to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "help the structure absorb wind energy instead of resisting it rigidly"}, {"id": "B", "text": "reduce the strength of the poles to below that of plastic"}, {"id": "C", "text": "prevent the scaffold from moving at all in high wind"}, {"id": "D", "text": "make the structure heavier than an equivalent steel frame"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0063', 'A', ARRAY['A']::TEXT[], 'The contrast with rigid structures that failed points to flexing as the mechanism that lets bamboo survive high winds.', '{"D": "The text says bamboo is strong for its weight.", "C": "Flexing is the opposite of not moving.", "B": "Plastic strips are the lashing, not a comparison of strength."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0064', 'HDSAT-RW-M10P-0064', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Tardigrades survive extreme drying by replacing water in their cells with a sugar that forms a glass-like solid. In this state, proteins keep their shape instead of unfolding. When water returns, the sugar dissolves and normal activity resumes. The sugar therefore functions to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "hold proteins in a stable shape while water is absent"}, {"id": "B", "text": "prevent water from ever returning to the cells"}, {"id": "C", "text": "provide energy for the animal during drought"}, {"id": "D", "text": "dissolve the proteins so they can be rebuilt later"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0064', 'A', ARRAY['A']::TEXT[], 'The glass-like solid is explicitly tied to preserving protein shape through desiccation.', '{"C": "No energy role is described.", "B": "Water returns and activity resumes.", "D": "Proteins keep their shape rather than dissolving."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0065', 'HDSAT-RW-M10P-0065', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Homing pigeons released from an unfamiliar site often circle before setting off. Their initial heading is more accurate when the sun is visible than when the sky is overcast. On overcast days, birds released from the same site take longer to depart and are more often lost. These observations suggest that pigeons ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "fly more accurately when the sky is overcast"}, {"id": "B", "text": "use the sun as one cue for setting their initial direction"}, {"id": "C", "text": "circle because they have already located home"}, {"id": "D", "text": "navigate only by landmarks they memorised before release"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0065', 'B', ARRAY['B']::TEXT[], 'The sun''s visibility changes accuracy at an unfamiliar site, which isolates it as a compass cue rather than a learned route.', '{"D": "An unfamiliar site rules out memorised landmarks as the only cue.", "A": "Accuracy is worse when the sky is overcast.", "C": "Circling precedes departure and is associated with uncertainty."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0066', 'HDSAT-RW-M10P-0066', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Slag from iron smelting contains iron in proportion to how efficiently the furnace ran. Heaps of slag at an excavated site therefore allow archaeologists to estimate how much ore was processed there, even when the furnaces themselves have not survived. The method depends on knowing ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "the number of workers employed at the site"}, {"id": "B", "text": "the exact age of the slag heap"}, {"id": "C", "text": "how much iron the slag holds relative to the ore that produced it"}, {"id": "D", "text": "the price of iron at the time of smelting"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0066', 'C', ARRAY['C']::TEXT[], 'Turning slag quantity into an ore estimate requires a conversion factor, which is the iron content relative to the original ore.', '{"B": "Age does not affect the conversion from slag to ore.", "A": "Workforce size is not part of the calculation described.", "D": "Price is unrelated to the physical proportion of iron."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0067', 'HDSAT-RW-M10P-0067', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Diatoms have silica shells that preserve in lake sediment. Different species thrive at different nutrient levels, so the species present in a sediment layer reflect the water at the time the layer formed. A core spanning several centuries can therefore be used to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "trace how nutrient levels in the lake changed over time"}, {"id": "B", "text": "identify the age of the lake basin itself"}, {"id": "C", "text": "show that all diatom species prefer the same conditions"}, {"id": "D", "text": "measure the lake''s current nutrient level directly"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0067', 'A', ARRAY['A']::TEXT[], 'Because species composition tracks nutrients and the core preserves layers in order, the core becomes a timeline of nutrient conditions.', '{"D": "A core records past layers rather than present water.", "B": "The layers date sediment, not the basin''s origin.", "C": "The method depends on species differing in preference."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0068', 'HDSAT-RW-M10P-0068', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Dust on solar panels reduces the light reaching the cells. In dry regions, cleaning is limited by the availability of water, so operators wait longer between washes than they would elsewhere. In such regions, panel output is therefore expected to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "decline faster between cleanings than in wetter regions"}, {"id": "B", "text": "remain constant because water is scarce"}, {"id": "C", "text": "be unaffected by dust because the air is dry"}, {"id": "D", "text": "improve as dust accumulates on the glass"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0068', 'A', ARRAY['A']::TEXT[], 'Less frequent cleaning in dusty conditions means more accumulated dust, so output falls further between washes.', '{"C": "Dust reduces light regardless of humidity.", "D": "Accumulating dust blocks light rather than improving it.", "B": "Waiting longer between washes allows more dust to build up."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0069', 'HDSAT-RW-M10P-0069', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Some moths produce clicks that interfere with bat echolocation. When bats hunt clicking moths in a chamber, they capture fewer than when they hunt silent moths of the same size. The clicks therefore appear to ______', 'Which choice most logically completes the text?', '[{"id": "A", "text": "make the moths larger on echolocation displays"}, {"id": "B", "text": "reduce the bats'' ability to locate the moths"}, {"id": "C", "text": "improve the bats'' hunting accuracy"}, {"id": "D", "text": "attract bats from a greater distance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0069', 'B', ARRAY['B']::TEXT[], 'Holding size constant and varying only the clicks isolates the sound as the cause of the lower capture rate.', '{"D": "Attraction would raise capture, not lower it.", "A": "The comparison uses moths of the same size.", "C": "Accuracy falls when the moths click."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0070', 'HDSAT-RW-M10P-0070', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A nightingale''s song has a whistle section and a trill section. Researchers recorded individually marked males throughout the night and compared the two sections across hours. Early in the night, males sang long whistle sections; later, the trills grew longer. The shift suggests that the song serves different functions at different hours, perhaps advertising territory first and attracting a mate later.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It states a theory and then reports an experiment that rejects it."}, {"id": "B", "text": "It lists several competing explanations without choosing among them."}, {"id": "C", "text": "It compares two species and explains why one is more successful."}, {"id": "D", "text": "It describes a pattern observed over time and then offers an explanation for it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0070', 'D', ARRAY['D']::TEXT[], 'The first sentences report a measured change across the night; the last sentence interprets that change as a shift in function.', '{"A": "The explanation is supported, not rejected.", "C": "Only one species is discussed.", "B": "One explanation is advanced, not several left open."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0071', 'HDSAT-RW-M10P-0071', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Some plants attach oily packages to their seeds. Ants carry the seeds underground, eat the package and abandon the seed in a chamber. The plant gains burial in a moist, protected space, and the ant gains food. The relationship is a trade: the plant pays in oil and receives transport and shelter for its offspring.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It compares two plants and argues that one is better adapted."}, {"id": "B", "text": "It presents a hypothesis and then describes an experiment that tests it."}, {"id": "C", "text": "It traces a sequence of events and then characterises the relationship between the two organisms."}, {"id": "D", "text": "It describes a problem and then proposes a technological solution."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0071', 'C', ARRAY['C']::TEXT[], 'The passage narrates what happens to seed and ant, then names the exchange as a trade, which is its purpose.', '{"B": "No experiment is described.", "A": "Only one plant strategy is discussed.", "D": "No technology or problem-solving is involved."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0072', 'HDSAT-RW-M10P-0072', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Ancient harbour concrete has outlasted modern port cement exposed to the same waves. The difference is not the aggregate but the binder: Roman mixes included lumps of lime that never fully combined. Water reaching a crack dissolves calcium from those lumps and precipitates minerals that seal it. What looked like careless mixing is now understood as a self-repair system.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It argues that modern cement is superior because it is more uniform."}, {"id": "B", "text": "It describes a manufacturing process in chronological order without evaluating it."}, {"id": "C", "text": "It poses a contrast, identifies its cause, and then revises the original interpretation of the material."}, {"id": "D", "text": "It compares two ancient sites and explains their different climates."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0072', 'C', ARRAY['C']::TEXT[], 'The passage opens with a contrast, explains it through the lime lumps, and closes by reinterpreting those lumps as functional.', '{"B": "The text evaluates the material and explains a mechanism.", "A": "Modern cement is presented as the less durable comparison.", "D": "No two sites are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0073', 'HDSAT-RW-M10P-0073', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The wing hinge of a flying insect is a set of elastic pads and hard plates. When a muscle pulls, the hinge stores energy and releases it at the end of each stroke. High-speed films show that the wing reverses direction before the muscle has finished contracting. The hinge, not the muscle alone, sets the rhythm of the stroke.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To describe how to build a mechanical wing hinge"}, {"id": "B", "text": "To explain how an anatomical structure contributes to the timing of insect flight"}, {"id": "C", "text": "To argue that insect muscles are stronger than vertebrate muscles"}, {"id": "D", "text": "To compare the flight speeds of several insect species"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0073', 'B', ARRAY['B']::TEXT[], 'The passage describes the hinge and uses film evidence to show that it, not just the muscle, times the wingbeat.', '{"C": "No comparison with vertebrates is made.", "A": "The text describes a natural structure, not a construction method.", "D": "Speeds are not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0074', 'HDSAT-RW-M10P-0074', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Permafrost holds large stores of frozen organic matter. When it thaws, microbes begin to decompose that material and release carbon dioxide and methane. A decade-long monitoring study found that emissions rose fastest in the first years after thaw and then slowed as the easily decomposed material was used up. The study''s authors caution that the slowdown may not hold if deeper layers continue to thaw.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It compares two regions and explains why one thaws faster."}, {"id": "B", "text": "It states a policy recommendation and then reviews the evidence for it."}, {"id": "C", "text": "It describes a process, reports a finding, and ends with a limitation on that finding."}, {"id": "D", "text": "It presents a hypothesis that the reported study confirms without reservation."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0074', 'C', ARRAY['C']::TEXT[], 'The text moves from mechanism to measurement to caveat, which is the shape of the whole passage.', '{"B": "No policy is recommended.", "A": "Regions are not compared.", "D": "The final sentence explicitly qualifies the finding."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0075', 'HDSAT-RW-M10P-0075', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Medieval scribes often left wide margins and filled them with small drawings. One explanation is decoration. Another is practical: parchment was expensive, and a copied text could be corrected or annotated only if space remained. Analysis of surviving manuscripts finds more marginal notes in texts used for teaching than in luxury copies, which supports the practical explanation.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It reports a single explanation as established fact."}, {"id": "B", "text": "It argues that decoration was the only reason for wide margins."}, {"id": "C", "text": "It presents two explanations and then describes evidence favoring one."}, {"id": "D", "text": "It describes a technique and then explains how to reproduce it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0075', 'C', ARRAY['C']::TEXT[], 'The passage sets two possible reasons side by side and then uses the distribution of notes to prefer the practical one.', '{"D": "No reproduction method is given.", "B": "Decoration is one candidate explanation, not the sole one.", "A": "A second explanation is offered and tested."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0076', 'HDSAT-RW-M10P-0076', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Whale sharks are the largest fish, yet their movements are poorly known because they spend long periods offshore. Researchers fitted sharks with tags that record depth and light level; the light record estimates position from day length and solar angle. Tracks from tagged animals showed repeated visits to the same seamounts. The tags turned an elusive animal into a mapped one.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It states a problem, explains a method used to address it, and reports a result."}, {"id": "B", "text": "It describes the anatomy of a whale shark in detail."}, {"id": "C", "text": "It compares two tagging technologies and recommends one."}, {"id": "D", "text": "It argues that whale sharks are more common than previously thought."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0076', 'A', ARRAY['A']::TEXT[], 'The difficulty of studying an offshore animal, the light-and-depth tags, and the seamount tracks form a problem-method-result structure.', '{"C": "Only one tagging approach is described.", "B": "Anatomy is not the subject.", "D": "The finding concerns movement patterns, not abundance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0077', 'HDSAT-RW-M10P-0077', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Cities are often warmer than the countryside around them. The difference comes from dark surfaces that absorb sunlight, from buildings that trap heat, and from the removal of vegetation that would otherwise cool the air. Measurements at night show the largest gap, because stored heat is released after sunset. The effect is therefore strongest when the sun is not shining.', 'Which choice best explains why the text mentions night-time measurements?', '[{"id": "A", "text": "To describe how the urban heat island is measured rather than explained"}, {"id": "B", "text": "To argue that vegetation has no effect on urban temperature"}, {"id": "C", "text": "To show that the heat stored during the day continues to affect temperature after sunset"}, {"id": "D", "text": "To prove that cities are cooler than the countryside at night"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0077', 'C', ARRAY['C']::TEXT[], 'The night-time maximum is used as evidence that surfaces store daytime heat and release it later.', '{"D": "The gap is largest at night, meaning cities stay warmer.", "B": "Vegetation is one of the causes named.", "A": "The measurements support an explanation of stored heat."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0078', 'HDSAT-RW-M10P-0078', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A termite mound stays close to a constant temperature even when the outside air swings widely. The mound''s walls are porous, and its internal structure channels warm air upward and draws cooler air in from the base. Architects have copied the principle in buildings that rely on stack ventilation rather than air conditioning. The mound is the model; the building is the application.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It describes a natural system without mentioning any human use."}, {"id": "B", "text": "It explains why termites cannot regulate the temperature of a mound."}, {"id": "C", "text": "It compares two building designs and argues that one is cheaper."}, {"id": "D", "text": "It describes how a natural system works and then shows how that principle has been applied."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0078', 'D', ARRAY['D']::TEXT[], 'The passage explains the mound''s ventilation and then names buildings that use the same stack principle.', '{"C": "Cost is not discussed.", "A": "The final sentences explicitly describe architectural application.", "B": "The mound is said to stay near constant temperature."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0079', 'HDSAT-RW-M10P-0079', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Light travels along a glass fibre by reflecting repeatedly from its walls. A fibre with a core of slightly higher refractive index than its cladding keeps the light inside even when the fibre bends. Medical instruments use bundles of such fibres to carry illumination in one direction and images back in the other. The same property that confines the light makes the bundle flexible enough to insert.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To describe the manufacture of glass from raw materials"}, {"id": "B", "text": "To compare glass fibres with copper wires for data transmission"}, {"id": "C", "text": "To argue that fibre optics are unsuitable for medical instruments"}, {"id": "D", "text": "To explain the optical property behind fibre bundles and how it enables a medical use"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0079', 'D', ARRAY['D']::TEXT[], 'The refractive-index difference is the principle, and the instrument bundle is the use drawn from it.', '{"B": "Data transmission is not discussed.", "A": "Manufacturing is not described.", "C": "The text presents a medical use as an application."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0080', 'HDSAT-RW-M10P-0080', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Ships carry ballast water to stay stable, and they discharge it in the next port. Organisms carried in that water can survive the voyage and establish in new waters. Regulations now require ships to treat ballast before release, using filtration, heat or ultraviolet light. The rules exist because a single discharge can move a species across an ocean.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It explains why a practice is a problem and then describes the response to it."}, {"id": "B", "text": "It compares three treatment methods and identifies the cheapest."}, {"id": "C", "text": "It describes the history of ship design over several centuries."}, {"id": "D", "text": "It argues that ballast water is harmless to receiving ports."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0080', 'A', ARRAY['A']::TEXT[], 'The practice, the ecological consequence, and the regulation form a problem-and-response structure.', '{"C": "No historical development is traced.", "B": "Costs are not compared.", "D": "The text says organisms can establish in new waters."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0081', 'HDSAT-RW-M10P-0081', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Fire leaves a scar in a tree''s rings: the wood just under the bark is damaged, and later rings grow around the wound. By counting rings inward from the scar, researchers date the fire to the year it occurred. A survey of scars across a valley can then be assembled into a map of past fires, showing which years burned and how far the fires spread.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It argues that fires are no longer a natural part of forests."}, {"id": "B", "text": "It compares two ways of dating fires and rejects one."}, {"id": "C", "text": "It explains a dating method and then describes what a collection of such dates can reveal."}, {"id": "D", "text": "It describes the effect of fire on soil chemistry."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0081', 'C', ARRAY['C']::TEXT[], 'The scar-dating technique comes first, and the valley-scale map is the larger use built from many dated scars.', '{"B": "Only one method is presented.", "D": "Soil chemistry is not discussed.", "A": "No such argument is made."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0082', 'HDSAT-RW-M10P-0082', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Two related birds build very different nests. One weaves a hanging pouch with a narrow entrance; the other builds an open cup on a branch. The pouch builder lives where tree snakes are common, and the entrance is too small for the snake to pass. The cup builder lives where snakes are absent, and its open nest allows faster access for feeding.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It describes one species and then rejects a theory about it."}, {"id": "B", "text": "It describes a single nest-building technique step by step."}, {"id": "C", "text": "It contrasts two behaviors and explains the contrast by their different environments."}, {"id": "D", "text": "It argues that open nests are always better than enclosed ones."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0082', 'C', ARRAY['C']::TEXT[], 'The nest forms differ, and the difference is tied to the presence of snakes and the demands of feeding.', '{"A": "Two species are contrasted throughout.", "D": "No such ranking is offered; each nest suits its setting.", "B": "Two techniques are compared, not one sequenced."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0083', 'HDSAT-RW-M10P-0083', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Moths of several species hear ultrasound and fly away from it. Bats hunt by emitting ultrasound and listening for echoes. Researchers played recorded bat calls to moths on a screen and filmed their responses; most turned away within a fraction of a second. A control group exposed to a tone outside the bats'' range showed no such response.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It describes two competing theories and confirms both."}, {"id": "B", "text": "It describes the life cycle of a moth in chronological order."}, {"id": "C", "text": "It explains how bats produce ultrasound but not how moths respond."}, {"id": "D", "text": "It describes a behavior and reports an experiment that tests its function."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0083', 'D', ARRAY['D']::TEXT[], 'The escape behavior and the playback experiment with a control together establish that the response is to bat calls.', '{"A": "A single explanation is tested rather than two theories confirmed.", "C": "Moth response is the focus of the experiment.", "B": "No life cycle is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0084', 'HDSAT-RW-M10P-0084', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Salt crystallising inside porous stone exerts pressure that can flake away the surface. Conservators can slow the damage by reducing the moisture that carries salt into the stone. In one treatment, a poultice draws dissolved salt out through the surface over weeks. The stone is not strengthened, but the source of the pressure is reduced.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It compares two stones and argues that one is more porous."}, {"id": "B", "text": "It lists several causes of damage without discussing remedies."}, {"id": "C", "text": "It describes a treatment and then claims it strengthens the stone."}, {"id": "D", "text": "It explains a cause of damage and then describes a treatment that addresses that cause."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0084', 'D', ARRAY['D']::TEXT[], 'The mechanism is salt pressure from moisture, and the poultice acts on that moisture rather than on the stone''s strength.', '{"A": "Two stones are not compared.", "C": "The text says the stone is not strengthened.", "B": "One cause and one remedy are described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0085', 'HDSAT-RW-M10P-0085', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Schools of fish move in coordinated patterns that look like a single animal turning. One model explains this by having each fish copy only its nearest neighbors. The model reproduces the turning patterns well. It fails, however, when a predator attacks: real schools spread apart faster than the model predicts, suggesting that fish also respond to more distant cues.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It describes a model, notes its success, and then identifies a case it cannot explain."}, {"id": "B", "text": "It describes an experiment that measured the swimming speed of fish."}, {"id": "C", "text": "It argues that fish schools have no coordinated behavior at all."}, {"id": "D", "text": "It presents a model that explains every observed behavior."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0085', 'A', ARRAY['A']::TEXT[], 'The passage gives the neighbor-copying model credit and then uses the predator response as a counterexample.', '{"D": "The final sentence names a case the model fails to explain.", "B": "Speed is not measured in the passage.", "C": "Coordinated turning is the starting observation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0086', 'HDSAT-RW-M10P-0086', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Mosquitoes find hosts using carbon dioxide, body heat and skin chemicals. Traps that release only carbon dioxide catch some mosquitoes but far fewer than traps baited with skin odour as well. When researchers removed carbon dioxide entirely, the traps caught almost nothing, even with skin odour present. Carbon dioxide appears to be necessary, though not sufficient on its own.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It argues that skin odour alone is sufficient to attract mosquitoes."}, {"id": "B", "text": "It lists cues, then reports comparisons that establish the role of one cue."}, {"id": "C", "text": "It describes a single cue and ignores the others."}, {"id": "D", "text": "It explains how to build a trap without evaluating any cue."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0086', 'B', ARRAY['B']::TEXT[], 'The candidates are introduced together, and the trap comparisons isolate carbon dioxide as necessary but not sufficient.', '{"C": "All three cues are introduced.", "A": "Traps with skin odour but no carbon dioxide caught almost nothing.", "D": "The comparisons evaluate the cues."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0087', 'HDSAT-RW-M10P-0087', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Steel in seawater corrodes faster than steel in fresh water because chloride ions break down the protective oxide layer. Cathodic protection counteracts this by supplying electrons from a sacrificial metal that corrodes in place of the steel. The sacrificial block is replaced periodically; the structure it protects is not.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It describes a method of protection without explaining why corrosion happens."}, {"id": "B", "text": "It compares two metals and argues that both corrode at the same rate."}, {"id": "C", "text": "It describes the manufacture of steel from iron ore."}, {"id": "D", "text": "It explains a cause of corrosion and then describes a method that prevents it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0087', 'D', ARRAY['D']::TEXT[], 'The chloride attack is the mechanism, and the sacrificial anode is the countermeasure that takes the corrosion instead.', '{"B": "The text says steel corrodes faster in seawater.", "A": "The chloride mechanism is explained first.", "C": "Manufacturing is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0088', 'HDSAT-RW-M10P-0088', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Folding a flat sheet into a rigid structure usually requires glue or fasteners. A pattern of folds can instead lock the sheet into a stiff three-dimensional shape by creating ridges that resist bending. Engineers have used such patterns for packaging that ships flat and for panels that deploy in space. The fold pattern replaces the fastener.', 'Which choice best states the main purpose of the text?', '[{"id": "A", "text": "To describe the history of paper folding as an art form"}, {"id": "B", "text": "To explain how folding can provide rigidity without added fasteners"}, {"id": "C", "text": "To argue that flat sheets cannot be made rigid by any means"}, {"id": "D", "text": "To compare the cost of packaging with the cost of spacecraft panels"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0088', 'B', ARRAY['B']::TEXT[], 'The passage''s point is that ridges from folds resist bending, so the fold pattern itself does the work of glue or fasteners.', '{"D": "No costs are compared.", "A": "Origami as art is not discussed.", "C": "The text shows one way to make a sheet rigid."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0089', 'HDSAT-RW-M10P-0089', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Pigments in cave paintings include iron oxides, charcoal and minerals ground from local rock. Analysis of a paint layer can identify its ingredients, and comparison with nearby deposits can suggest where each came from. Some pigments were carried tens of kilometres, which implies that the painters chose materials for color or durability rather than convenience alone.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It argues that cave painters used only materials found at the site."}, {"id": "B", "text": "It lists pigments without saying what they reveal."}, {"id": "C", "text": "It describes a painting technique and recommends it to modern artists."}, {"id": "D", "text": "It describes an analysis and then draws an inference from its results."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0089', 'D', ARRAY['D']::TEXT[], 'The ingredient analysis is the method, and the long-distance sourcing is the inference about why materials were chosen.', '{"C": "No recommendation is made.", "B": "The pigments are linked to sourcing and choice.", "A": "The text says some pigments were carried long distances."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0090', 'HDSAT-RW-M10P-0090', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A single seismic station can record an earthquake but cannot locate it precisely. Three stations that record the same event allow location, because the arrival times differ by distance and the differences define a point. Networks therefore place stations in arrays rather than at isolated sites. The network, not the instrument, does the locating.', 'Which choice best describes the structure of the text?', '[{"id": "A", "text": "It states a limitation, explains how combining stations overcomes it, and draws a design conclusion."}, {"id": "B", "text": "It describes an instrument and then lists its components."}, {"id": "C", "text": "It argues that isolated stations are more useful than networks."}, {"id": "D", "text": "It compares two types of earthquake and explains their origins."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0090', 'A', ARRAY['A']::TEXT[], 'The single-station limit, the three-station solution, and the resulting preference for arrays form the passage''s logic.', '{"D": "Earthquake types are not compared.", "B": "Components are not listed.", "C": "The text concludes the opposite."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0091', 'HDSAT-RW-M10P-0091', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Lichen grows so slowly that its hold on a gravestone can serve as a clock. Researchers measure the largest thallus on a stone and divide its radius by a growth rate calibrated to the local climate. On churchyard monuments of known age, the method usually lands within a few years. It fails on porous limestone and in polluted air, where growth stalls unpredictably.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Porous limestone offers the most reliable setting for lichen dating."}, {"id": "B", "text": "Churchyard monuments are usually older than their inscriptions claim."}, {"id": "C", "text": "Lichen grows quickly enough to record the exact year a stone was carved."}, {"id": "D", "text": "Lichen size can estimate the age of a gravestone, but only under favorable conditions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0091', 'D', ARRAY['D']::TEXT[], 'The passage explains the dating method, notes its apparent accuracy on dated monuments, and then names two conditions that break it.', '{"C": "The text calls lichen a slow grower, not a fast one.", "B": "No claim is made about inscriptions being wrong.", "A": "Limestone is named as one of the surfaces where the method fails."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0092', 'HDSAT-RW-M10P-0092', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Before the nineteenth century, most European paper was made from linen rags. Cotton and linen fibres are long and interlock into a sheet that resists acid. When cheap wood pulp replaced rags, paper became far more plentiful, but the pulp carried lignin and residual acids that slowly break fibre bonds. Libraries now spend large sums on chemical treatment for volumes printed after 1850.', 'Which choice best explains why books printed after 1850 often need conservation?', '[{"id": "A", "text": "Later books were manufactured on thinner paper to cut transport weight."}, {"id": "B", "text": "Libraries stored the newer volumes in damper rooms than the older ones."}, {"id": "C", "text": "Post-1850 ink corrodes the binding thread faster than earlier ink."}, {"id": "D", "text": "Wood pulp introduced acids and lignin that weaken the paper over time."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0092', 'D', ARRAY['D']::TEXT[], 'The passage contrasts acid-resistant rag paper with acidic, lignin-bearing wood pulp and ties the conservation expense to that shift.', '{"C": "Ink is not mentioned; the change is in the paper itself.", "A": "Thickness is not offered as a cause.", "B": "Storage conditions are never compared in the text."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0093', 'HDSAT-RW-M10P-0093', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A peat bog is a waterlogged archive. Because standing water excludes oxygen and slows decay, plant material accumulates for thousands of years. Each layer records the pollen that fell that season, so a core from a bog reads like a calendar of regional vegetation. Draining a bog for fuel or farmland reverses the guarantee: oxygen enters, decay resumes, and the archive is lost.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Peat burns well because it holds very little water."}, {"id": "B", "text": "Bog cores record animal populations more reliably than plants."}, {"id": "C", "text": "Draining a bog speeds up the formation of new peat layers."}, {"id": "D", "text": "Bogs preserve layered evidence of past vegetation only while they remain wet."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0093', 'D', ARRAY['D']::TEXT[], 'The passage explains how waterlogged conditions stop decay and create a pollen record, then warns that drainage destroys it.', '{"A": "The text stresses that bogs are waterlogged, not water-poor.", "B": "Pollen is the recorded evidence, not animals.", "C": "Draining is described as ending preservation, not aiding it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0094', 'HDSAT-RW-M10P-0094', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Bats that hunt near foliage use long, low-frequency calls that travel well but resolve detail poorly. Bats hunting in cluttered woods switch to brief, high-frequency calls that fade quickly yet return sharp echoes from nearby shapes. When researchers recorded a single species hunting in both habitats, the calls matched the setting rather than the animal: individuals changed call design as they crossed from open field to canopy.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "High-frequency calls travel farther than low-frequency calls."}, {"id": "B", "text": "Each bat species uses one fixed call design from birth."}, {"id": "C", "text": "Open-field hunting demands sharper detail than hunting inside woods."}, {"id": "D", "text": "Bats adjust their calls to the habitat they are hunting in at that moment."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0094', 'D', ARRAY['D']::TEXT[], 'The passage gives the trade-off between call designs, then reports that one species changed its design as it moved between habitats.', '{"B": "The recorded individuals changed calls within one species.", "A": "The text says high-frequency calls fade quickly, so they travel less far.", "C": "It is the cluttered woods that require resolution of nearby shapes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0095', 'HDSAT-RW-M10P-0095', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Bamboo scaffolding still rises around skyscrapers in some cities. The traditional material is cheap, light enough to be carried by hand, and quickly cut to length. Critics point to fire risk and to the absence of formal design codes. Practitioners answer that the lashings are the structure: a properly tied joint spreads load across several culms, so the frame gives slightly instead of snapping in typhoon winds.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Bamboo scaffolding has replaced steel on most high-rise construction sites."}, {"id": "B", "text": "Fire risk has made bamboo scaffolding unacceptable in every city."}, {"id": "C", "text": "Bamboo scaffolding offers genuine structural advantages, though it also carries risks."}, {"id": "D", "text": "Lashings are decorative and play no part in supporting the frame."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0095', 'C', ARRAY['C']::TEXT[], 'The passage balances practical advantages against fire and code concerns, then explains how tied joints distribute load.', '{"A": "The text says \"some cities,\" not most sites.", "B": "Risk is acknowledged but not described as a universal ban.", "D": "The passage calls the lashings the structure itself."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0096', 'HDSAT-RW-M10P-0096', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Seed banks cannot simply freeze every seed and forget it. Some species die if dried to the standard moisture level; others survive only if cooled slowly. Germination tests therefore run on samples withdrawn at fixed intervals, and a fraction of each collection is regrown so fresh seed replaces ageing stock. A bank''s value lies less in its freezer than in this repeated cycle of testing and renewal.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Seed banks regrow samples only when a species becomes extinct in the wild."}, {"id": "B", "text": "Germination tests are performed once, when a collection first arrives."}, {"id": "C", "text": "Keeping seeds viable requires ongoing testing and regeneration, not storage alone."}, {"id": "D", "text": "Freezing at a single standard moisture level works for all species."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0096', 'C', ARRAY['C']::TEXT[], 'The passage lists species-specific handling, describes periodic testing and regrowth, and concludes that this cycle is the bank''s real value.', '{"D": "The text names species that die at the standard level.", "A": "Regrowth is routine renewal, not a response to extinction.", "B": "Tests run at fixed intervals throughout storage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0097', 'HDSAT-RW-M10P-0097', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'On some glaciers, small balls of moss roll slowly downhill as the ice moves beneath them. The balls stay green on the outside and die at the base, where they touch the ice. Because each ball turns only as fast as the surface it rides, its motion is set by the glacier rather than by the wind. Researchers have used them as passive markers of ice flow.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Glacier moss balls are blown downhill by strong katabatic winds."}, {"id": "B", "text": "Researchers move the balls deliberately to chart ice movement."}, {"id": "C", "text": "Glacier moss balls move with the ice and can therefore serve as markers of its flow."}, {"id": "D", "text": "The moss stays alive throughout the ball, including where it meets the ice."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0097', 'C', ARRAY['C']::TEXT[], 'The passage describes the balls, explains that ice movement drives them, and states that researchers use them as passive flow markers.', '{"A": "The text says motion is set by the glacier, not by wind.", "D": "The base dies where it touches the ice.", "B": "They are passive markers, not tools the researchers reposition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0098', 'HDSAT-RW-M10P-0098', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Tide pools high on a rocky shore heat up faster than pools near the waterline. During low tide on a sunny day, a shallow upper pool can climb several degrees above the surrounding ocean. Species that cannot tolerate the swing retreat downward, leaving the upper pools to a few heat-tolerant specialists. On cool, foggy coasts the same pools stay far closer to ocean temperature.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A pool''s height on the shore shapes how extreme its temperature becomes and which species survive there."}, {"id": "B", "text": "Foggy coasts produce the widest temperature swings in tide pools."}, {"id": "C", "text": "Upper tide pools are always cooler than pools near the waterline."}, {"id": "D", "text": "All tide-pool species tolerate the same range of temperatures."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0098', 'A', ARRAY['A']::TEXT[], 'The passage links pool height to temperature extremes, notes that sensitive species move down, and contrasts sunny with foggy coasts.', '{"C": "The text says upper pools heat faster and climb higher.", "D": "Species differ in tolerance, which is why some retreat.", "B": "Foggy coasts keep pools closer to ocean temperature."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0099', 'HDSAT-RW-M10P-0099', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'The painted clay figures buried near Xi''an retained traces of pigment because the burial chamber stayed dark, dry and chemically stable. Once excavated, the surface met air and light for the first time in two thousand years. Conservators now record color within minutes of exposure, and some figures are reburied rather than displayed, because the safest environment for the paint is the one it left.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The figures were originally painted with pigments that resist light."}, {"id": "B", "text": "Reburial damages the paint more than museum display does."}, {"id": "C", "text": "Conservators display every figure as soon as it is excavated."}, {"id": "D", "text": "The pigment survives best in the buried conditions that exposure destroys."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0099', 'D', ARRAY['D']::TEXT[], 'The passage credits the stable burial chamber, describes the threat posed by air and light, and explains choices made to protect the paint.', '{"A": "The text says exposure damages the paint; it never calls it light-resistant.", "C": "Some figures are reburied instead of displayed.", "B": "Reburial is described as the safer option."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0100', 'HDSAT-RW-M10P-0100', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'A subway diagram is not a map. To make routes readable, designers straighten lines, space stations evenly and enlarge the city center. The result distorts distance so badly that a two-stop ride downtown may be shorter on the ground than a one-stop ride in the suburbs. Riders accept the distortion because the diagram answers the question they actually ask: which line to take, not how far they will travel.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Subway diagrams are drawn to preserve true geographic distance."}, {"id": "B", "text": "Outer stations are always spaced more widely than central ones."}, {"id": "C", "text": "Subway diagrams deliberately distort distance in order to make routes easier to follow."}, {"id": "D", "text": "Riders reject diagrams that fail to show exact travel distances."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0100', 'C', ARRAY['C']::TEXT[], 'The passage describes the distortions, gives an example of their effect, and explains why riders tolerate them.', '{"A": "The text says designers straighten lines and space stations evenly.", "D": "The passage says riders accept the distortion.", "B": "Central stations are enlarged and spread out, not the reverse."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0101', 'HDSAT-RW-M10P-0101', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A sourdough starter is a stable community of wild yeasts and lactic-acid bacteria. Feed it flour and water on a regular schedule and the same species tend to dominate for years, even if the kitchen is not sterile. Change the feeding rhythm or the flour, however, and the balance shifts. Bakers describe the result as a change in character: sharper, slower to rise, or suddenly vigorous.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sterile kitchens are required to keep a starter free of unwanted microbes."}, {"id": "B", "text": "A starter''s species composition never changes once it is established."}, {"id": "C", "text": "Switching flour has no measurable effect on how a starter behaves."}, {"id": "D", "text": "A starter''s microbial balance stays stable under routine feeding but responds to changes in it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0101', 'D', ARRAY['D']::TEXT[], 'The passage presents the starter as a stable community, then describes how feeding rhythm and flour change its behavior.', '{"A": "The text says the community persists even in an unsterile kitchen.", "B": "The passage says the balance shifts when conditions change.", "C": "Flour is named as one of the changes that alters the balance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0102', 'HDSAT-RW-M10P-0102', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Ice cores preserve dust in annual layers. A band rich in mineral dust usually marks a year when winds carried more material from exposed ground, often during a dry period. Because the layers are ordered and countable, a core gives both a sequence of events and a rough timescale. The dust itself does not measure temperature; it records atmospheric transport, which researchers interpret alongside other signals.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Dust layers in ice cores are a direct measurement of past temperature."}, {"id": "B", "text": "Ice-core layers cannot be counted, so they provide no timescale."}, {"id": "C", "text": "Mineral dust in ice cores comes mainly from volcanic eruptions."}, {"id": "D", "text": "Dust layers in ice cores record atmospheric transport and give a dated sequence, not a direct temperature reading."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0102', 'D', ARRAY['D']::TEXT[], 'The passage explains what a dust band represents, notes the countable layering, and limits the interpretation to atmospheric transport.', '{"A": "The text explicitly denies that dust measures temperature.", "B": "It says the layers are countable and give a rough timescale.", "C": "The dust is described as wind-blown from exposed ground."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0103', 'HDSAT-RW-M10P-0103', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'When a whale carcass sinks, it supports a succession of communities for decades. Scavengers strip soft tissue within months. Bone-eating worms and mussels then colonise the skeleton, using fats locked inside the bone. Only after those reserves are exhausted do sulphide-loving microbes take over the remaining mineral structure. The same carcass passes through several distinct ecosystems without moving.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Bone-eating species arrive before soft tissue scavengers."}, {"id": "B", "text": "A single sunken carcass supports a long sequence of different communities as its resources are used up."}, {"id": "C", "text": "Whale carcasses are consumed entirely within a few months of sinking."}, {"id": "D", "text": "The communities at a carcass all depend on the same food source."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0103', 'B', ARRAY['B']::TEXT[], 'The passage orders the stages of a whale fall and shows that each community exploits a different remaining resource.', '{"C": "The text says the process lasts for decades.", "A": "Scavengers strip soft tissue first, then bone specialists arrive.", "D": "Each stage uses a different resource, from tissue to bone fat to minerals."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0104', 'HDSAT-RW-M10P-0104', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Before radio, fire lookouts located fires by triangulation. Two towers sighted the same smoke plume and reported the bearing from each. Drawn on a map, the two bearings crossed at a single point. Accuracy depended on clear sightlines and on towers being far enough apart that the lines met at a wide angle; towers nearly in line produced a crossing so shallow that a small error moved the reported fire by miles.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Fire lookouts relied on radio to report bearings before triangulation."}, {"id": "B", "text": "Towers placed close together produced the most accurate crossings."}, {"id": "C", "text": "A single lookout could locate a fire without help from another tower."}, {"id": "D", "text": "Triangulation worked well only when the sighting towers were positioned to produce a wide crossing angle."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0104', 'D', ARRAY['D']::TEXT[], 'The passage describes the two-bearing method and explains why wide angles made the crossing reliable while shallow ones amplified error.', '{"C": "The method requires two bearings from two towers.", "A": "The text places triangulation before radio.", "B": "Close or nearly aligned towers produced shallow, inaccurate crossings."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0105', 'HDSAT-RW-M10P-0105', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Oyster reefs once formed low walls along many estuaries. The shells break incoming waves before the water reaches the shore, and the spaces between them shelter juvenile fish. When reefs were dredged away for lime and road fill, shorelines began to erode faster. Restoration projects now lay shell bags in shallow water, where new larvae settle on old shell and rebuild the structure over several seasons.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Dredging reefs improved shoreline stability in most estuaries."}, {"id": "B", "text": "Oyster reefs increase wave energy reaching the shore."}, {"id": "C", "text": "Oyster reefs protect shorelines and can be rebuilt by giving larvae a shell base to settle on."}, {"id": "D", "text": "Restored reefs form within a single season without intervention."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0105', 'C', ARRAY['C']::TEXT[], 'The passage describes the protective role of reefs, the consequence of removing them, and the shell-bag method of restoration.', '{"B": "The text says reefs break waves before they reach shore.", "D": "Rebuilding takes several seasons.", "A": "Dredging is linked to faster erosion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0106', 'HDSAT-RW-M10P-0106', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Japanese joinery connects beams without nails or glue. A dovetail or mortise-and-tenon joint relies on shaped surfaces that lock together under load, and a well-cut joint can be dismantled and reassembled without losing grip. The technique demands precise handwork, since a gap of a millimetre defeats the interlock. Modern timber frames sometimes combine such joints with concealed steel, using the metal where the wood alone would creep.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Wooden joints can carry structural loads through precise shaping, though modern practice sometimes adds hidden reinforcement."}, {"id": "B", "text": "Machine-cut joints are more precise than hand-cut ones and have replaced them."}, {"id": "C", "text": "Japanese joinery depends on glue to hold its shaped surfaces together."}, {"id": "D", "text": "Steel reinforcement makes traditional joints impossible to dismantle."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0106', 'A', ARRAY['A']::TEXT[], 'The passage explains how interlocking shapes carry load, stresses the need for precision, and notes where modern builders add concealed steel.', '{"C": "The text says the joints use no nails or glue.", "B": "Precision is attributed to handwork, not machines.", "D": "The passage does not say reinforced frames cannot be dismantled."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0107', 'HDSAT-RW-M10P-0107', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Tea leaves begin to oxidise as soon as they are rolled. To make green tea, growers heat the leaves quickly to stop the reaction; to make black tea, they let it run. The same bush can therefore produce either style. What changes is not the plant but the moment at which the process is halted, which is why a single garden may sell several very different teas from one harvest.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Black tea is made by halting oxidation immediately after rolling."}, {"id": "B", "text": "A single garden can produce only one style of tea per harvest."}, {"id": "C", "text": "The style of tea depends on when oxidation is stopped, not on a different plant."}, {"id": "D", "text": "Green tea and black tea come from different species of bush."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0107', 'C', ARRAY['C']::TEXT[], 'The passage contrasts the two processes and concludes that timing, not the plant, determines the style.', '{"D": "The text says the same bush can produce either style.", "A": "Black tea lets oxidation continue.", "B": "One harvest can yield several styles."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0108', 'HDSAT-RW-M10P-0108', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Most microplastic fibres in coastal water come from clothing. Washing releases them because fabric rubs against itself in the drum, breaking weak filaments. Filters fitted to washing machines catch a share of the fibres, but the smallest fragments pass through. Researchers therefore compare fibre loads downstream of treatment plants with those from households, trying to separate what a plant removes from what it simply delays.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Machine filters capture every fibre released during a wash."}, {"id": "B", "text": "Treatment plants prevent all microplastic fibres from reaching the sea."}, {"id": "C", "text": "Microplastic fibres in coastal water originate mainly from fishing gear."}, {"id": "D", "text": "Washing clothes releases microplastic fibres that treatment plants only partly remove."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0108', 'D', ARRAY['D']::TEXT[], 'The passage names washing as the main source, explains the release mechanism, and notes that filters and plants capture only part of the load.', '{"C": "The text identifies clothing as the main source.", "A": "The smallest fragments pass through filters.", "B": "The plants capture a share, not everything."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0109', 'HDSAT-RW-M10P-0109', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'In dry regions, a sand dam is built across a seasonal riverbed. During the rains, sand washes down and lodges behind the wall, and water fills the pores between the grains. Because the sand shields the water from sun and evaporation, the stored supply can outlast an open reservoir of similar volume. Wells sunk into the sand then draw water through the dry season.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sand dams are open reservoirs that lose water quickly to evaporation."}, {"id": "B", "text": "Sand dams store water in the pores of trapped sand, which limits evaporation and keeps supply available through dry months."}, {"id": "C", "text": "The wall of a sand dam blocks sand while allowing water to pass downstream."}, {"id": "D", "text": "Wells dug into sand dams yield water only during the rainy season."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0109', 'B', ARRAY['B']::TEXT[], 'The passage describes how sand collects behind the wall, how water is held between grains, and why that limits evaporation.', '{"A": "The text says the sand shields the water, unlike an open reservoir.", "C": "The wall traps the sand, and water is held among the grains.", "D": "Wells draw on the stored water through the dry season."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0110', 'HDSAT-RW-M10P-0110', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Many birds moult their flight feathers on a schedule that avoids the demands of migration and breeding. Waterfowl often drop all primaries at once and cannot fly for several weeks, so they gather on open water where predators are easier to see. Smaller songbirds replace feathers gradually, keeping enough lift to fly throughout. Both strategies are ways of managing the same trade-off between repair and mobility.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Moult strategies differ because birds balance feather replacement against the need to stay mobile."}, {"id": "B", "text": "All birds replace their flight feathers at exactly the same time of year."}, {"id": "C", "text": "Songbirds moult only when they have finished migrating for the year."}, {"id": "D", "text": "Waterfowl keep flying normally while they replace every primary feather."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0110', 'A', ARRAY['A']::TEXT[], 'The passage contrasts simultaneous and gradual moult and explains that both manage the trade-off between repair and staying airborne.', '{"B": "The passage describes two different schedules.", "D": "Waterfowl cannot fly for weeks after dropping all primaries.", "C": "The text does not tie songbird moult to migration completion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0111', 'HDSAT-RW-M10P-0111', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Lunar soil contains no organic binder, so engineers have tested sintering it with microwaves into solid bricks. The process melts grains at contact points, fusing them without additives. A furnace would have to carry its own power and mass to the Moon, which makes the energy budget the central design constraint. Tests on simulated regolith show that bricks strong enough for a landing pad are possible, but only at temperatures that demand substantial equipment.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sintering lunar soil can make strong bricks, but the energy and equipment required are the main obstacles."}, {"id": "B", "text": "Lunar soil already contains a natural binder that holds bricks together."}, {"id": "C", "text": "Engineers have built landing pads on the Moon from sintered regolith."}, {"id": "D", "text": "Microwave sintering requires additives shipped from Earth."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0111', 'A', ARRAY['A']::TEXT[], 'The passage explains the sintering method, identifies energy as the constraint, and limits the result to laboratory tests.', '{"B": "The text says the soil has no organic binder.", "C": "The tests are on simulated regolith on Earth.", "D": "The process fuses grains without additives."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0112', 'HDSAT-RW-M10P-0112', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A hand-bound book is held together by thread sewn through the folds of its sections. The sewing must be tight enough to keep the pages aligned but loose enough that the spine can open without cracking the paper. Binders therefore choose thread thickness and stitch spacing for the paper in front of them. A method that works for heavy drawing paper will tear thin text paper at the fold.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Tight sewing is always better because it prevents pages from shifting."}, {"id": "B", "text": "Thread thickness has no effect on whether a spine can open."}, {"id": "C", "text": "Binding choices must be matched to the paper, because a stitch that suits one paper damages another."}, {"id": "D", "text": "Hand binding uses glue instead of thread to hold sections together."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0112', 'C', ARRAY['C']::TEXT[], 'The passage explains the tension in sewing, then states that thread and spacing are selected per paper, with a concrete failure example.', '{"D": "The text describes thread sewn through folds.", "A": "The passage warns that too tight a stitch cracks the paper.", "B": "Thread thickness is named as a choice binders make."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0113', 'HDSAT-RW-M10P-0113', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Beavers change the hydrology of a valley long before anyone measures it. A dam raises the water table, slows spring runoff and spreads water across the floodplain. Downstream, the peak of a flood arrives later and lower. Removing beavers reverses the effect quickly, which is why some water managers now treat them as inexpensive infrastructure rather than as nuisance rodents.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Water managers universally regard beavers as pests to be removed."}, {"id": "B", "text": "Beaver activity has no measurable effect on the water table."}, {"id": "C", "text": "Beaver dams alter water storage and timing in ways that can be useful to water managers."}, {"id": "D", "text": "Beaver dams raise flood peaks downstream."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0113', 'C', ARRAY['C']::TEXT[], 'The passage describes the hydrological effects and notes that managers increasingly value them.', '{"D": "The text says the downstream peak arrives later and lower.", "B": "The dam is said to raise the water table.", "A": "The passage describes a shift toward treating them as infrastructure."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0114', 'HDSAT-RW-M10P-0114', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Soil microbes respire carbon the way animals do, releasing it as carbon dioxide. Whether a soil stores or loses carbon depends on how much of that respiration is offset by plant inputs and by organic matter sticking to mineral surfaces. Warming speeds microbial activity, but it can also dry the soil and reduce plant growth. The net effect therefore varies by site, which is why estimates from one grassland do not transfer to another.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Whether warming makes a soil a carbon source or sink depends on local conditions."}, {"id": "B", "text": "Soil microbes store carbon directly in their cells without respiring."}, {"id": "C", "text": "Warming always causes soil to release more carbon than it stores."}, {"id": "D", "text": "Results from one grassland reliably predict another''s carbon balance."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0114', 'A', ARRAY['A']::TEXT[], 'The passage sets respiration against plant inputs and mineral binding, then concludes that the outcome is site-specific.', '{"C": "The text says the net effect varies.", "B": "Microbes are described as respiring carbon dioxide.", "D": "The passage says estimates do not transfer between sites."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0115', 'HDSAT-RW-M10P-0115', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'A star catalog is a snapshot that ages. Stars move, and a position recorded with great precision in one decade can be wrong by a noticeable margin a century later. Astronomers therefore re-measure reference stars to track proper motion, the slow drift across the sky. Older catalogues remain useful not despite their age but because of it: the long interval between observations is what makes the drift visible.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Astronomers measure proper motion by observing a star only once."}, {"id": "B", "text": "Old star catalogues gain value from their age, because the time gap reveals how stars have moved."}, {"id": "C", "text": "Stars hold fixed positions, so old catalogues remain accurate indefinitely."}, {"id": "D", "text": "Proper motion makes historical catalogues useless for modern astronomy."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0115', 'B', ARRAY['B']::TEXT[], 'The passage explains drift, the need for re-measurement, and the special value of long time baselines.', '{"C": "The text says positions drift over time.", "D": "Old catalogues are described as useful precisely because of their age.", "A": "Motion requires comparison across observations."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0116', 'HDSAT-RW-M10P-0116', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Inca suspension bridges were woven from grass rope and rebuilt every year. The span was anchored to stone abutments on each bank, and the cables were kept taut by tension applied at the anchors rather than by mid-span supports. Because the material degraded in rain and sun, annual renewal was part of the design, not a repair. The bridge existed as a repeated event rather than as a permanent object.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The bridges were permanent structures rebuilt only after accidents."}, {"id": "B", "text": "The bridges were made from rope that did not degrade in weather."}, {"id": "C", "text": "Annual rebuilding was integral to how these grass-rope bridges worked, not a failure of maintenance."}, {"id": "D", "text": "Stone abutments supported the middle of each span."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0116', 'C', ARRAY['C']::TEXT[], 'The passage describes the structure and concludes that renewal belonged to the design.', '{"B": "The text says the material degraded in rain and sun.", "D": "The abutments anchored the ends; there were no mid-span supports.", "A": "Renewal was annual and planned, not a response to accidents."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0117', 'HDSAT-RW-M10P-0117', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Honey crystallises because it is a supersaturated sugar solution. Glucose comes out of solution first, forming small crystals; the rest of the honey then sets around them. Gentle warming redissolves the crystals, but overheating destroys the enzymes that make honey distinctive. Whether a jar crystallises quickly depends mostly on its ratio of glucose to fructose, which varies with the flowers the bees visited.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The glucose-to-fructose ratio is identical in every jar of honey."}, {"id": "B", "text": "Crystallisation is a natural consequence of honey''s sugar balance and can be reversed without overheating."}, {"id": "C", "text": "Heating honey strongly is the recommended way to restore it."}, {"id": "D", "text": "Crystallisation indicates that honey has begun to spoil."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0117', 'B', ARRAY['B']::TEXT[], 'The passage explains the chemistry, the safe remedy, and the floral source of variation.', '{"D": "The passage treats crystallisation as physical, not spoilage.", "C": "Overheating destroys enzymes, so strong heat is not recommended.", "A": "The ratio varies with the flowers visited."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0118', 'HDSAT-RW-M10P-0118', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Rock art is hard to photograph without flattening it. A camera pointed straight at a carved panel loses the shadows that make the figures legible. Photogrammetry solves this by taking many overlapping images from different angles and rebuilding the surface as a three-dimensional model. Light can then be aimed across the digital surface from any direction, revealing carving depth that no single photograph recorded.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Photogrammetry requires a single photograph taken in flat light."}, {"id": "B", "text": "Carved panels are easier to read in photographs than in person."}, {"id": "C", "text": "Photogrammetry preserves the surface relief of rock art that ordinary photographs flatten."}, {"id": "D", "text": "The digital model removes the need to record the site at all."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0118', 'C', ARRAY['C']::TEXT[], 'The passage contrasts flat photography with multi-angle reconstruction and explains the advantage of relighting the model.', '{"A": "The method uses many overlapping images.", "B": "The text says photographs lose the shadows that make figures legible.", "D": "The model is a record of the site, not a replacement for recording."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0119', 'HDSAT-RW-M10P-0119', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'A fish ladder is a staircase of small pools built around a dam. Each pool is low enough for a fish to jump or swim into, and the flow between pools is kept slow enough that the animal is not swept back. Designs differ by species: a ladder tuned for salmon, which leap, may be unusable for bottom-dwelling fish that cannot clear a step at all.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Fish ladders are built to speed water past a dam rather than to help fish."}, {"id": "B", "text": "A single ladder design works for every species in a river."}, {"id": "C", "text": "Fish ladders must be designed for the swimming and jumping abilities of the species that need them."}, {"id": "D", "text": "Bottom-dwelling fish pass ladders more easily than salmon do."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0119', 'C', ARRAY['C']::TEXT[], 'The passage describes the pool staircase and explains why a design suited to jumpers can fail other species.', '{"B": "The text says designs differ by species.", "A": "The pools are built to let fish ascend.", "D": "Bottom-dwelling fish may be unable to clear a step."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0120', 'HDSAT-RW-M10P-0120', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Adobe walls stay comfortable in hot, dry climates because they combine mass with delay. During the day the wall absorbs heat slowly; by the time that heat reaches the interior, the outside air has cooled. Thick walls work because the delay is long, not because the material insulates especially well. In humid climates the same walls can trap moisture, which is why the technique spread most widely in dry regions.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Adobe construction performs best in humid regions."}, {"id": "B", "text": "Adobe''s comfort comes from the delay created by wall mass, which suits dry climates better than humid ones."}, {"id": "C", "text": "Adobe walls cool a room by insulating it almost perfectly."}, {"id": "D", "text": "Thin adobe walls are more effective than thick ones in hot climates."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0120', 'B', ARRAY['B']::TEXT[], 'The passage explains the thermal delay and ties the technique''s distribution to dry climates.', '{"C": "The text says the delay, not insulation, is the key.", "D": "The passage credits thick walls with a longer delay.", "A": "Humid climates can trap moisture in adobe."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0121', 'HDSAT-RW-M10P-0121', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Some seeds germinate only after fire. Their coats are impermeable to water until heat cracks them, and some species also respond to chemicals in smoke. This delays germination until a fire has cleared competing vegetation and returned nutrients to the soil. A seed that sprouted immediately would face shade and competition; waiting is an advantage, not a delay.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Fire destroys the seed coats of every species in a burned area."}, {"id": "B", "text": "Smoke chemicals prevent seeds from germinating after a fire."}, {"id": "C", "text": "Seeds that germinate immediately gain an advantage over fire-followers."}, {"id": "D", "text": "Fire-triggered germination is advantageous because it times sprouting to conditions after a fire."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0121', 'D', ARRAY['D']::TEXT[], 'The passage explains the mechanism and the benefit of timing germination to post-fire conditions.', '{"A": "The text describes some seeds, not every species.", "B": "Smoke chemicals can trigger germination.", "C": "The passage says waiting avoids shade and competition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0122', 'HDSAT-RW-M10P-0122', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Corten steel is formulated to rust in a controlled way. Its alloying elements form a dense, adherent oxide layer on the surface, which then slows further corrosion. Ordinary steel rusts through because its oxide flakes away and exposes fresh metal. Corten therefore needs the right cycle of wetting and drying to develop its protective skin; in constant damp or in salt air the layer may never stabilise.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Corten steel never corrodes at all because it contains no iron."}, {"id": "B", "text": "Corten steel resists corrosion by forming a stable oxide layer, but only under suitable weathering conditions."}, {"id": "C", "text": "Corten performs best where surfaces stay constantly wet."}, {"id": "D", "text": "Ordinary steel forms a tighter oxide layer than corten steel does."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0122', 'B', ARRAY['B']::TEXT[], 'The passage contrasts corten with ordinary steel and names the wetting cycle needed for the protective layer.', '{"A": "The text describes controlled rusting, not immunity to corrosion.", "D": "Ordinary steel''s oxide flakes away.", "C": "Constant damp can prevent the layer from stabilising."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0123', 'HDSAT-RW-M10P-0123', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Glass must be cooled slowly after shaping. Rapid cooling sets the outside while the inside is still contracting, which leaves stresses locked in the object. An annealing oven holds the piece just below its softening point and then lowers the temperature over hours, letting the interior catch up. Skip that step and a bowl may shatter weeks later, long after it has left the workshop.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Glass that cools too quickly fails immediately, never later."}, {"id": "B", "text": "Slow, controlled cooling prevents the internal stresses that make glass fail later."}, {"id": "C", "text": "Annealing raises glass above its softening point and holds it there."}, {"id": "D", "text": "Rapid cooling strengthens glass by locking the outside in compression."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0123', 'B', ARRAY['B']::TEXT[], 'The passage explains the stress created by fast cooling and the schedule that avoids it.', '{"D": "The passage presents rapid cooling as the cause of failure.", "C": "Annealing holds the piece just below the softening point.", "A": "The text says a bowl may shatter weeks later."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0124', 'HDSAT-RW-M10P-0124', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Tardigrades survive desiccation by replacing most of their body water with a sugar that turns their cells into a glass-like state. Metabolism stops, membranes hold their shape, and the animal can revive when water returns. The trick is not unique to tardigrades, but their version is unusually effective. What the sugar does is physical rather than chemical: it immobilises molecules so they cannot react or unfold.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The protective sugar works through a chemical reaction that repairs DNA."}, {"id": "B", "text": "Only tardigrades possess any mechanism for surviving desiccation."}, {"id": "C", "text": "A glass-forming sugar protects tardigrades during drought by physically immobilising their cells."}, {"id": "D", "text": "Tardigrades survive drought by keeping their normal metabolism running."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0124', 'C', ARRAY['C']::TEXT[], 'The passage describes the dried state and explains the physical protective role of the sugar.', '{"D": "The text says metabolism stops.", "A": "The passage calls the effect physical, not chemical.", "B": "The trick is not unique to tardigrades."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0125', 'HDSAT-RW-M10P-0125', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Fog-collecting nets work because droplets in fog are large enough to strike mesh fibres and coalesce. The water then runs down the strands into a trough. Fine mesh catches more droplets but clogs with dust, while coarse mesh sheds water well but misses much of it. Designers therefore tune mesh density to the local fog, which is why installations from different coastal deserts look so unlike one another.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Fine mesh always outperforms coarse mesh in every climate."}, {"id": "B", "text": "Fog nets must be tuned to local conditions because mesh density trades capture against clogging."}, {"id": "C", "text": "Mesh density has no effect on how much water a net gathers."}, {"id": "D", "text": "Fog nets collect water by condensing vapour inside a tank."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0125', 'B', ARRAY['B']::TEXT[], 'The passage explains droplet capture and the competing costs of mesh density, then links design differences to local fog.', '{"A": "Fine mesh clogs with dust, so it is not always better.", "D": "Collection relies on droplets striking mesh, not a tank.", "C": "Density is described as the key trade-off."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0126', 'HDSAT-RW-M10P-0126', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'City trees cool streets in two ways: they cast shade and they release water vapour through their leaves. Shade acts immediately on surfaces below the canopy, while evaporation lowers air temperature more gradually. A single young tree does little of either, and a row of trees in sealed pavement may never reach the size needed. Cooling benefits therefore depend on long-term growth as much as on planting.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Trees cool streets only by casting shade, with no evaporative effect."}, {"id": "B", "text": "Sealed pavement helps street trees reach full size faster."}, {"id": "C", "text": "Young trees provide more cooling than mature ones."}, {"id": "D", "text": "Urban tree cooling depends on the trees surviving and growing large, not only on how many are planted."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0126', 'D', ARRAY['D']::TEXT[], 'The passage presents the two cooling mechanisms and stresses that benefit grows with the tree.', '{"A": "The passage names evaporation as a second mechanism.", "C": "The text says a young tree does little.", "B": "Sealed pavement is described as a barrier to growth."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0127', 'HDSAT-RW-M10P-0127', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Krill gather in swarms so dense that sonar can mistake them for the seabed. The swarm is not a herd in the usual sense: individuals do not follow a leader but adjust to neighbors, and the group darkens as it thickens, which may confuse predators. Because swarms shift shape quickly, surveys that sample one patch may badly misestimate the population of a whole region.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Krill swarms form through local interactions and move in ways that make population surveys hard."}, {"id": "B", "text": "Krill swarms are led by a single dominant individual."}, {"id": "C", "text": "Sonar accurately counts krill because swarms scatter sound weakly."}, {"id": "D", "text": "Krill swarms keep a fixed shape throughout the day."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0127', 'A', ARRAY['A']::TEXT[], 'The passage explains neighbor-based grouping, the effect on predators, and the difficulty for surveys.', '{"B": "The text says individuals adjust to neighbors, not a leader.", "C": "Sonar can mistake swarms for the seabed, which is not accuracy.", "D": "The swarms shift shape quickly."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0128', 'HDSAT-RW-M10P-0128', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A lightning rod does not attract lightning from a distance. It provides a low-resistance path from roof to ground, so that a strike arriving nearby passes through metal instead of through timber. The sharp tip matters less than the continuous connection: a rod with a broken conductor is worse than none, because it invites a discharge it cannot carry away.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A lightning rod pulls strikes toward a building from far away."}, {"id": "B", "text": "The sharpness of the tip is the only feature that provides protection."}, {"id": "C", "text": "A rod with a broken conductor still protects the structure."}, {"id": "D", "text": "A lightning rod protects a building by giving current a continuous path to the ground."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0128', 'D', ARRAY['D']::TEXT[], 'The passage defines the rod''s job as a conductive path and stresses that the path must be unbroken.', '{"A": "The text denies that the rod attracts lightning from a distance.", "B": "The passage says the continuous connection matters more than the tip.", "C": "A broken conductor is described as worse than no rod."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0129', 'HDSAT-RW-M10P-0129', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Every flat map distorts something. Mercator preserves direction, which is why it suited navigation, but it stretches area toward the poles so that Greenland appears larger than Africa. A projection that preserves area must give up shape, and one that preserves shape must give up area. The choice is not a matter of accuracy but of which property a particular map is meant to show.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mercator is the only projection that preserves true area."}, {"id": "B", "text": "It is possible to preserve area, shape and direction on one flat map."}, {"id": "C", "text": "Greenland is in fact larger in area than Africa."}, {"id": "D", "text": "Map projections trade one geometric property for another, so the right map depends on its purpose."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0129', 'D', ARRAY['D']::TEXT[], 'The passage names the trade-offs and concludes that purpose determines the choice.', '{"A": "Mercator preserves direction and stretches area.", "B": "The passage says preserving one property requires giving up another.", "C": "The text uses Greenland''s apparent size as an example of distortion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0130', 'HDSAT-RW-M10P-0130', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'A camel''s hump stores fat, not water. Burning that fat releases energy and also produces water as a by-product, which helps in dry conditions. Concentrating the store on the back also keeps the animal cooler than an even layer of fat would, since heat can escape from the rest of the body. The hump therefore serves both as fuel reserve and as a way of managing heat.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Burning fat consumes water rather than producing it."}, {"id": "B", "text": "Fat spread evenly over the body would keep a camel cooler."}, {"id": "C", "text": "The hump stores energy and helps regulate heat, rather than holding water directly."}, {"id": "D", "text": "The hump is a sac of liquid water carried for long journeys."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0130', 'C', ARRAY['C']::TEXT[], 'The passage corrects the water myth and explains both the energy and heat-management roles.', '{"D": "The text says the hump stores fat, not water.", "B": "The passage says an even layer would be less cool.", "A": "Burning fat produces water as a by-product."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0131', 'HDSAT-RW-M10P-0131', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'An octopus changes color by stretching pigment sacs in its skin. Muscles pull each sac open or closed, so the change is under direct neural control and can happen in under a second. The skin also carries reflective cells that scatter light, which lets the animal match a surface even when its pigments alone could not. Color change is therefore both fast and structural.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Octopus color change is fast because it is muscular and structural rather than chemical."}, {"id": "B", "text": "The pigment sacs cannot be controlled by the animal."}, {"id": "C", "text": "Octopuses change color slowly as pigments are produced chemically."}, {"id": "D", "text": "Reflective cells prevent the skin from matching a surface."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0131', 'A', ARRAY['A']::TEXT[], 'The passage describes muscular pigment sacs and reflective cells and concludes that the mechanism is fast and structural.', '{"C": "The text says the change takes under a second and is neural.", "D": "Reflective cells help the match.", "B": "Muscles under neural control open and close the sacs."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0132', 'HDSAT-RW-M10P-0132', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A vaccine that leaves the factory must stay cold all the way to the clinic. Each transfer between a refrigerator, a vehicle and a field cooler is a chance for the chain to break. Health programs therefore attach temperature indicators to every box and train staff to reject a shipment whose indicator has changed, even if the vials look normal. The vial itself gives no warning.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Because spoiled vaccine may look unchanged, programs rely on temperature indicators and strict handling rules."}, {"id": "B", "text": "Staff can tell a spoiled shipment by inspecting the vials."}, {"id": "C", "text": "Temperature indicators are attached only after a shipment reaches a clinic."}, {"id": "D", "text": "Vaccines remain effective after any number of breaks in the cold chain."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0132', 'A', ARRAY['A']::TEXT[], 'The passage explains the fragile chain and the visual check that replaces inspecting the vials.', '{"D": "The text treats each transfer as a risk.", "B": "The passage says the vial gives no warning.", "C": "Indicators are attached to every box before transit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0133', 'HDSAT-RW-M10P-0133', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Mangrove seedlings are planted in mud that shifts with every tide. A propagule pushed into soft sediment may be washed out before its roots take hold, so planters often use bamboo stakes or biodegradable anchors. Survival also depends on hydrology: seedlings placed too low are flooded too often, while those placed too high dry out. Successful restoration is therefore a matter of choosing the right elevation as much as planting.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mangrove seedlings survive equally well at any height above the tide line."}, {"id": "B", "text": "Mangrove restoration succeeds only when seedlings are anchored and planted at the right tidal elevation."}, {"id": "C", "text": "Planting alone is enough, regardless of where seedlings are placed."}, {"id": "D", "text": "Bamboo stakes are used to raise seedlings above the reach of tides."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0133', 'B', ARRAY['B']::TEXT[], 'The passage describes the two risks, anchoring and elevation, and concludes that placement matters as much as planting.', '{"A": "The text says elevation determines flooding and drying.", "D": "Stakes anchor seedlings in soft mud; they do not raise them.", "C": "Placement is described as decisive."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0134', 'HDSAT-RW-M10P-0134', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Desert varnish is a thin dark coating that accumulates on stable rock surfaces over thousands of years. It forms as wind-blown clay and microbes deposit manganese and iron oxides. Because the coating builds slowly and only where rock stays undisturbed, archaeologists use its thickness and chemistry to estimate how long a surface has been exposed. A varnish date is a minimum age for the carving beneath it.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The coating is composed mainly of organic material from plants."}, {"id": "B", "text": "Varnish dates give the exact year a carving was made."}, {"id": "C", "text": "Desert varnish accumulates slowly on undisturbed rock and can give a minimum age for carvings."}, {"id": "D", "text": "Desert varnish forms quickly wherever rock is exposed to rain."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0134', 'C', ARRAY['C']::TEXT[], 'The passage explains the slow formation and the cautious minimum-age interpretation.', '{"D": "The text says it accumulates over thousands of years.", "B": "It provides a minimum age, not an exact year.", "A": "The coating is clay plus manganese and iron oxides."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0135', 'HDSAT-RW-M10P-0135', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'An ancient stone amphitheatre can carry a whisper from the stage to the highest tier. The curved wall reflects sound back toward the center, and the seating steps scatter it so that it arrives with little delay. Modern concrete halls often need amplification because their flat surfaces absorb or diffuse energy. The old design worked with geometry rather than with power.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The amphitheatre''s curved geometry carried sound effectively without electronic amplification."}, {"id": "B", "text": "Flat modern surfaces reflect sound more efficiently than curved ones."}, {"id": "C", "text": "Ancient amphitheatres relied on hidden amplification devices."}, {"id": "D", "text": "The seating steps absorbed sound before it reached the upper tiers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0135', 'A', ARRAY['A']::TEXT[], 'The passage contrasts curved stone geometry with flat modern surfaces and notes that the old design needed no power.', '{"C": "No amplification is described; geometry does the work.", "B": "The text says flat surfaces absorb or diffuse energy.", "D": "The steps scatter sound so it arrives with little delay."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0136', 'HDSAT-RW-M10P-0136', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A pollinator strip is a band of flowers sown along a field edge. It offers nectar and pollen through the season, so bees and hoverflies remain nearby instead of dispersing. Studies find more pollinators inside adjacent crops, though the effect depends on which flowers are sown and on whether pesticides drift onto the strip. A strip that blooms for two weeks helps far less than one that flowers across the growing season.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Pollinator strips can support nearby crops, but their benefit depends on duration and on how they are managed."}, {"id": "B", "text": "Pollinator strips work best when they bloom for only a short period."}, {"id": "C", "text": "Pesticide drift improves the value of a pollinator strip."}, {"id": "D", "text": "Any flower strip guarantees a larger harvest in the adjacent field."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0136', 'A', ARRAY['A']::TEXT[], 'The passage describes the mechanism, notes the conditional benefits, and contrasts short and long blooming.', '{"D": "The text says the effect depends on species and pesticide drift.", "B": "The passage says a long flowering season helps more.", "C": "Drift is named as a factor that can reduce the benefit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0137', 'HDSAT-RW-M10P-0137', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Newsprint made before the 1870s was manufactured from rags and remains flexible. Later papers used groundwood pulp, which retains lignin and turns brittle as it oxidises. A single brittle volume can crack its neighbors as it is shelved and pulled. Conservators therefore box each fragile item separately, slowing the transfer of acid and preventing mechanical damage from the book beside it.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Lignin-rich paper becomes brittle, so fragile volumes are boxed separately to prevent damage to neighbors."}, {"id": "B", "text": "Rag paper turns brittle faster than groundwood paper."}, {"id": "C", "text": "Lignin makes paper more flexible as it ages."}, {"id": "D", "text": "Boxing a volume increases the acid it transfers to its neighbors."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0137', 'A', ARRAY['A']::TEXT[], 'The passage contrasts the two papers and explains why separate boxes protect a collection.', '{"B": "The text says rag paper remains flexible.", "D": "Boxing slows acid transfer rather than increasing it.", "C": "The passage says lignin-bearing paper turns brittle."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0138', 'HDSAT-RW-M10P-0138', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A tidal turbine blade works in water far denser than air, so the same diameter extracts far more power than a wind turbine''s. That density also loads the blade heavily and wears its leading edge, and salt water corrodes fittings that would last decades in air. Designs therefore favor thick, simple sections that tolerate abrasion rather than the slender aerofoils used on wind farms.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Tidal turbines produce less power than wind turbines of the same diameter."}, {"id": "B", "text": "Tidal turbines gain power from dense water but must be built more ruggedly than wind turbines."}, {"id": "C", "text": "Slender aerofoil sections are preferred for tidal blades."}, {"id": "D", "text": "Salt water protects tidal turbine fittings from corrosion."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0138', 'B', ARRAY['B']::TEXT[], 'The passage explains the power advantage and the wear and corrosion penalties that shape the design.', '{"A": "The text says dense water yields far more power.", "D": "Salt water is described as corrosive.", "C": "The passage says tidal designs favor thick sections."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0139', 'HDSAT-RW-M10P-0139', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Coffee beans crack audibly twice during roasting. The first crack marks the point at which water and gases force their way out of the bean; the second comes later as the structure begins to fracture. Roasters listen for these sounds because they mark stages that are hard to judge by color alone. A bean pulled at the first crack tastes quite different from one taken past the second.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The two cracking sounds give roasters reliable markers for stages that color alone cannot show."}, {"id": "B", "text": "Beans taken at the first and second cracks taste the same."}, {"id": "C", "text": "Coffee beans crack only once, at the very end of roasting."}, {"id": "D", "text": "Roasters rely on color because the cracks are inaudible."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0139', 'A', ARRAY['A']::TEXT[], 'The passage describes the physical cause of each crack and explains why roasters use them.', '{"C": "The text describes two distinct cracks.", "D": "The passage says the cracks mark stages hard to judge by color.", "B": "The text says the flavours differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0140', 'HDSAT-RW-M10P-0140', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Banknote paper is made from cotton and linen fibres rather than wood pulp. The long fibres flex without tearing, and the sheet is sized so that ink sits on the surface instead of soaking through. A watermark is formed during manufacture by pressing the wet sheet against a shaped mould, which thins the paper in a pattern that becomes visible when held to light. The security feature is part of the sheet, not printed on it.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Durable fibres and a watermark formed within the sheet make banknote paper hard to copy."}, {"id": "B", "text": "Banknote paper is made from wood pulp for extra stiffness."}, {"id": "C", "text": "Short fibres make banknote paper more resistant to tearing."}, {"id": "D", "text": "The watermark is printed onto the finished sheet with ink."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0140', 'A', ARRAY['A']::TEXT[], 'The passage explains the fibre choice, the sizing, and the in-sheet watermark that makes the note hard to forge.', '{"B": "The text says cotton and linen, not wood pulp.", "D": "The watermark is formed during manufacture, not printed.", "C": "The passage attributes durability to long fibres."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0141', 'HDSAT-RW-M10P-0141', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A museum''s climate system is designed around slow change rather than constant conditions. Materials such as wood and ivory expand and contract as humidity shifts, and repeated cycling does more damage than a steady level slightly outside the ideal range. Curators therefore accept small departures from the target if the readings stay stable, and they watch the rate of change as closely as the value itself.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The rate of change is irrelevant if the average value is correct."}, {"id": "B", "text": "Museums should keep every gallery at the exact ideal humidity at all times."}, {"id": "C", "text": "Wood and ivory are unaffected by changes in humidity."}, {"id": "D", "text": "Stable conditions matter more than hitting an exact target, because repeated swings damage objects."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0141', 'D', ARRAY['D']::TEXT[], 'The passage contrasts cycling with stability and concludes that rate of change is a key measure.', '{"B": "The text accepts small departures when readings are stable.", "C": "The passage says such materials expand and contract.", "A": "Curators watch the rate of change closely."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0142', 'HDSAT-RW-M10P-0142', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A traditional windmill''s sails turn a central shaft that drives millstones through gears. The stones must turn at a steady speed: too fast and the flour heats and loses quality, too slow and the grain is not cut cleanly. Millers therefore adjust the gap between the stones and the amount of sail cloth according to the wind, a constant negotiation between power and control.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Sail cloth is fixed and never adjusted by the miller."}, {"id": "B", "text": "Millstones work best when they turn as fast as the wind allows."}, {"id": "C", "text": "A miller''s work is a continual adjustment of gearing and sail area to keep the stones turning at the right speed."}, {"id": "D", "text": "The gap between the stones has no effect on the flour."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0142', 'C', ARRAY['C']::TEXT[], 'The passage explains why steady speed matters and names the two controls a miller uses.', '{"B": "The text says too fast heats the flour and loses quality.", "D": "The gap is one of the two adjustments described.", "A": "Millers adjust sail cloth according to the wind."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0143', 'HDSAT-RW-M10P-0143', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A cathedral''s stained glass looks dull from outside because the colored glass is translucent, not reflective. The design assumes light passing through from behind, so the images face inward. On an overcast day the effect weakens, and on a bright day the leading between panes throws dark lines across the figures. The window is therefore a device for shaping transmitted light rather than a painted surface.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Stained glass is designed for transmitted light, which is why it looks different from outside or under changing skies."}, {"id": "B", "text": "Stained glass is painted to be read by reflected light from outside."}, {"id": "C", "text": "Overcast weather makes the images brighter and sharper."}, {"id": "D", "text": "The leading between panes has no visual effect on the figures."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0143', 'A', ARRAY['A']::TEXT[], 'The passage explains the transmission model and the visible consequences of weather and leading.', '{"B": "The text says the glass is translucent and lit from behind.", "C": "The passage says the effect weakens on overcast days.", "D": "Leading throws dark lines across the figures."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0144', 'HDSAT-RW-M10P-0144', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'An arch carries load by compression. Each stone pushes against its neighbors, and the whole curve transfers the weight outward to the supports. Because stone is strong in compression but weak in tension, an arch needs thick abutments to resist that outward push. A crack at the crown often signals that the supports have spread rather than that the stones themselves have failed.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "An arch carries load mainly through tension in its stones."}, {"id": "B", "text": "Thin abutments are sufficient because the arch pushes inward."}, {"id": "C", "text": "An arch works through compression and needs strong abutments to resist the outward thrust."}, {"id": "D", "text": "A crack at the crown always means the stones have failed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0144', 'C', ARRAY['C']::TEXT[], 'The passage explains the compressive path and interprets crown cracks as a sign of support movement.', '{"A": "The text says load travels by compression.", "B": "The arch pushes outward, so thick abutments are needed.", "D": "The passage says such a crack often indicates spreading supports."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0145', 'HDSAT-RW-M10P-0145', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'The first public aquariums were built as windows into the sea, but the water inside them quickly went stale. Early keepers learned that a tank needs circulation, light and plants to stay clear, and that a closed system collapses without them. Modern aquariums still depend on the same three elements, though they now add filters and chillers. The biology has not changed, only the machinery.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Aquarium keeping depends on circulation, light and plants, and modern equipment only refines those basics."}, {"id": "B", "text": "Modern aquariums no longer need plants or light."}, {"id": "C", "text": "Water in an aquarium improves when it is kept still."}, {"id": "D", "text": "Early aquariums stayed clear because they were sealed off from air."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0145', 'A', ARRAY['A']::TEXT[], 'The passage describes the early failures and the enduring requirements, noting that technology changed but biology did not.', '{"D": "The text says closed systems collapse.", "B": "The passage says the same three elements remain necessary.", "C": "Circulation is one of the requirements."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0146', 'HDSAT-RW-M10P-0146', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A weather station in a city park records warmer nights than one at the airport outside town. The difference is the urban heat island: buildings and roads release heat stored during the day, and the city''s rough surfaces trap it. The effect is strongest on clear, still nights, when rural ground radiates heat freely to the sky. On windy nights the two stations converge.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Windy nights produce the largest urban-rural temperature gap."}, {"id": "B", "text": "Cities are always cooler than rural areas at night."}, {"id": "C", "text": "Airport stations record the heat island more strongly than park stations."}, {"id": "D", "text": "Cities stay warmer than surrounding land mainly on clear, still nights, because built surfaces release and trap heat."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0146', 'D', ARRAY['D']::TEXT[], 'The passage defines the heat island and explains why it peaks under clear, calm conditions.', '{"B": "The text says the city park records warmer nights.", "A": "The passage says the effect is strongest on still nights.", "C": "The park station shows the warmer reading."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0147', 'HDSAT-RW-M10P-0147', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A hand saw cuts on the forward stroke because its teeth are set to lift waste clear of the kerf. Pushing the saw back does little cutting; the return stroke only repositions the blade. Sawyers therefore apply pressure on the push and relax on the return, letting the tool do the work. A saw used with even pressure both ways dulls faster and wanders from the line.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Teeth set to lift waste make the saw dull more slowly."}, {"id": "B", "text": "A hand saw is designed to cut on one stroke, so even pressure in both directions is wasteful and less accurate."}, {"id": "C", "text": "Applying pressure on the return stroke keeps the blade on line."}, {"id": "D", "text": "A hand saw cuts equally well on the forward and return strokes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0147', 'B', ARRAY['B']::TEXT[], 'The passage explains the tooth set and the correct stroke, then describes the consequences of ignoring it.', '{"D": "The text says the return stroke does little cutting.", "A": "No such claim is made about wear and the tooth set.", "C": "Even pressure both ways makes the saw wander."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0148', 'HDSAT-RW-M10P-0148', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A lighthouse lens does not need to be large to be seen far away. A Fresnel design rings a small central lens with concentric prisms, each bending light from the lamp into a narrow horizontal beam. The result is the reach of a much larger lens at a fraction of the weight and cost. The principle is still used in solar concentrators and in some vehicle lights.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Fresnel lenses work by absorbing light from the lamp and re-emitting it."}, {"id": "B", "text": "A large solid lens is cheaper to make than a Fresnel lens."}, {"id": "C", "text": "The Fresnel design was abandoned and is no longer used."}, {"id": "D", "text": "The Fresnel lens achieves long-range beams with a compact, light assembly."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0148', 'D', ARRAY['D']::TEXT[], 'The passage describes the prism rings and their advantage in reach, weight and cost.', '{"A": "The prisms bend light; absorption is not the mechanism.", "B": "The text says the design costs a fraction of a larger lens.", "C": "The principle is still used today."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0149', 'HDSAT-RW-M10P-0149', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'A salt flat looks empty but records water. As a shallow brine pool dries, minerals crystallise in a sequence determined by their solubility, leaving rings of different salts. A core through the crust therefore preserves a history of wet and dry periods. Interpreting that history requires care, because later floods can dissolve and redeposit the very layers a reader hopes to date.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Minerals crystallise in a random order unrelated to solubility."}, {"id": "B", "text": "Salt flats contain no evidence of past water."}, {"id": "C", "text": "Salt crusts record wet and dry periods in layers, though later floods can disturb the record."}, {"id": "D", "text": "Later floods make the layers easier to date."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0149', 'C', ARRAY['C']::TEXT[], 'The passage explains the layered record and the disturbance that limits interpretation.', '{"B": "The text says the flat records water history.", "A": "The sequence is determined by solubility.", "D": "Floods can dissolve and redeposit layers, complicating dating."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0150', 'HDSAT-RW-M10P-0150', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'A violin''s soundpost is a small dowel wedged between the front and back plates inside the instrument. It is not glued; friction and the curve of the plates hold it in place. Moving it a millimetre changes how the instrument responds, which is why players guard it carefully. The post transfers vibration between the plates, and a loose post can make an otherwise healthy violin sound thin.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The soundpost is glued in place so that it cannot move."}, {"id": "B", "text": "A loose soundpost improves the tone of a violin."}, {"id": "C", "text": "Its exact position has little effect on the instrument''s sound."}, {"id": "D", "text": "The soundpost is a precisely placed, unglued brace whose position and fit strongly affect a violin''s sound."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0150', 'D', ARRAY['D']::TEXT[], 'The passage describes the post''s placement and its role in transferring vibration.', '{"A": "The text says it is not glued.", "C": "A millimetre of movement changes the response.", "B": "A loose post can make the violin sound thin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0151', 'HDSAT-RW-M10P-0151', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Antarctic sponges grow extremely slowly, adding only a fraction of a millimetre each year. A specimen collected at 200 meters had growth bands that took decades to form. Because the bands record the chemistry of the water in which they formed, a single large sponge can preserve a record of changing ocean conditions stretching back further than most instrument series.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Growth bands are unrelated to the chemistry of the surrounding water."}, {"id": "B", "text": "Instrument series are always longer than a sponge''s growth record."}, {"id": "C", "text": "Antarctic sponges grow quickly enough to record daily changes in seawater."}, {"id": "D", "text": "Old sponges can serve as archives of ocean chemistry that predate modern measurements."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0151', 'D', ARRAY['D']::TEXT[], 'Slow growth plus chemistry-bearing bands means a long, pre-instrument archive.', '{"C": "The text describes growth as extremely slow.", "A": "The bands are said to record water chemistry.", "B": "The passage says the sponge record stretches back further."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0152', 'HDSAT-RW-M10P-0152', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A Roman water wheel recovered from a riverbed had wooden paddles worn thin on one face only. The wear pattern matches contact with flowing water rather than with sand or gravel. The wheel''s axle showed no sign of having been turned by an animal. Together these details suggest that the wheel was driven by the current itself.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The wear on the paddles came from abrasive gravel in the riverbed."}, {"id": "B", "text": "The wheel was turned by oxen walking on a circular track."}, {"id": "C", "text": "The wheel was never used and was abandoned before installation."}, {"id": "D", "text": "The wheel was a water-powered device rather than one turned by animals or people."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0152', 'D', ARRAY['D']::TEXT[], 'The evidence points to current-driven rotation and away from animal power or abrasion.', '{"B": "The axle shows no animal-drive wear.", "A": "The wear matches flowing water, not sand or gravel.", "C": "Use is implied by the wear pattern."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0153', 'HDSAT-RW-M10P-0153', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Bats emit calls at frequencies too high for most people to hear. A detector that records ultrasound can therefore reveal species that mist-netting misses, because nets catch only animals flying at net height. In one survey, detectors registered eight species at a site where nets had caught three. The two methods were not measuring the same thing.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The survey proved that only three species live at the site."}, {"id": "B", "text": "Acoustic detectors capture bats physically for identification."}, {"id": "C", "text": "Combining acoustic detectors with nets gives a fuller species list than either method alone."}, {"id": "D", "text": "Mist-netting is more reliable than acoustic detection for every species."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0153', 'C', ARRAY['C']::TEXT[], 'Each method samples differently, so the union is more complete than either alone.', '{"D": "Nets missed five species the detectors found.", "B": "Detectors record sound; nets catch animals.", "A": "The detectors found eight species, so three is incomplete."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0154', 'HDSAT-RW-M10P-0154', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Legumes host bacteria in root nodules that convert atmospheric nitrogen into a form plants can use. A field planted with legumes for one season contains more available nitrogen the following year, even after the plants are harvested. Farmers who rotate legumes with cereals often reduce their fertiliser use without lowering yields.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The nitrogen fixed by legumes remains in the soil and benefits the next crop."}, {"id": "B", "text": "Root-nodule bacteria convert nitrogen into a gas that plants cannot use."}, {"id": "C", "text": "Cereal yields fall whenever legumes are grown in rotation."}, {"id": "D", "text": "Legumes remove nitrogen from the soil and deplete it for later crops."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0154', 'A', ARRAY['A']::TEXT[], 'The rotation effect follows from fixed nitrogen remaining available to the following crop.', '{"D": "The passage says available nitrogen increases.", "C": "Yields are maintained while fertiliser falls.", "B": "The bacteria produce a usable form."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0155', 'HDSAT-RW-M10P-0155', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Lighthouse keepers recorded weather every few hours for over a century. Their logs note wind direction, cloud cover and the first appearance of ice. Historians comparing these entries with ships'' logs from the same waters find close agreement on storms but frequent disagreement on calm days. The keepers'' records are therefore most valuable for severe weather.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The keepers'' logs should be discarded because they disagree with ships'' logs."}, {"id": "B", "text": "Ships'' logs are unreliable because they were written at sea."}, {"id": "C", "text": "The logs are most trustworthy where independent records confirm them, especially during storms."}, {"id": "D", "text": "Calm days are the best evidence of the keepers'' accuracy."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0155', 'C', ARRAY['C']::TEXT[], 'Agreement during storms supports using the logs for severe weather, not for calm conditions.', '{"A": "Agreement on storms makes the logs useful there.", "D": "Disagreement is most frequent on calm days.", "B": "The passage does not accuse ships'' logs of unreliability."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0156', 'HDSAT-RW-M10P-0156', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Paper marbling floats pigments on a thickened bath, then lays paper on the surface to lift the pattern. Because the bath is viscous, the colors move slowly and can be combed before printing. Two sheets made minutes apart from the same bath differ, since each lift removes pigment. No two marbled sheets are identical.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The combing step prevents any pattern from forming."}, {"id": "B", "text": "Each print is unique because lifting the paper removes pigment from the bath."}, {"id": "C", "text": "Marbled sheets are identical because the bath is stirred between prints."}, {"id": "D", "text": "Pigments sink immediately in the thickened bath."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0156', 'B', ARRAY['B']::TEXT[], 'Depletion of pigment at each lift explains the uniqueness of every sheet.', '{"C": "The passage says each lift removes pigment and changes the pattern.", "D": "The viscous bath slows movement rather than sinking.", "A": "Combing shapes the pattern before printing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0157', 'HDSAT-RW-M10P-0157', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A lake core contains a thin, pale layer of volcanic ash between darker organic sediment. The ash layer is the same thickness at both ends of the lake, which is unusual for sediment that normally thins away from shore. Geologists conclude that the ash fell directly onto the lake surface across its whole extent in a very short interval.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The layer records a single airborne deposit rather than material washed in from the shore."}, {"id": "B", "text": "The lake was dry when the ash fell."}, {"id": "C", "text": "The layer was deposited by a river entering the lake."}, {"id": "D", "text": "The ash drifted in slowly from one shoreline over many years."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0157', 'A', ARRAY['A']::TEXT[], 'Uniform thickness across the basin points to airborne deposition over a short time.', '{"D": "A direct fall explains uniform thickness across the lake.", "C": "River input would thin away from the inlet.", "B": "A dry lake would not preserve an even layer in sediment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0158', 'HDSAT-RW-M10P-0158', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Nest temperature determines the sex of some turtle hatchlings. On beaches where shade from vegetation has increased, nests stay cooler and produce more males. Conservationists who move nests to open sand to protect them from tides may unintentionally raise temperatures. Protection and sex ratio can therefore pull in opposite directions.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Moving nests to open sand guarantees a balanced sex ratio."}, {"id": "B", "text": "Shade has no effect on hatchling sex."}, {"id": "C", "text": "Tides are the only threat to nests on shaded beaches."}, {"id": "D", "text": "A nest-relocation program should consider temperature as well as protection from tides."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0158', 'D', ARRAY['D']::TEXT[], 'The two goals conflict, so relocation must account for both.', '{"A": "Open sand is warmer, which skews the ratio.", "B": "The passage says temperature determines sex.", "C": "The text mentions vegetation and temperature, not only tides."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0159', 'HDSAT-RW-M10P-0159', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Iron-gall ink etches paper as it ages because it releases acid. A manuscript written in the fifteenth century may have holes where the ink was thickest, even though the surrounding paper is sound. Conservators treat such leaves cautiously: washing removes acid but can also loosen the remaining ink, so a treatment that helps the paper may erase the text.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Preservation choices must balance saving the paper against losing the writing on it."}, {"id": "B", "text": "Holes appear where the ink was thinnest."}, {"id": "C", "text": "Washing always restores both the paper and the ink."}, {"id": "D", "text": "Iron-gall ink strengthens paper where it is applied."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0159', 'A', ARRAY['A']::TEXT[], 'The risk of losing ink sets a limit on acid removal.', '{"C": "Washing can loosen the ink.", "D": "The ink releases acid and etches the paper.", "B": "Holes appear where the ink was thickest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0160', 'HDSAT-RW-M10P-0160', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Tree rings are wide in years with abundant moisture and narrow in dry years. A stand of oaks on a dry ridge shows narrow rings in the same years as a stand in a wet valley nearby. Because both stands respond to the same regional rainfall, the shared pattern lets researchers cross-date the two records and build one longer chronology.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The two stands grew at different rates and cannot be compared."}, {"id": "B", "text": "Wide rings indicate drought at both sites."}, {"id": "C", "text": "A climate signal common to both sites allows their rings to be aligned in time."}, {"id": "D", "text": "Cross-dating depends on counting rings from the outside inward."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0160', 'C', ARRAY['C']::TEXT[], 'A shared rainfall signal produces matching narrow years that align the chronologies.', '{"A": "The shared narrow years make alignment possible.", "B": "Wide rings indicate moisture, not drought.", "D": "The passage explains alignment by shared climate, not by a counting direction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0161', 'HDSAT-RW-M10P-0161', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A foraging bee that finds a rich patch returns to the hive and performs a figure-eight dance. The angle of the dance''s straight run relative to vertical corresponds to the direction of the food relative to the sun. When researchers rotated the hive, the dancers adjusted the angle, and the other bees still found the patch.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The dance encodes direction in a way that stays accurate as the hive''s orientation changes."}, {"id": "B", "text": "Rotating the hive made the other bees unable to find the patch."}, {"id": "C", "text": "The dance communicates only the distance to food, not its direction."}, {"id": "D", "text": "The angle of the dance is fixed and unrelated to the sun."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0161', 'A', ARRAY['A']::TEXT[], 'Adjustment after rotation shows the angle carries usable directional information.', '{"C": "The angle corresponds to direction.", "B": "The bees still found the patch after rotation.", "D": "The angle is measured relative to the sun."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0162', 'HDSAT-RW-M10P-0162', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Roman fish sauce was made by packing fish with salt and leaving the mixture in the sun for weeks. The salt drew water out of the tissue and suppressed the bacteria that would otherwise spoil it. Amphorae found on shipwrecks still contain residues of the sauce, and their sealed interiors kept the contents from exchanging with seawater.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The sauce survived because seawater flushed through the amphorae."}, {"id": "B", "text": "Salt encouraged the bacteria that spoil fish."}, {"id": "C", "text": "The residues found on shipwrecks are unrelated to fish sauce."}, {"id": "D", "text": "Salt preservation and sealed storage together kept the sauce chemically distinct for centuries."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0162', 'D', ARRAY['D']::TEXT[], 'Preservation plus sealing explains why residues survived intact.', '{"A": "Sealed interiors are said to have kept seawater out.", "B": "Salt suppressed spoilage bacteria.", "C": "The passage identifies the residues as the sauce."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0163', 'HDSAT-RW-M10P-0163', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Deep-sea corals grow in cold water and lack the algae that feed shallow reefs. They capture food from passing currents instead, and their skeletons grow slowly enough that a colony may be centuries old. Radiocarbon dating of a specimen showed that its base was far older than its living branches, so the colony is best understood as a long-lived structure rather than a single animal.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Deep-sea corals depend on algae for food."}, {"id": "B", "text": "The living branches are the oldest part of the colony."}, {"id": "C", "text": "The age of a coral colony is set by the whole structure, not only by its living tissue."}, {"id": "D", "text": "Cold-water corals grow faster than shallow-water corals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0163', 'C', ARRAY['C']::TEXT[], 'Dating the base older than the branches shows the structure''s age spans the whole colony.', '{"D": "The passage says their skeletons grow slowly.", "B": "The base is older than the living branches.", "A": "They lack symbiotic algae and catch food from currents."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0164', 'HDSAT-RW-M10P-0164', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Readers of old books sometimes wrote in the margins. A note may correct a printer''s error, argue with the author, or record the date a reader finished the volume. Because marginalia are attached to a specific copy, they can show how one book traveled between owners. Historians therefore treat them as evidence of reading practice rather than as damage to be removed.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "All marginal notes record the same kind of information."}, {"id": "B", "text": "The value of marginalia lies in what they reveal about the people who used a particular copy."}, {"id": "C", "text": "Removing marginalia improves the historical record."}, {"id": "D", "text": "Marginalia are valuable mainly because they restore the printed text."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0164', 'B', ARRAY['B']::TEXT[], 'The notes attach evidence of reading and ownership to a specific copy.', '{"D": "Their value is evidence of use, not restoration.", "A": "The passage lists several different kinds of note.", "C": "Historians treat the notes as evidence, not damage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0165', 'HDSAT-RW-M10P-0165', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A retreating glacier leaves a valley with steep sides and a flat floor. A river valley of similar size usually has a V-shaped cross-section, because running water cuts downward and inward. The U-shape of a glaciated valley therefore records that ice, which erodes sideways as well as downward, once filled the space.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The shape of a valley can indicate whether ice or a river formed it."}, {"id": "B", "text": "Valley shape is unrelated to the agent of erosion."}, {"id": "C", "text": "A retreating glacier leaves a deep V-shaped trench."}, {"id": "D", "text": "Rivers carve U-shaped valleys more often than glaciers do."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0165', 'A', ARRAY['A']::TEXT[], 'The contrast between U- and V-shaped profiles is the evidence for the erosional agent.', '{"D": "The text attributes U-shapes to ice and V-shapes to rivers.", "C": "Glacial valleys are described as U-shaped.", "B": "The passage draws the conclusion from shape."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0166', 'HDSAT-RW-M10P-0166', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Coffee grown under shade trees ripens more slowly than coffee grown in full sun. The slower ripening produces denser beans, and tasters often describe the cup as more complex. Yields per hectare, however, are lower under shade, and farmers must weigh the price premium against the reduced volume harvested.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Shade-grown coffee can earn more per bean while producing fewer beans overall."}, {"id": "B", "text": "Shade trees raise yields without affecting quality."}, {"id": "C", "text": "Shade-grown coffee always earns more per hectare than sun-grown coffee."}, {"id": "D", "text": "Full-sun coffee produces denser beans than shade-grown coffee."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0166', 'A', ARRAY['A']::TEXT[], 'Quality and price rise while volume falls, creating a trade-off.', '{"C": "The passage says yields are lower, so per-hectare earnings are not guaranteed.", "D": "Slower ripening under shade produces denser beans.", "B": "The text says shade lowers yields."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0167', 'HDSAT-RW-M10P-0167', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Honey often contains pollen grains from the flowers the bees visited. Because pollen grains have distinctive shapes, a sample can reveal which plants were in bloom. Analysis of a jar from a market stall showed pollen from a plant that flowers only in early spring, several months before the honey was sold. The jar was probably not from the most recent harvest.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Pollen analysis cannot distinguish one season''s honey from another''s."}, {"id": "B", "text": "Bees visit only one plant species in a season."}, {"id": "C", "text": "The jar was certainly made from artificial honey."}, {"id": "D", "text": "Pollen can date honey by showing which flowering season produced it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0167', 'D', ARRAY['D']::TEXT[], 'Season-specific pollen in a jar sold later points to an earlier harvest.', '{"A": "Distinctive pollen tied to a season is exactly what enables dating.", "C": "The passage infers age, not adulteration.", "B": "The passage describes pollen from visited flowers generally."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0168', 'HDSAT-RW-M10P-0168', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Shipworms bore into wooden hulls and pilings, digesting the wood with the help of bacteria. A hull recovered from a cold, low-oxygen harbour showed far less damage than one from a warm estuary. Conservators now store excavated timbers in tanks where oxygen is limited, because the animals that attack wood need oxygen as well as wood.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Warm water protects wood from shipworms."}, {"id": "B", "text": "Oxygen has no effect on wood-boring animals."}, {"id": "C", "text": "Limiting oxygen slows the organisms that would otherwise consume waterlogged wood."}, {"id": "D", "text": "Shipworms digest wood without the help of bacteria."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0168', 'C', ARRAY['C']::TEXT[], 'The comparison and the storage practice both turn on oxygen.', '{"A": "The warm estuary showed more damage.", "D": "The passage mentions bacterial help.", "B": "The storage method relies on oxygen limitation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0169', 'HDSAT-RW-M10P-0169', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A solar still collects drinking water by evaporating brine under a transparent cover and condensing the vapour on the underside. Output depends on sunlight and on the area of the cover. On a cloudy day a small still may produce only a few spoonfuls, while a larger still in full sun produces liters. The device is therefore a supplement rather than a stand-alone supply.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Condensation reduces the amount of water collected."}, {"id": "B", "text": "A solar still''s output is too weather-dependent to guarantee water on its own."}, {"id": "C", "text": "A solar still produces the same output in all weather."}, {"id": "D", "text": "Small stills outperform large ones in full sun."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0169', 'B', ARRAY['B']::TEXT[], 'Variable output under clouds explains why the device is a supplement.', '{"C": "The passage describes output varying with sunlight and area.", "D": "Larger stills in full sun produce liters.", "A": "Condensation is the collection step."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0170', 'HDSAT-RW-M10P-0170', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Fish ferment faster in warm weather, and salt slows the process. Communities that live where temperatures stay high use more salt in their preserved fish than communities in cooler regions. A recipe that works in one place can therefore fail in another, not because the method is wrong but because the conditions have changed.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Preservation recipes have to be adjusted to local temperature."}, {"id": "B", "text": "Salt speeds fermentation in warm weather."}, {"id": "C", "text": "Cooler regions require more salt than warmer ones."}, {"id": "D", "text": "A recipe that works in one region always works in another."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0170', 'A', ARRAY['A']::TEXT[], 'Temperature changes the rate of fermentation, so salt amounts must adapt.', '{"B": "Salt slows fermentation.", "C": "The passage says warmer communities use more salt.", "D": "The passage says a recipe can fail when conditions change."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0171', 'HDSAT-RW-M10P-0171', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A cathedral bell is tuned by grinding metal from its rim. Removing material lowers the pitch and can also change the relationships among the bell''s partial tones. Founders therefore remove metal in small stages, testing between each. A bell ground too far cannot be restored, because the metal cannot be added back.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Tuning is irreversible, so it proceeds cautiously and in measured steps."}, {"id": "B", "text": "Grinding raises the pitch of a bell."}, {"id": "C", "text": "Partial tones are unaffected by removing metal."}, {"id": "D", "text": "Founders grind the rim quickly because extra metal can be added later."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0171', 'A', ARRAY['A']::TEXT[], 'Irreversibility explains the incremental method.', '{"D": "Metal cannot be added back.", "B": "The passage says removing material lowers pitch.", "C": "Grinding can change the partial relationships."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0172', 'HDSAT-RW-M10P-0172', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Compacted soil resists root growth even when it holds enough water. Roots follow pores and cracks, and compaction closes those channels. In a field where machinery has passed repeatedly, roots may spread sideways above a hard layer instead of reaching deeper moisture. The plants survive but depend on rain in the upper soil.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Compaction makes crops more vulnerable to drought in the upper soil."}, {"id": "B", "text": "Roots grow through compacted soil more easily than through pores."}, {"id": "C", "text": "Machinery traffic improves the soil''s pore structure."}, {"id": "D", "text": "Compaction helps roots reach deeper water."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0172', 'A', ARRAY['A']::TEXT[], 'Shallow rooting ties survival to upper-soil moisture.', '{"D": "Roots are blocked from deeper layers.", "B": "Roots follow pores, which compaction closes.", "C": "Traffic is the cause of the compaction described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0173', 'HDSAT-RW-M10P-0173', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Soot deposits on cave ceilings accumulate in thin layers that record the fires below. A layer rich in charcoal indicates a larger or more frequent fire; a gap indicates a period without burning. Archaeologists reading a sequence of layers can therefore reconstruct how often people used a cave, even when no tools survive.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Soot layers form only when a cave is empty of people."}, {"id": "B", "text": "Soot layers provide a record of human activity independent of artefacts."}, {"id": "C", "text": "Charcoal-rich layers indicate cold weather rather than fires."}, {"id": "D", "text": "A gap in the layers proves that the cave was never visited."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0173', 'B', ARRAY['B']::TEXT[], 'Burning evidence alone can show occupation frequency.', '{"A": "The passage says the layers record use.", "D": "A gap indicates a period without burning, not no visits.", "C": "Charcoal richness tracks fire size or frequency."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0174', 'HDSAT-RW-M10P-0174', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Harbour sediment traps lead, copper and organic matter washed from streets and ships. A core taken near a former shipyard contains a sharp peak in copper at the depth corresponding to the yard''s busiest decades. Above that layer, concentrations fall as the yard closed and runoff was diverted. The core therefore reads as a history of industrial activity.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Chemical layers in harbour mud can be tied to the rise and fall of nearby industry."}, {"id": "B", "text": "Copper concentrations rise after the shipyard closed."}, {"id": "C", "text": "Harbour sediment carries no trace of industrial activity."}, {"id": "D", "text": "The peak in copper came from natural erosion only."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0174', 'A', ARRAY['A']::TEXT[], 'The copper profile matches the yard''s timeline.', '{"B": "Concentrations fall above the peak as the yard closed.", "C": "The passage describes clear traces.", "D": "The peak corresponds to the yard''s busiest decades."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0175', 'HDSAT-RW-M10P-0175', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Bats that hibernate through winter need high humidity as well as steady cold. Dry air draws water from their skin and wings, and an aroused bat burns fat it cannot replace until spring. A cave that is cold but draughty can therefore be worse for a colony than one that is slightly warmer but still.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Bats can replace fat easily during winter."}, {"id": "B", "text": "Air movement has no effect on hibernating bats."}, {"id": "C", "text": "Stable, humid conditions matter more to hibernating bats than cold alone."}, {"id": "D", "text": "Warm, dry caves are ideal for hibernating bats."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0175', 'C', ARRAY['C']::TEXT[], 'Humidity and stillness protect the fat reserve that must last the winter.', '{"D": "Dry air causes water loss and arousal.", "A": "The passage says fat cannot be replaced until spring.", "B": "Draughty caves are described as harmful."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0176', 'HDSAT-RW-M10P-0176', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Roof tiles are laid so that each row overlaps the one below. Water running down the slope crosses from one tile to the next without reaching the deck beneath. If the overlap is too small, wind-driven rain can be forced upward under the edge. The overlap is therefore a specification, not a decorative choice.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Overlap width must be set to withstand the weather a roof will face."}, {"id": "B", "text": "The overlap has no effect on whether rain reaches the deck."}, {"id": "C", "text": "Water runs upward across the roof under normal conditions."}, {"id": "D", "text": "A smaller overlap gives better protection in strong wind."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0176', 'A', ARRAY['A']::TEXT[], 'Weather exposure sets the minimum overlap.', '{"D": "Too small an overlap lets wind-driven rain under the edge.", "C": "Water runs down the slope; only driven rain moves upward.", "B": "The overlap determines whether water crosses safely."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0177', 'HDSAT-RW-M10P-0177', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Some plants rely on ants to carry their seeds. The seed carries a fleshy appendage that ants eat, and the seed itself is discarded underground. Seeds moved this way end up buried, where they escape drying and some seed-eaters. The plant pays a small food cost for dispersal and burial.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Seeds left on the surface survive better than buried ones."}, {"id": "B", "text": "The food reward buys the seed both transport and a safer place to germinate."}, {"id": "C", "text": "Ants destroy the seeds they carry."}, {"id": "D", "text": "The appendage prevents ants from moving the seed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0177', 'B', ARRAY['B']::TEXT[], 'Transport plus burial explains the benefit of the food cost.', '{"C": "The seed is discarded intact underground.", "D": "The appendage is the reward that attracts ants.", "A": "Burial is described as protection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0178', 'HDSAT-RW-M10P-0178', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Clipper ships carried tea from China to London, and speed mattered because early arrivals sold at higher prices. Their hulls were narrow and their sail area large, which made them fast in strong winds but hard to handle in a calm. After steamships offered reliable schedules, the clippers lost their advantage.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Reliability of arrival proved more valuable than the fastest possible passage."}, {"id": "B", "text": "Clippers remained the fastest option after steamships appeared."}, {"id": "C", "text": "Speed had no effect on the price tea fetched."}, {"id": "D", "text": "Calm weather was the clippers'' greatest advantage."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0178', 'A', ARRAY['A']::TEXT[], 'Steam''s dependable schedule displaced the clipper''s speed premium.', '{"B": "Clippers lost their advantage to steamships.", "D": "The narrow hull was hard to handle in a calm.", "C": "The passage says early arrivals sold higher."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0179', 'HDSAT-RW-M10P-0179', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Some birds lay eggs with thinner shells where the soil is low in calcium. The birds cannot manufacture calcium, so they must take it from food or grit. Studies of a population on calcium-poor ground found thinner shells and more breakages than in a population on limestone. The difference tracked geology, not species.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Birds can synthesise calcium without eating it."}, {"id": "B", "text": "Calcium-poor soil produces thicker shells."}, {"id": "C", "text": "Access to calcium in the environment shapes shell thickness in these birds."}, {"id": "D", "text": "Shell thickness is fixed by the species and cannot vary."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0179', 'C', ARRAY['C']::TEXT[], 'The geologic contrast, with the same species, isolates calcium availability.', '{"D": "The two populations differ within the same species.", "B": "Thin shells occur on poor ground.", "A": "The passage says birds must obtain calcium from food or grit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0180', 'HDSAT-RW-M10P-0180', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Residue inside Roman amphorae can be identified by its chemical signature. Jars found in a storage room contained traces of olive oil, while jars from a nearby shop contained fish sauce. The two sets were the same shape. Shape alone therefore does not tell an archaeologist what a vessel carried.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Fish sauce and olive oil leave identical residues."}, {"id": "B", "text": "Contents must be identified chemically, because form does not reveal use."}, {"id": "C", "text": "All jars in a storage room held the same product."}, {"id": "D", "text": "Amphora shape reliably indicates what was stored inside."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0180', 'B', ARRAY['B']::TEXT[], 'Same shape, different contents forces chemical identification.', '{"D": "Identical shapes held different contents.", "A": "The distinction comes from chemical signatures.", "C": "The passage contrasts two nearby sets."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0181', 'HDSAT-RW-M10P-0181', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Pencil leads are graded by hardness, which depends on the ratio of graphite to clay. More clay makes a harder lead that holds a sharp point and prints lightly; more graphite makes a softer lead that darkens the page and wears quickly. A drafter choosing a lead is choosing between precision and darkness.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The graphite-to-clay ratio has no effect on wear."}, {"id": "B", "text": "Hard leads darken the page more than soft leads."}, {"id": "C", "text": "No single lead suits both fine detail and dense shading equally well."}, {"id": "D", "text": "Clay increases the darkness of a pencil line."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0181', 'C', ARRAY['C']::TEXT[], 'The trade-off between point retention and darkness is the basis of the grading scale.', '{"B": "Hard leads print lightly; soft leads darken.", "D": "Graphite provides darkness, not clay.", "A": "The ratio determines both darkness and wear."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0182', 'HDSAT-RW-M10P-0182', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A bleached coral reef can recover if the algae that live inside the coral return while the coral is still alive. Recovery is slower where the reef is also stressed by sediment or warm water. Surveys find that reefs with cleaner water regain color sooner after a bleaching event than reefs near river mouths.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Bleached coral is always dead and cannot recover."}, {"id": "B", "text": "Sediment speeds the return of algae to coral."}, {"id": "C", "text": "Warm water improves recovery after bleaching."}, {"id": "D", "text": "Reducing local stress helps a reef recover from bleaching."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0182', 'D', ARRAY['D']::TEXT[], 'The comparison points to local stress as a brake on recovery.', '{"B": "Cleaner-water reefs recovered sooner.", "A": "The passage describes recovery while the coral is alive.", "C": "Warm water is named as an additional stress."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0183', 'HDSAT-RW-M10P-0183', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Salmon that die after spawning leave carcasses in streams. Their bodies carry nitrogen from the ocean, which enters the food web as the carcasses decay. Trees along a stream with many spawning salmon contain more marine-derived nitrogen than trees along a stream without them. The forest is therefore linked to the ocean by the fish.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Marine nutrients reach streamside forests through the bodies of spawning fish."}, {"id": "B", "text": "Trees cannot take up nitrogen from decaying fish."}, {"id": "C", "text": "Salmon remove nitrogen from streamside forests."}, {"id": "D", "text": "The connection exists only in streams without spawning salmon."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0183', 'A', ARRAY['A']::TEXT[], 'The nitrogen signature in trees traces the marine source through the carcasses.', '{"B": "The passage reports elevated nitrogen in those trees.", "C": "The carcasses add nitrogen.", "D": "The contrast is between streams with and without salmon."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0184', 'HDSAT-RW-M10P-0184', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A windmill''s sails turn a shaft, and gearing converts that slow, powerful rotation into a faster one at the millstone. Changing the gear ratio changes the speed of the stone without changing the wind. Millers keep several gears on hand so that a strong wind and a light one can both be used.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Gearing lets a miller match the stone''s speed to the available wind."}, {"id": "B", "text": "A single fixed gear ratio suits every wind condition."}, {"id": "C", "text": "The millstone turns more slowly than the shaft in all gears."}, {"id": "D", "text": "Gearing changes the amount of wind reaching the sails."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0184', 'A', ARRAY['A']::TEXT[], 'Multiple gears exist to keep stone speed steady across wind strengths.', '{"D": "Gearing converts rotation, not wind.", "B": "The passage describes changing ratios for different winds.", "C": "The gearing speeds the rotation up at the stone."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0185', 'HDSAT-RW-M10P-0185', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A manuscript written with acidic ink can lose text at the same time it loses paper. Washing a leaf removes acid but may also lift the ink, so conservators first test a small, unimportant area. If the ink survives the test, the leaf can be washed; if not, it is stored dry and digitised instead.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Every leaf can be washed safely with acidic ink."}, {"id": "B", "text": "Testing a small area damages the whole manuscript."}, {"id": "C", "text": "Digitisation removes acid from the paper."}, {"id": "D", "text": "Treatment decisions depend on evidence from a test before the whole leaf is exposed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0185', 'D', ARRAY['D']::TEXT[], 'The small-area test governs whether the full treatment is safe.', '{"A": "Washing may lift the ink.", "B": "The test uses an unimportant area precisely to avoid damage.", "C": "Digitisation creates a copy; it does not treat the paper."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0186', 'HDSAT-RW-M10P-0186', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Moss on a stone wall is thickest on the side that receives the most moisture, not always the side that receives the most light. On a wall shaded by trees, moss may cover the whole face, while an exposed wall carries moss in a band near the ground. Anyone reading moss as a compass would need to know the local conditions.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Moss requires full sunlight and avoids damp surfaces."}, {"id": "B", "text": "Moss always grows on the north side of a wall regardless of shade."}, {"id": "C", "text": "A shaded wall carries less moss than an exposed one."}, {"id": "D", "text": "Moss growth reflects moisture and shade, so it is an unreliable direction indicator without local context."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0186', 'D', ARRAY['D']::TEXT[], 'Moisture and shade dominate, which defeats naive compass use.', '{"B": "The passage says moisture matters more than direction.", "A": "Moss is thickest where moisture is greatest.", "C": "The shaded wall may be covered entirely."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0187', 'HDSAT-RW-M10P-0187', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Volcanic lightning occurs in ash clouds when particles collide and separate charge. The effect is more common in eruptions that produce fine ash and vigorous convection. Observers have used lightning detection to track eruptions at night and in bad weather, when cameras see little. The electrical signal becomes a remote sensing tool.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Volcanic lightning occurs only in eruptions with no ash."}, {"id": "B", "text": "Cameras see eruptions better at night than detectors do."}, {"id": "C", "text": "Lightning detection replaces the need to monitor volcanoes."}, {"id": "D", "text": "Detecting lightning can reveal an eruption that visibility would hide."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0187', 'D', ARRAY['D']::TEXT[], 'The electrical signal works when visual observation fails.', '{"A": "The passage ties lightning to fine ash and convection.", "C": "It is a tool, not a replacement for monitoring.", "B": "The text says cameras see little at night and in bad weather."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0188', 'HDSAT-RW-M10P-0188', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Wool takes dye unevenly if its scales are damaged. Makers therefore clean fleece gently and avoid sudden temperature changes during dyeing, since a rapid shift can shock the fibres. A dye lot that looks patchy often records a handling error rather than a fault in the dye itself.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Rapid temperature changes improve the evenness of dye uptake."}, {"id": "B", "text": "Damaged scales help wool absorb dye uniformly."}, {"id": "C", "text": "Even color depends on gentle handling as much as on the dye recipe."}, {"id": "D", "text": "Patchiness always indicates a faulty dye."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0188', 'C', ARRAY['C']::TEXT[], 'Handling errors, not the dye, explain many patchy lots.', '{"A": "The passage warns that rapid shifts shock the fibres.", "B": "Damage is described as causing uneven uptake.", "D": "Patchiness often reflects handling, not the dye."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0189', 'HDSAT-RW-M10P-0189', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Charcoal in lake sediment comes from fires in the surrounding catchment. A layer with abundant charcoal often coincides with a shift from forest pollen to grass pollen. The two signals together suggest that fire removed trees and allowed grasses to spread. Neither signal alone would establish the sequence.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Charcoal layers indicate that no fire occurred in the catchment."}, {"id": "B", "text": "Combining charcoal and pollen evidence links fire to vegetation change."}, {"id": "C", "text": "Pollen shifts always precede fires by several centuries."}, {"id": "D", "text": "Grass pollen excludes the possibility of fire."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0189', 'B', ARRAY['B']::TEXT[], 'The coincidence of the two proxies is what ties fire to the vegetation shift.', '{"A": "Charcoal records fire.", "C": "The signals are described as coinciding.", "D": "Grass pollen follows fire in the proposed sequence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0190', 'HDSAT-RW-M10P-0190', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A tea clipper''s narrow hull reduced drag but also reduced cargo space. Owners packed light, high-value cargo such as tea and raced for the first market. When the Suez Canal opened, steamships could take a shorter route that sailing ships could not use reliably. The clippers'' advantage narrowed.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Narrow hulls increased cargo capacity."}, {"id": "B", "text": "A route change reduced the value of the clippers'' speed and small capacity."}, {"id": "C", "text": "Clippers carried bulk cargo more cheaply after the canal opened."}, {"id": "D", "text": "The Suez Canal made the clippers'' route shorter than the steamships''."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0190', 'B', ARRAY['B']::TEXT[], 'The canal favored steam, eroding the clipper''s niche.', '{"D": "Steamships took the shorter route the clippers could not use.", "C": "Clippers carried light, high-value cargo.", "A": "The passage says the narrow hull reduced capacity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0191', 'HDSAT-RW-M10P-0191', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A bell foundry casts a bell slightly larger than its final size because tuning removes metal. The founder also adjusts the profile so that the bell''s partial tones form the intended chord. Changing the profile after casting is nearly impossible, so the shape must be right before the metal cools.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Tuning adds metal to raise the pitch."}, {"id": "B", "text": "The partial tones are unrelated to the bell''s shape."}, {"id": "C", "text": "A bell''s profile can be reshaped easily after casting."}, {"id": "D", "text": "Most of a bell''s tonal character is fixed at casting, with tuning only refining it."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0191', 'D', ARRAY['D']::TEXT[], 'Since profile cannot be changed later, the cast shape carries the tonal design.', '{"C": "The passage says reshaping after casting is nearly impossible.", "A": "Tuning removes metal.", "B": "The profile is adjusted to shape the partials."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0192', 'HDSAT-RW-M10P-0192', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'An oyster reef filters water as its inhabitants feed. A dense reef can clear suspended particles from a large volume in a day. When reefs were removed, water clarity fell and sunlight reached less deeply. Seagrasses, which need light, declined in the same estuaries.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Water clarity improved after reefs were removed."}, {"id": "B", "text": "Oyster reefs increase suspended particles in the water."}, {"id": "C", "text": "Losing oyster reefs can reduce water clarity enough to harm seagrass."}, {"id": "D", "text": "Seagrasses grow better in turbid water."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0192', 'C', ARRAY['C']::TEXT[], 'Filtration loss, lower clarity and seagrass decline form the causal chain.', '{"B": "The reef filters particles out.", "D": "Seagrass needs light, which turbidity blocks.", "A": "The passage says clarity fell."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0193', 'HDSAT-RW-M10P-0193', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A mudbrick wall shrinks as it dries. If the outer surface dries faster than the core, the difference in shrinkage pulls the surface apart. Builders therefore mix straw into the clay, which slows drying and gives the shrinking mass something to hold onto. The cracks that appear in unstrawed brick begin at the surface.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Mudbrick does not change size as it dries."}, {"id": "B", "text": "Straw reduces cracking by evening out the drying of a mudbrick."}, {"id": "C", "text": "Straw speeds drying and increases surface shrinkage."}, {"id": "D", "text": "Cracks in unstrawed brick start at the core."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0193', 'B', ARRAY['B']::TEXT[], 'Straw moderates the moisture gradient that causes surface cracking.', '{"C": "The passage says straw slows drying.", "A": "The wall shrinks as it dries.", "D": "The text says cracks begin at the surface."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0194', 'HDSAT-RW-M10P-0194', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Goats browse young trees before they can grow above reach. On islands where goats were removed, tree lines moved upslope within decades. On islands where goats remained, the same species stayed low and sparse. The difference between the islands tracks the presence of goats rather than climate.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Goats help young trees grow above browsing height."}, {"id": "B", "text": "Removing goats prevented trees from spreading."}, {"id": "C", "text": "Grazing animals can hold a tree line in place."}, {"id": "D", "text": "Tree lines are determined entirely by temperature."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0194', 'C', ARRAY['C']::TEXT[], 'The island comparison isolates grazing as the cause.', '{"D": "The paired islands share climate but differ in goats.", "B": "Tree lines moved upslope after removal.", "A": "Goats browse young trees before they escape reach."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0195', 'HDSAT-RW-M10P-0195', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Lichens absorb water and nutrients directly through their surfaces, which also means they absorb pollutants. A lichen transplanted from a clean site to a city center accumulates metals within months. Species differ in tolerance, so a survey of which lichens survive can map pollution without instruments.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Lichens filter out pollutants and remain unaffected."}, {"id": "B", "text": "Lichen communities can act as biological pollution monitors."}, {"id": "C", "text": "All lichen species respond to pollution in the same way."}, {"id": "D", "text": "Transplanted lichens cannot accumulate metals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0195', 'B', ARRAY['B']::TEXT[], 'Absorption plus species-specific tolerance supports biomonitoring.', '{"A": "The passage says they absorb pollutants.", "C": "Tolerance differs by species.", "D": "The transplant accumulated metals within months."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0196', 'HDSAT-RW-M10P-0196', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Dredging records show how often a harbour was cleared. Sediment cores show layers of coarse material where dredging mixed the bed. Where the two records agree, historians can date a period of increased shipping. Where they disagree, one source is probably incomplete.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Disagreement proves both records are correct."}, {"id": "B", "text": "Agreement between independent records strengthens a claim about harbour use."}, {"id": "C", "text": "Dredging records and sediment cores always agree."}, {"id": "D", "text": "Coarse sediment indicates that no dredging occurred."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0196', 'B', ARRAY['B']::TEXT[], 'Cross-checking two independent records is what supports the dating.', '{"C": "The passage describes cases where they disagree.", "D": "Mixed beds leave coarse layers.", "A": "Disagreement is explained as incompleteness in one source."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0197', 'HDSAT-RW-M10P-0197', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In permafrost, ice wedges form when meltwater enters cracks and refreezes. Repeated widening pushes the surrounding ground upward and outward, creating patterned polygons at the surface. Where the climate warms, wedges melt and the polygons subside. The pattern is therefore a visible record of ground temperature.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The patterns are unrelated to temperature."}, {"id": "B", "text": "Melting ice wedges raises the ground surface."}, {"id": "C", "text": "Changing polygon patterns can signal thawing permafrost."}, {"id": "D", "text": "Polygons form only where the ground never freezes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0197', 'C', ARRAY['C']::TEXT[], 'The surface pattern tracks the state of the ice wedges.', '{"D": "Freezing meltwater is the mechanism.", "B": "Melting causes subsidence.", "A": "The passage links the pattern to ground temperature."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0198', 'HDSAT-RW-M10P-0198', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A fresco is painted on wet lime plaster. As the plaster sets, the pigment becomes part of the wall, which is why the color lasts. The painter must work quickly, because once the plaster dries the surface will not accept pigment in the same way. Frescoes were therefore planned in sections sized to one day''s work.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "A painter could return to the same section weeks later."}, {"id": "B", "text": "The technique''s durability depends on painting before the plaster sets."}, {"id": "C", "text": "Fresco pigment sits on top of dry plaster."}, {"id": "D", "text": "The sections were sized to the painter''s arm length only."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0198', 'B', ARRAY['B']::TEXT[], 'The wet-plaster window explains both durability and the daily section plan.', '{"C": "The pigment becomes part of the wall as it sets.", "A": "Dry plaster will not accept pigment the same way.", "D": "Sections matched a day''s work, not arm length."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0199', 'HDSAT-RW-M10P-0199', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A bridge cable is protected from rust by a galvanised coating that corrodes before the steel beneath. The coating is sacrificial: it gives up metal so the cable does not. Once the coating is consumed, the steel begins to rust, so inspectors measure coating thickness rather than waiting for visible damage.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "Inspectors should ignore the coating and wait for rust."}, {"id": "B", "text": "Measuring the protective layer gives earlier warning than looking for rust."}, {"id": "C", "text": "Galvanising makes steel immune to corrosion."}, {"id": "D", "text": "The coating outlasts the steel it protects."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0199', 'B', ARRAY['B']::TEXT[], 'Coating thickness is an early indicator of remaining protection.', '{"C": "The coating corrodes so the steel does not.", "A": "By the time rust shows, the coating is gone.", "D": "Once consumed, the steel begins to rust."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0200', 'HDSAT-RW-M10P-0200', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'A fish''s otolith grows in annual rings, much like a tree. The rings record the temperature and chemistry of the water the fish inhabited, and a single otolith carries the whole life history of one animal. Researchers can therefore place a fish in particular waters at particular ages, even after it has been caught far away.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "An otolith changes after the fish dies, erasing its history."}, {"id": "B", "text": "Otoliths preserve a dated record of the environments a fish moved through."}, {"id": "C", "text": "Otoliths grow without annual layers."}, {"id": "D", "text": "Otolith rings record only the fish''s age, not its environment."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0200', 'B', ARRAY['B']::TEXT[], 'Annual layers with environmental chemistry allow life-history reconstruction.', '{"D": "The rings record water chemistry as well as age.", "A": "The record survives in the recovered ear stone.", "C": "The passage describes annual rings."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0201', 'HDSAT-RW-M10P-0201', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In stony deserts, stones sometimes sit on pedestals of fine soil. Wind removes the loose material around a stone but cannot lift the stone itself, so the ground beneath it erodes more slowly. Over time the stone appears to rise. The pedestal is therefore a record of wind erosion, not of the stone being pushed upward.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "The stone is gradually lifted by rising air currents."}, {"id": "B", "text": "Pedestals form only where the ground is fully protected from wind."}, {"id": "C", "text": "The surrounding ground has been lowered, leaving the stone elevated."}, {"id": "D", "text": "Wind deposits soil beneath the stone."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0201', 'C', ARRAY['C']::TEXT[], 'Differential deflation lowers the surrounding plain.', '{"A": "Deflation removes material around the stone.", "D": "The pedestal remains because erosion is slower beneath the stone.", "B": "Wind erosion is the mechanism, not protection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0202', 'HDSAT-RW-M10P-0202', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Many mushrooms fruit after rain, but rain alone is not enough. The mycelium must already have stored enough nutrients, and the air must cool enough to trigger development. A dry summer followed by a single storm often produces no flush, while a wet autumn with mild nights produces a large one.', 'Which choice most logically completes the text?', '[{"id": "A", "text": "A single storm is sufficient to produce a mushroom flush."}, {"id": "B", "text": "Mycelium stores no nutrients before fruiting."}, {"id": "C", "text": "Mushrooms fruit best in dry, warm conditions."}, {"id": "D", "text": "Fruiting depends on accumulated reserves and temperature as well as moisture."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0202', 'D', ARRAY['D']::TEXT[], 'The passage names three conditions, not one.', '{"A": "The passage says rain alone is not enough.", "C": "Cooling nights and wet weather favor fruiting.", "B": "Reserves are described as necessary."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0203', 'HDSAT-RW-M10P-0203', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'People often assume that a desert is empty of life because it looks bare. A closer look at a single square meter of sand can reveal seeds, dormant eggs and buried insects waiting for rain. Within days of a storm, the same ground may be covered with seedlings and insects that were invisible before.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two deserts and concludes that they are identical."}, {"id": "B", "text": "It states a common assumption and then presents evidence that contradicts it."}, {"id": "C", "text": "It lists several causes and ranks them by importance."}, {"id": "D", "text": "It describes a process step by step from beginning to end."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0203', 'B', ARRAY['B']::TEXT[], 'The passage opens with an assumption, then offers hidden life as the correction.', '{"C": "There is no ranking of causes.", "D": "No sequential process is described.", "A": "Only one setting is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0204', 'HDSAT-RW-M10P-0204', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A hand loom and a power loom produce the same cloth, but they organize work differently. On a hand loom the weaver controls pace and pattern at every pass. A power loom fixes the pace and moves pattern control into the punch card or the computer. The change is less about speed than about where decisions sit.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To explain how mechanisation shifted control over pattern and pace away from the weaver."}, {"id": "B", "text": "To describe the technical steps of warping a loom."}, {"id": "C", "text": "To show that power looms produce no patterned cloth."}, {"id": "D", "text": "To argue that hand-woven cloth is of better quality."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0204', 'A', ARRAY['A']::TEXT[], 'The passage contrasts two looms and locates the real change in decision-making.', '{"D": "Quality is not compared.", "B": "Warping is never mentioned.", "C": "Pattern control is relocated, not eliminated."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0205', 'HDSAT-RW-M10P-0205', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Early maps of the ocean floor were assembled from lead lines dropped over the side. Each sounding gave one depth at one point. A century later, sonar surveyed whole swaths in a single pass. The difference is not merely accuracy: it is the shift from a scatter of points to a continuous surface.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that early maps were more accurate than sonar maps."}, {"id": "B", "text": "It contrasts two surveying methods and explains what the change made possible."}, {"id": "C", "text": "It narrates a single voyage in chronological order."}, {"id": "D", "text": "It lists the materials used to build sounding lines."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0205', 'B', ARRAY['B']::TEXT[], 'The passage juxtaposes lead-line and sonar surveys and names the conceptual gain.', '{"C": "No voyage is described.", "D": "Materials are not listed.", "A": "Sonar is presented as the advance."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0206', 'HDSAT-RW-M10P-0206', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A paper conservator faced with a brittle volume has two options. Washing removes acid but risks the ink. Deacidification spray neutralises acid with less moisture but penetrates unevenly. The choice depends on the ink, the paper and how much time the collection can spare.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains why brittle paper cannot be treated at all."}, {"id": "B", "text": "It presents two options, notes the risk of each, and says the choice is conditional."}, {"id": "C", "text": "It describes the history of paper manufacture in order."}, {"id": "D", "text": "It recommends one treatment as correct in every case."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0206', 'B', ARRAY['B']::TEXT[], 'Two treatments, their risks, and conditional advice structure the passage.', '{"D": "The passage says the choice is conditional.", "C": "No manufacturing history is given.", "A": "Treatments are offered, not ruled out."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0207', 'HDSAT-RW-M10P-0207', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Bamboo is often called a grass, and the label matters. It grows from an underground rhizome, sends up hollow stems, and dies back after flowering. Each of these traits is shared with grasses and not with the trees it resembles. The resemblance to wood is a matter of size, not of family.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To describe how bamboo is harvested and dried."}, {"id": "B", "text": "To explain why bamboo''s botanical traits place it with grasses rather than trees."}, {"id": "C", "text": "To compare the strength of bamboo and steel."}, {"id": "D", "text": "To argue that bamboo should be classified as a hardwood."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0207', 'B', ARRAY['B']::TEXT[], 'Shared grass traits are the evidence behind the classification.', '{"D": "The passage separates bamboo from trees.", "A": "Harvesting is not discussed.", "C": "No strength comparison appears."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0208', 'HDSAT-RW-M10P-0208', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A new bridge design was tested in a wind tunnel at increasing speeds. At low speeds the deck behaved as predicted. At a critical speed the deck began to twist, and the twisting grew instead of settling. The test was stopped, and the section was reshaped before the next run.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two bridge designs and declares one superior."}, {"id": "B", "text": "It explains the theory of wind loading without describing a test."}, {"id": "C", "text": "It lists several failures from different laboratories."}, {"id": "D", "text": "It narrates a test in sequence and ends with the response to a failure."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0208', 'D', ARRAY['D']::TEXT[], 'The passage follows the test from low speed to failure to redesign.', '{"A": "Only one design is tested.", "B": "A concrete test is described.", "C": "There is a single test sequence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0209', 'HDSAT-RW-M10P-0209', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Salt marshes absorb wave energy, store carbon and shelter young fish. They also migrate inland as sea level rises, but only if the land behind them is open. Where a seawall blocks that retreat, the marsh is squeezed against a hard edge and drowns. Protection therefore depends on what lies behind the marsh.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the formation of salt marshes from bare mud."}, {"id": "B", "text": "It argues that seawalls are the best way to protect marshes."}, {"id": "C", "text": "It lists benefits, introduces a condition for survival, and draws a conclusion about that condition."}, {"id": "D", "text": "It compares marshes in two countries and finds no difference."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0209', 'C', ARRAY['C']::TEXT[], 'Benefits, a migration condition, and the blocking seawall build to the conclusion.', '{"A": "Formation from mud is not described.", "B": "Seawalls are the obstacle in the example.", "D": "No country comparison appears."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0210', 'HDSAT-RW-M10P-0210', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The claim that goldfish have three-second memories is repeated so often that it has become a fact in popular telling. Experiments with trained fish show them returning to a feeding site weeks later. The repetition of the claim, not the evidence, explains its persistence.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To confirm that goldfish memory lasts only seconds."}, {"id": "B", "text": "To challenge a widely repeated claim by pointing to contrary evidence."}, {"id": "C", "text": "To explain how to train a goldfish to feed on cue."}, {"id": "D", "text": "To describe the anatomy of the goldfish brain."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0210', 'B', ARRAY['B']::TEXT[], 'The passage sets a popular claim against experimental evidence and explains its persistence.', '{"C": "Training is mentioned as evidence, not as instruction.", "A": "The passage contradicts the three-second claim.", "D": "Anatomy is never discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0211', 'HDSAT-RW-M10P-0211', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A weaver preparing a warp winds hundreds of threads onto a beam, keeping each at even tension. If one thread is tighter, it pulls the cloth out of shape later. The preparation is slow and invisible in the finished fabric, which is why it is easy to skimp and expensive to get wrong.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To compare two kinds of loom in detail."}, {"id": "B", "text": "To describe the visible pattern of a finished cloth."}, {"id": "C", "text": "To explain why an invisible preparatory step matters to the final product."}, {"id": "D", "text": "To argue that warp preparation can safely be skipped."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0211', 'C', ARRAY['C']::TEXT[], 'The passage connects an unseen preparation to a visible consequence.', '{"B": "The step''s invisibility is the point.", "D": "Skimping is described as costly.", "A": "Looms are not compared here."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0212', 'HDSAT-RW-M10P-0212', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Some seeds remain dormant for decades even when conditions seem right. Scarification, whether by heat, abrasion or passage through an animal, can break that dormancy. The seed is not waiting passively; it is holding a lock that only particular events can open.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes an observation, illustrates it with examples, and closes with a comparison."}, {"id": "B", "text": "It argues that dormancy is simply a passive waiting period."}, {"id": "C", "text": "It lists the chemical steps of germination in order."}, {"id": "D", "text": "It presents a chronological history of seed science."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0212', 'A', ARRAY['A']::TEXT[], 'Observation, examples, then the lock metaphor shape the passage.', '{"D": "No historical sequence is offered.", "B": "The final sentence rejects pure passivity.", "C": "Chemical steps are not given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0213', 'HDSAT-RW-M10P-0213', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'An acoustic engineer testing a lecture hall found that speech was clear in the front rows but muddled at the back. The ceiling reflected sound back to the front while the rear received echoes from a flat wall. Adding curved diffusers at the rear changed the pattern without adding amplification.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that amplification is the only solution."}, {"id": "B", "text": "It compares two halls and finds both equally clear."}, {"id": "C", "text": "It describes a problem, identifies its cause, and reports a solution."}, {"id": "D", "text": "It lists materials used in hall construction."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0213', 'C', ARRAY['C']::TEXT[], 'Problem, cause and remedy structure the paragraph.', '{"B": "Only one hall is discussed.", "D": "Materials are incidental.", "A": "The solution avoids amplification."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0214', 'HDSAT-RW-M10P-0214', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A river that once meandered across a floodplain was straightened for navigation. The shortened channel carried water away faster, which deepened the bed and lowered the water table beside it. Farmland that had relied on the high water table dried, and the river began to cut downward rather than spread sideways.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces a chain of consequences that followed a single alteration."}, {"id": "B", "text": "It argues that straightening a river has no downstream effects."}, {"id": "C", "text": "It describes the construction of a navigation lock."}, {"id": "D", "text": "It compares two rivers and ranks their water quality."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0214', 'A', ARRAY['A']::TEXT[], 'The paragraph moves from straightening to deepening to a lowered water table and dried farmland.', '{"D": "One river is followed.", "C": "No lock construction is described.", "B": "Consequences are the subject of the passage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0215', 'HDSAT-RW-M10P-0215', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A museum label once told visitors that a wooden mask was used in ceremonies. No record supported the claim. When the catalog was revised, the label was replaced with a note that the mask''s use is unknown and that the wood dates to the twelfth century. The absence of evidence became part of the display.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To prove that the mask was used in ceremonies."}, {"id": "B", "text": "To show how acknowledging missing evidence can improve an exhibit."}, {"id": "C", "text": "To describe the carving techniques used on the mask."}, {"id": "D", "text": "To explain how wooden objects are dated by museums."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0215', 'B', ARRAY['B']::TEXT[], 'The revision turns an unsupported claim into an honest label.', '{"C": "Carving is not described.", "A": "The passage says the ceremony claim lacked support.", "D": "Dating is mentioned but not explained."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0216', 'HDSAT-RW-M10P-0216', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Two methods exist for measuring a forest''s carbon. One counts every tree in sample plots and estimates the rest. The other uses laser scanning from an aircraft to map canopy height. Plot counts are accurate but slow; scanning is fast but needs calibration against plots. Neither stands alone.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that forest carbon cannot be measured."}, {"id": "B", "text": "It describes a single method in step-by-step detail."}, {"id": "C", "text": "It compares two methods, names the limits of each, and concludes that they depend on one another."}, {"id": "D", "text": "It recommends abandoning plot counts in favor of scanning."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0216', 'C', ARRAY['C']::TEXT[], 'The contrast and the calibration requirement produce the joint conclusion.', '{"D": "Plot counts are needed for calibration.", "B": "Two methods are compared.", "A": "Measurement is described as possible."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0217', 'HDSAT-RW-M10P-0217', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A bell is rung once and the sound continues for many seconds. A listener hears a fundamental note plus weaker tones above it. The shape of the bell determines which of those tones are strong, and shifting one part of the profile can make a bell sound bright or dull without changing its fundamental pitch.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To describe the metal alloy used in bell casting."}, {"id": "B", "text": "To explain how a bell''s shape shapes its tone beyond the fundamental note."}, {"id": "C", "text": "To argue that a bell produces only one tone."}, {"id": "D", "text": "To explain how bell ringers time their strokes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0217', 'B', ARRAY['B']::TEXT[], 'The passage links profile shape to the strength of upper tones.', '{"A": "Alloy is not mentioned.", "C": "The passage describes multiple tones.", "D": "Ringing technique is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0218', 'HDSAT-RW-M10P-0218', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Coastal dunes form when wind carries sand inland until vegetation slows it. The plants trap grains, and the dune grows upward. A single storm can cut the dune back, but the roots usually survive. The dune is therefore built slowly and destroyed quickly, a pattern that shapes how coastlines are managed.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains a formation process, notes a countervailing force, and draws a management implication."}, {"id": "B", "text": "It argues that storms build dunes faster than vegetation does."}, {"id": "C", "text": "It lists the plant species found on dunes."}, {"id": "D", "text": "It tells the history of one particular coastline."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0218', 'A', ARRAY['A']::TEXT[], 'Growth, storm damage and management follow one another.', '{"D": "No specific coastline is followed.", "B": "Storms cut dunes back.", "C": "Species are not listed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0219', 'HDSAT-RW-M10P-0219', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Every year the same lake freezes later than it did a century ago. Records kept by a monastery note the first day of ice each winter. The series is not continuous, but the trend survives the gaps. A record kept for another purpose has become evidence for a changing climate.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To compare two lakes and explain their differences."}, {"id": "B", "text": "To describe the physics of lake freezing in detail."}, {"id": "C", "text": "To argue that the monastery records are useless."}, {"id": "D", "text": "To show how an incidental historical record can document long-term change."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0219', 'D', ARRAY['D']::TEXT[], 'The final sentence states the reinterpretation of an old record.', '{"B": "The physics is not the subject.", "C": "The records are presented as valuable.", "A": "Only one lake is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0220', 'HDSAT-RW-M10P-0220', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A chef testing a new oven found that the same recipe produced different results on different shelves. The top shelf browned too quickly, the bottom stayed pale. The chef rotated the trays halfway through and the variation fell. The oven''s heat was uneven, and the method had been hiding it.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that oven shelves make no difference."}, {"id": "B", "text": "It lists the ingredients of the recipe."}, {"id": "C", "text": "It compares two ovens made by different manufacturers."}, {"id": "D", "text": "It reports observations, describes a fix, and explains what the observations revealed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0220', 'D', ARRAY['D']::TEXT[], 'Observation, remedy and diagnosis form the sequence.', '{"A": "Shelf position is the variable.", "B": "Ingredients are not listed.", "C": "One oven is tested."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0221', 'HDSAT-RW-M10P-0221', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Some desert plants open their pores at night rather than during the day. The cooler air reduces water loss, and the plant stores the carbon it takes in until daylight. The strategy trades a slower process for a much smaller water bill, which matters where rain is rare.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To compare desert plants with rainforest species."}, {"id": "B", "text": "To explain how a night-time strategy reduces water loss in dry conditions."}, {"id": "C", "text": "To argue that opening pores at midday is more efficient."}, {"id": "D", "text": "To describe how desert plants store water in their leaves."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0221', 'B', ARRAY['B']::TEXT[], 'The passage links timing, temperature and water loss.', '{"D": "Storage of water is not described.", "C": "Midday opening would increase loss.", "A": "No rainforest comparison appears."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0222', 'HDSAT-RW-M10P-0222', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A clockmaker adjusts a pendulum''s length to change its period. A longer pendulum swings more slowly; a shorter one swings faster. Temperature matters too, because metal expands in warmth. Precision clocks therefore use alloys that change little with heat, or compensate with a second metal that expands in the opposite direction.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It states a basic relationship, introduces a complication, and describes two responses to it."}, {"id": "B", "text": "It argues that temperature has no effect on clocks."}, {"id": "C", "text": "It narrates the invention of the pendulum clock."}, {"id": "D", "text": "It lists the parts of a clock in the order they are assembled."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0222', 'A', ARRAY['A']::TEXT[], 'The period-length relation, thermal expansion, and two compensations build the paragraph.', '{"C": "No invention narrative appears.", "B": "Temperature is the complication.", "D": "No assembly order is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0223', 'HDSAT-RW-M10P-0223', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A farmer plants a cover crop after harvest. The roots hold soil through winter rains, and the plants add organic matter when they are turned in. The field looks idle, but the cover crop is working. Yield in the following season often rises even though nothing was harvested in between.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To explain the unseen benefits of a crop grown between harvests."}, {"id": "B", "text": "To describe how to harvest a cover crop for profit."}, {"id": "C", "text": "To compare two fertiliser brands."}, {"id": "D", "text": "To argue that bare soil is better for yields."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0223', 'A', ARRAY['A']::TEXT[], 'The passage explains what the cover crop does while looking idle.', '{"B": "Nothing is harvested from the cover crop.", "D": "Bare soil is the contrast case.", "C": "No brands are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0224', 'HDSAT-RW-M10P-0224', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'The first tests of a new vaccine measure immune response, not protection. A later trial follows thousands of people to see who becomes ill. The two stages answer different questions, and a strong immune response in the first does not guarantee success in the second. Reading the first result as a verdict is a common error.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It reports the results of a completed field trial."}, {"id": "B", "text": "It distinguishes two stages, explains what each measures, and warns against conflating them."}, {"id": "C", "text": "It argues that early trials are unnecessary."}, {"id": "D", "text": "It describes the manufacturing process of a vaccine."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0224', 'B', ARRAY['B']::TEXT[], 'The paragraph separates the two questions and names the mistake of merging them.', '{"D": "Manufacturing is not described.", "C": "Early trials are presented as one stage.", "A": "No results are reported."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0225', 'HDSAT-RW-M10P-0225', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A stone arch bridge carries load by compression. Each block pushes against its neighbors, and the curve directs the force into the abutments. The bridge can stand for centuries because the material is strong in compression. It fails when water scours the foundation and the abutments move, not because the stone crumbles.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares stone and steel bridges and prefers steel."}, {"id": "B", "text": "It argues that arches carry load in tension."}, {"id": "C", "text": "It explains the structural principle and then names the usual cause of failure."}, {"id": "D", "text": "It describes the construction sequence of a bridge."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0225', 'C', ARRAY['C']::TEXT[], 'The principle of compression is followed by scour as the failure mode.', '{"A": "No steel comparison appears.", "D": "Construction order is not given.", "B": "The passage specifies compression."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0226', 'HDSAT-RW-M10P-0226', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'An archive received a box of letters with no catalog. A conservator noted the paper, ink and postmarks before anyone read them. The postmarks placed the letters in three decades; the ink identified two writers. Reading came last, after the physical evidence had narrowed the possibilities.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes how paper is manufactured."}, {"id": "B", "text": "It argues that letters should be read before being examined."}, {"id": "C", "text": "It lists the contents of the box in detail."}, {"id": "D", "text": "It narrates a sequence in which physical analysis precedes reading."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0226', 'D', ARRAY['D']::TEXT[], 'The order of steps is the structure the question asks about.', '{"B": "Reading comes last in the passage.", "C": "Contents are summarized, not listed.", "A": "Manufacture is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0227', 'HDSAT-RW-M10P-0227', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A tidal flat looks uniform from a distance. Up close it holds channels, pools and patches of mud of different grain sizes. Each patch drains at a different rate, so the animals living in them experience different periods of exposure. A single square meter can contain several distinct habitats.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To list the species found on tidal flats."}, {"id": "B", "text": "To show how small-scale variation creates distinct habitats on a seemingly uniform flat."}, {"id": "C", "text": "To describe the tides that cover a flat twice a day."}, {"id": "D", "text": "To argue that grain size has no effect on drainage."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0227', 'B', ARRAY['B']::TEXT[], 'The contrast between distant and close views carries the point.', '{"C": "Tide timing is not the subject.", "D": "Grain size is tied to drainage.", "A": "Species are mentioned generally."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0228', 'HDSAT-RW-M10P-0228', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A baker''s starter failed after a move to a new city. The flour was different, and so was the water. Replacing the flour restored the rise within a week, which suggested that the water was not the problem. The starter had been selective about its food all along.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a problem, tests one cause, and draws a conclusion from the result."}, {"id": "B", "text": "It compares two cities and their baking traditions."}, {"id": "C", "text": "It argues that water quality never affects baking."}, {"id": "D", "text": "It lists the steps for making a starter from scratch."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0228', 'A', ARRAY['A']::TEXT[], 'The flour swap isolates the cause and produces the conclusion.', '{"B": "No traditions are compared.", "C": "Water is ruled out only after the flour test.", "D": "No recipe is given."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0229', 'HDSAT-RW-M10P-0229', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A lighthouse''s beam is narrow because a wide beam spreads its light too thin to be seen far. Rotating the beam sweeps the horizon, so a distant ship sees a flash rather than a steady glow. The flash pattern identifies the lighthouse, which is why each station has a different interval.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that a wide beam is easier to see at sea."}, {"id": "B", "text": "It explains a design choice, describes its effect, and states a further function of that effect."}, {"id": "C", "text": "It narrates the construction of a lighthouse tower."}, {"id": "D", "text": "It compares two lighthouses of different heights."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0229', 'B', ARRAY['B']::TEXT[], 'Narrow beam, rotation and identifying flash build on one another.', '{"C": "Construction is not described.", "A": "A wide beam spreads light too thin.", "D": "Heights are not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0230', 'HDSAT-RW-M10P-0230', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A museum once displayed a bronze horse without its stand because the stand was thought to be a later addition. Analysis of the metal showed the stand and the horse were cast together. The display was changed, and the label now explains that the two parts belong to one object.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To argue that museum labels are never revised."}, {"id": "B", "text": "To show how material analysis corrected an assumption about an object''s parts."}, {"id": "C", "text": "To describe the process of casting bronze."}, {"id": "D", "text": "To compare two bronze horses from different museums."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0230', 'B', ARRAY['B']::TEXT[], 'The passage contrasts an old assumption with the analysis that overturned it.', '{"C": "Casting technique is not explained.", "A": "A revision is the subject.", "D": "One object is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0231', 'HDSAT-RW-M10P-0231', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A floodplain is not wasted land. When a river overtops its banks, the water slows and drops sediment that renews the soil. The same flood that damages a road may improve a field. Building levees everywhere removes the benefit along with the risk, which is why some rivers are now reconnected to their floodplains.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It lists the costs of flooding without mentioning benefits."}, {"id": "B", "text": "It describes the geology of a river delta."}, {"id": "C", "text": "It argues that levees are the only sensible flood policy."}, {"id": "D", "text": "It challenges a common view, explains a benefit, and describes a policy response."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0231', 'D', ARRAY['D']::TEXT[], 'The opening reframing leads to the sediment benefit and the reconnection policy.', '{"C": "Levees are presented as removing a benefit.", "B": "Delta geology is not described.", "A": "Benefits are central to the passage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0232', 'HDSAT-RW-M10P-0232', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A new telescope''s mirror is made of many hexagonal segments. Each segment is adjusted by actuators so that the whole surface behaves as one curve. A single large mirror would be too heavy to launch, so the design trades complexity on the ground for a lighter payload in orbit.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the launch sequence of a rocket."}, {"id": "B", "text": "It explains a design, describes how it works, and states the trade-off that motivated it."}, {"id": "C", "text": "It argues that a single large mirror is easier to launch."}, {"id": "D", "text": "It compares the images from two telescopes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0232', 'B', ARRAY['B']::TEXT[], 'Segment design, actuation and the launch-weight trade-off structure the passage.', '{"A": "No launch sequence appears.", "C": "A single mirror is too heavy.", "D": "No images are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0233', 'HDSAT-RW-M10P-0233', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A seed catalog lists a tomato as resistant to a disease. Resistance does not mean immunity: the plant may still show symptoms under heavy pressure. Gardeners who read the label as a guarantee are disappointed, though the variety may still outperform others in the same bed.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To argue that resistant varieties never show symptoms."}, {"id": "B", "text": "To compare two tomato varieties for flavour."}, {"id": "C", "text": "To clarify a term that is easily misread as a stronger promise than it is."}, {"id": "D", "text": "To describe how to grow tomatoes from seed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0233', 'C', ARRAY['C']::TEXT[], 'The passage defines resistance against a common misreading.', '{"D": "Growing instructions are absent.", "A": "Symptoms can still appear.", "B": "Flavour is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0234', 'HDSAT-RW-M10P-0234', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A choral conductor asks singers to breathe in the same place in a phrase. The instruction is not about stamina. A shared breath makes the consonants land together, which is what the audience hears as precision. The technique is therefore about ensemble rather than endurance.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It states an instruction, rejects an obvious explanation, and gives the real one."}, {"id": "B", "text": "It explains how to train a solo voice."}, {"id": "C", "text": "It argues that singers should breathe whenever they choose."}, {"id": "D", "text": "It describes the history of choral music."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0234', 'A', ARRAY['A']::TEXT[], 'The passage moves from instruction to rejected reason to the ensemble explanation.', '{"D": "No history is given.", "C": "Shared breathing is the instruction.", "B": "The focus is ensemble, not solo training."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0235', 'HDSAT-RW-M10P-0235', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A concrete path cracks because it is restrained at the edges while the slab expands in heat. The crack relieves the stress at one point but concentrates it at the ends. A line of joints cut across the path gives the concrete places to move, so the cracks form where they were planned instead of randomly.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains a failure, describes how it propagates, and presents a design that controls it."}, {"id": "B", "text": "It describes the mixing of a concrete batch."}, {"id": "C", "text": "It compares two kinds of concrete and ranks their strength."}, {"id": "D", "text": "It argues that joints make cracking worse."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0235', 'A', ARRAY['A']::TEXT[], 'Cause, propagation and control joints form the sequence.', '{"C": "No strength ranking appears.", "D": "Joints control where cracks form.", "B": "Mixing is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0236', 'HDSAT-RW-M10P-0236', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A historian reading a merchant''s ledger noticed that the same cargo was recorded twice, once on departure and once on arrival. The two entries differ by a small amount, which probably reflects loss in transit. Such gaps, collected across many voyages, can estimate how much cargo never reached port.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two merchants and their profits."}, {"id": "B", "text": "It argues that ledgers are too unreliable to use."}, {"id": "C", "text": "It narrates a single voyage from departure to arrival."}, {"id": "D", "text": "It describes a detail in a source and explains how that detail can be used at scale."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0236', 'D', ARRAY['D']::TEXT[], 'A small discrepancy becomes a method when aggregated over many records.', '{"C": "No voyage narrative is given.", "B": "The ledger is used, not dismissed.", "A": "One merchant is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0237', 'HDSAT-RW-M10P-0237', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Some spiders build webs that reflect ultraviolet light. Insects see ultraviolet, so the web appears as a bright pattern to them while remaining nearly invisible to birds that might tear through it. The silk is not decorative; it is tuned to the vision of a particular audience.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To explain how a web''s appearance is shaped by the vision of different animals."}, {"id": "B", "text": "To describe how spiders spin silk threads."}, {"id": "C", "text": "To argue that birds are attracted to ultraviolet webs."}, {"id": "D", "text": "To compare the strength of two kinds of spider silk."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0237', 'A', ARRAY['A']::TEXT[], 'The UV reflection is explained by what insects and birds can see.', '{"B": "Spinning is not described.", "C": "Birds see the web as nearly invisible.", "D": "Strength is not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0238', 'HDSAT-RW-M10P-0238', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A town''s water supply came from a spring above the town. The pipe ran downhill, so no pump was needed, but the pressure at the top of the hill was too low for firefighting. A second tank halfway up solved the problem by holding water at a height that gave pressure without a pump.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that pumps are always necessary."}, {"id": "B", "text": "It describes a system, names a shortcoming, and explains the remedy."}, {"id": "C", "text": "It compares two towns and their water supplies."}, {"id": "D", "text": "It describes the construction of a spring house."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0238', 'B', ARRAY['B']::TEXT[], 'Gravity feed, weak pressure uphill, and a mid-level tank form the sequence.', '{"C": "One town is discussed.", "A": "The solutions avoid pumps.", "D": "No spring house is described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0239', 'HDSAT-RW-M10P-0239', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A paper was retracted after readers found that two figures were identical. The authors said the duplication was an error in assembling the manuscript. The journal''s notice did not decide intent, only that the published record could no longer be relied on. Correction and misconduct are separate questions.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that every retraction proves misconduct."}, {"id": "B", "text": "It compares two journals and their retraction policies."}, {"id": "C", "text": "It describes how to assemble figures for publication."}, {"id": "D", "text": "It reports an event, notes the authors'' explanation, and distinguishes two issues the notice leaves separate."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0239', 'D', ARRAY['D']::TEXT[], 'The final sentence draws the distinction the notice preserves.', '{"A": "The passage separates correction from misconduct.", "C": "Figure assembly is mentioned but not explained.", "B": "One journal is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0240', 'HDSAT-RW-M10P-0240', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A beekeeper inspects a hive less often in winter. Opening the hive releases heat the colony has stored, and the bees must spend energy replacing it. A quick check may cost less than a cold night. The timing of an inspection is therefore a calculation, not a habit.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a practice and explains the cost that justifies it."}, {"id": "B", "text": "It compares two species of bee."}, {"id": "C", "text": "It argues that hives should be opened daily in winter."}, {"id": "D", "text": "It describes how bees make honey."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0240', 'A', ARRAY['A']::TEXT[], 'The heat cost explains why inspections are rationed.', '{"D": "Honey making is not described.", "C": "The passage recommends less frequent inspection.", "B": "One species is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0241', 'HDSAT-RW-M10P-0241', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A geologist found shells on a mountain top. The shells are marine, and the rock around them formed under water. The explanation is not that the sea once reached this height, but that the rock was lifted. Uplift is slow, which is why the shells remain intact rather than being crushed.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares two mountain ranges."}, {"id": "B", "text": "It argues that the shells were carried up by birds."}, {"id": "C", "text": "It narrates a climb to a mountain summit."}, {"id": "D", "text": "It poses an observation, rejects one explanation, and supplies another with supporting detail."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0241', 'D', ARRAY['D']::TEXT[], 'The observation, rejected sea-level explanation and uplift account form the structure.', '{"C": "No climb is described.", "B": "Birds are not mentioned.", "A": "One location is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0242', 'HDSAT-RW-M10P-0242', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A violin maker chooses wood for how it rings when tapped. A plate that rings too long sounds hollow under the bow; one that dies quickly sounds thin. The maker removes wood from the edges until the tap tone falls into a range learned from experience rather than measured on a scale.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To argue that tap tone is irrelevant to violin sound."}, {"id": "B", "text": "To explain a judgement made by ear rather than by measurement."}, {"id": "C", "text": "To describe the chemical treatment of violin varnish."}, {"id": "D", "text": "To compare two famous violin makers."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0242', 'B', ARRAY['B']::TEXT[], 'The passage contrasts an experienced ear with a measured scale.', '{"C": "Varnish is not discussed.", "A": "Tap tone is central.", "D": "No makers are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0243', 'HDSAT-RW-M10P-0243', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A long drought exposed a submerged bridge in a reservoir. The bridge was built before the valley was flooded and had been underwater for sixty years. Its piers were intact, but the deck had sagged where water had entered the joints. The reservoir''s low level turned a hidden structure into a visible record of its own construction.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that the bridge should never have been flooded."}, {"id": "B", "text": "It lists the materials used in bridge piers."}, {"id": "C", "text": "It begins with a chance event and uses it to describe what the revealed structure shows."}, {"id": "D", "text": "It describes the engineering of reservoir dams."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0243', 'C', ARRAY['C']::TEXT[], 'The drought is the occasion; the bridge''s condition is the content.', '{"A": "No judgement about flooding is offered.", "D": "Dams are not described.", "B": "Materials are not listed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0244', 'HDSAT-RW-M10P-0244', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A museum''s textile gallery dims its lights. Dyes fade in proportion to the light they receive, and a year of bright display can do more damage than a century in a drawer. Visitors sometimes complain about the gloom, but the alternative is the gradual disappearance of the objects they came to see.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that bright lighting preserves textiles."}, {"id": "B", "text": "It compares two museums and their visitor numbers."}, {"id": "C", "text": "It explains a policy, gives its rationale, and acknowledges a cost."}, {"id": "D", "text": "It describes the manufacture of natural dyes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0244', 'C', ARRAY['C']::TEXT[], 'Dim lighting, the fading mechanism and the visitor complaint complete the structure.', '{"A": "Light causes fading.", "D": "Dye manufacture is not described.", "B": "Visitor numbers are not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0245', 'HDSAT-RW-M10P-0245', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A new bridge was built beside the old one rather than on its site. Keeping the old bridge open during construction meant traffic never stopped, but it also meant the new structure had to fit a narrower corridor. The builders accepted the constraint because the alternative was months of closure.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a decision and explains the trade-off that justified it."}, {"id": "B", "text": "It compares the cost of two bridges in detail."}, {"id": "C", "text": "It narrates the failure of the old bridge."}, {"id": "D", "text": "It argues that road closures are always preferable."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0245', 'A', ARRAY['A']::TEXT[], 'The siting decision and its traffic trade-off are the passage''s content.', '{"B": "No cost figures are given.", "C": "The old bridge stayed open.", "D": "Closures are the alternative that was avoided."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0246', 'HDSAT-RW-M10P-0246', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A seed''s size limits how far the wind can carry it. Small, winged seeds travel far but carry little stored food, so a seedling must establish quickly. Large seeds land near the parent but have reserves to survive shade. The trade-off shapes which species colonise open ground and which persist in closed forest.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It states a constraint, contrasts two strategies, and draws a consequence for where species grow."}, {"id": "B", "text": "It argues that large seeds travel farther than small ones."}, {"id": "C", "text": "It lists the animals that disperse seeds."}, {"id": "D", "text": "It describes the anatomy of a seed in detail."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0246', 'A', ARRAY['A']::TEXT[], 'Size, dispersal and establishment lead to the habitat conclusion.', '{"D": "Anatomy is not the subject.", "B": "Small winged seeds travel farther.", "C": "No animals are listed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0247', 'HDSAT-RW-M10P-0247', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'An archaeologist found a hearth with ash, burnt bone and a ring of stones. The stones were not local. Analysis matched them to a riverbed two days'' walk away. The hearth therefore records not only a fire but a decision to carry heavy material to a place where it was wanted.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates a journey to a riverbed."}, {"id": "B", "text": "It compares two hearths from different sites."}, {"id": "C", "text": "It presents evidence, links it to a distant source, and infers deliberate behavior."}, {"id": "D", "text": "It argues that the stones arrived by natural transport."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0247', 'C', ARRAY['C']::TEXT[], 'Evidence, provenance and inference about effort form the structure.', '{"A": "The journey is inferred, not narrated.", "D": "The analysis ties the stones to the riverbed.", "B": "One hearth is discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0248', 'HDSAT-RW-M10P-0248', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A textile printer tests a dye on a scrap before committing a whole bolt. The scrap is washed, dried and exposed to light in conditions harsher than ordinary use. If the color survives that, the bolt is printed. The test is a small, deliberate failure used to prevent a large one.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To explain why a small destructive test protects a larger investment."}, {"id": "B", "text": "To argue that testing scraps is a waste of material."}, {"id": "C", "text": "To describe how dye is extracted from plants."}, {"id": "D", "text": "To compare two printing machines."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0248', 'A', ARRAY['A']::TEXT[], 'The last sentence states the logic of the sample test.', '{"C": "Extraction is not described.", "B": "The test prevents loss.", "D": "No machines are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0249', 'HDSAT-RW-M10P-0249', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A city planted trees along a new road. Within five years, half had died, mostly in the pits cut into compacted ground. The failures were not caused by drought or disease but by roots unable to spread beyond the pit. Later plantings broke the surrounding compaction before planting.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It reports an outcome, rules out two explanations, and identifies the real cause."}, {"id": "B", "text": "It narrates the construction of the road."}, {"id": "C", "text": "It lists the species of trees planted."}, {"id": "D", "text": "It argues that tree pits are the best place to plant."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0249', 'A', ARRAY['A']::TEXT[], 'Mortality, rejected causes and compaction form the paragraph.', '{"B": "Road construction is incidental.", "D": "Pits are the problem.", "C": "Species are not listed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0250', 'HDSAT-RW-M10P-0250', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'A stone tool''s edge dulls at a rate that depends on what it cuts. Microscopic wear on a blade can distinguish hide from wood from bone. An archaeologist can therefore infer what a tool was used for without finding the material it worked on. The evidence is the surface, not the residue.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To compare two archaeological sites."}, {"id": "B", "text": "To argue that tools cannot reveal their function."}, {"id": "C", "text": "To describe how stone tools are made."}, {"id": "D", "text": "To explain how wear patterns on a tool reveal its past use."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0250', 'D', ARRAY['D']::TEXT[], 'The passage explains wear analysis and its inferential reach.', '{"C": "Manufacture is not described.", "B": "Function is the subject.", "A": "No sites are compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0251', 'HDSAT-RW-M10P-0251', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A wick must be the right size for a candle. Too small and the flame starves; too large and it smokes, leaving soot on the glass. Candle makers match wick diameter to the wax and the container. A wick that works in one candle may fail in another of the same height.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the history of candle making."}, {"id": "B", "text": "It argues that one wick size suits every candle."}, {"id": "C", "text": "It describes a requirement, gives failure modes, and concludes that the choice is specific."}, {"id": "D", "text": "It describes how wax is refined."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0251', 'C', ARRAY['C']::TEXT[], 'Requirement, failure modes and the specificity conclusion build the text.', '{"A": "No history is given.", "B": "The passage says a wick can fail in another candle.", "D": "Wax refining is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0252', 'HDSAT-RW-M10P-0252', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'An island''s birds were larger than their mainland relatives. With no ground predators, large size was not a liability. When people introduced rats, the largest ground-nesting species vanished first. Size had been an advantage that became a disadvantage in one generation.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a pattern, explains its original cause, and shows how a new factor reversed it."}, {"id": "B", "text": "It lists the predators introduced to the island."}, {"id": "C", "text": "It argues that island birds are always smaller than mainland birds."}, {"id": "D", "text": "It compares two islands and their climates."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0252', 'A', ARRAY['A']::TEXT[], 'Advantage, explanation and reversal form the arc.', '{"D": "Only one island is discussed.", "C": "The passage says the birds were larger.", "B": "One predator is named, not listed as a group."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0253', 'HDSAT-RW-M10P-0253', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A manuscript''s margins are wide because the skin was expensive and the scribe planned them. Ruling lines left faint grooves that are still visible. The widths are consistent across a whole scriptorium, which suggests a standard rather than an individual choice. The page layout is therefore evidence of workshop practice.', 'Which choice best describes the purpose of the text?', '[{"id": "A", "text": "To describe the animals whose skin was used."}, {"id": "B", "text": "To argue that margins were always random."}, {"id": "C", "text": "To compare two scribes and their handwriting."}, {"id": "D", "text": "To show how a page''s physical features can reveal how it was produced."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0253', 'D', ARRAY['D']::TEXT[], 'Margins and ruling grooves are read as evidence of workshop standards.', '{"A": "Animals are not described.", "B": "The widths are consistent.", "C": "Handwriting is not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10P-0254', 'HDSAT-RW-M10P-0254', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A wing''s shape produces lift because air moves faster over the curved upper surface. That faster air has lower pressure, and the difference pushes the wing upward. The explanation is often simplified as a longer path over the top, but the length of the path is not what matters. Pressure, not distance, does the work.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It lists the forces acting on a paper plane."}, {"id": "B", "text": "It argues that wing shape has no effect on lift."}, {"id": "C", "text": "It states a mechanism, corrects a popular version of it, and names the real cause."}, {"id": "D", "text": "It describes the history of aviation in order."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10P-0254', 'C', ARRAY['C']::TEXT[], 'The passage presents the pressure difference and corrects the equal-transit explanation.', '{"D": "No history is given.", "B": "Shape produces lift in the passage.", "A": "No forces are listed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
