INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10S-0000', 'D', ARRAY['D']::TEXT[], 'The correct choice selects the notes that serve the stated goal and states them precisely; the others either miss the goal or add unsupported detail.', '{"C": "This choice reports only the hottest group, so it does not compare the two groups.", "B": "This choice describes the method and its limits rather than the size of the difference.", "A": "This choice describes canopy coverage without mentioning any temperature."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
