INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10S-0004', 'A', ARRAY['A']::TEXT[], 'The correct choice selects the notes that serve the stated goal and states them precisely; the others either miss the goal or add unsupported detail.', '{"D": "This choice states how long the walls lasted but not why they lasted.", "C": "This choice identifies the mineral without explaining its strengthening effect.", "B": "This choice describes modern concrete rather than the Roman material."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
