INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10S-0005', 'A', ARRAY['A']::TEXT[], 'The correct choice selects the notes that serve the stated goal and states them precisely; the others either miss the goal or add unsupported detail.', '{"B": "This choice explains the mechanism but does not describe the recovery.", "D": "This choice reports only the loss, not what happened afterward.", "C": "This choice gives the final area without the loss it recovered from, so the completeness is unclear."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
