INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10Q-0000', 'HDSAT-RW-M10Q-0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A team of ecologists recorded the number of nesting pairs at four restored wetlands. The measurements were collected in 2019 across the northern catchment as part of survey 001, and the results are summarized in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "All four wetlands recorded the same nesting pairs."}, {"id": "B", "text": "Wetland North recorded the highest nesting pairs, at 18."}, {"id": "C", "text": "Wetland South recorded the highest nesting pairs, at 27."}, {"id": "D", "text": "Wetland West recorded the highest nesting pairs, at 33."}]'::jsonb, '{"type": "table", "caption": "Nesting pairs by wetland", "headers": ["Wetland", "nesting pairs"], "rows": [["Wetland North", "18"], ["Wetland South", "27"], ["Wetland East", "22"], ["Wetland West", "33"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10Q-0000', 'D', ARRAY['D']::TEXT[], 'The table gives 33 for Wetland West, more than any other row; the next highest is 27 for Wetland South.', '{"C": "This option misreads the table: another row or year is higher.", "B": "This option names a value that does not appear in the data.", "A": "This option claims a pattern the data do not show."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10Q-0001', 'HDSAT-RW-M10Q-0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A soil lab measured the percentage of organic matter in four field plots. The measurements were collected in 2024 across the lower river valley as part of survey 002, and the results are summarized in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "Plot West was the highest at 51, 12 above Plot South."}, {"id": "B", "text": "Plot South was the lowest at 39."}, {"id": "C", "text": "Plot North was the highest at 28."}, {"id": "D", "text": "Plot West and Plot South recorded identical values."}]'::jsonb, '{"type": "bar_chart", "caption": "Organic matter (%) by plot", "x_label": "Plot", "y_label": "organic matter (%)", "series": [{"label": "North", "value": 28}, {"label": "South", "value": 39}, {"label": "East", "value": 31}, {"label": "West", "value": 51}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10Q-0001', 'A', ARRAY['A']::TEXT[], 'The tallest bar is Plot West at 51; Plot North is the smallest at 28.', '{"C": "This option misreads the graph: another row or year is higher.", "D": "This option names a value that does not appear in the data.", "B": "This option claims a pattern the data do not show."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10Q-0002', 'HDSAT-RW-M10Q-0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A transport survey counted daily bicycle crossings on four city bridges. The measurements were collected in 2023 across a small island group as part of survey 003, and the results are summarized in the graph.', 'Which choice best describes the trend shown in the graph?', '[{"id": "A", "text": "It fell steadily from 2020 to 2023 without ever rising."}, {"id": "B", "text": "It rose to a peak of 52 in 2022 and then declined slightly in 2023."}, {"id": "C", "text": "It peaked in 2020 at 38."}, {"id": "D", "text": "It stayed exactly the same in every year shown."}]'::jsonb, '{"type": "line_chart", "caption": "Daily crossings at bridge West over four years", "x_label": "Year", "y_label": "daily crossings", "series": [{"label": "2020", "value": 38}, {"label": "2021", "value": 51}, {"label": "2022", "value": 52}, {"label": "2023", "value": 50}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set,